    {"id": "q-f203-g01-050", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which findings fit a pneumothorax?", "choices": ["Absent breath sounds, trachea away, hyperresonance", "Bronchial sounds, dullness, ↑ fremitus", "Wheezing and hyperresonance only", "Crackles and dullness"], "correct": 0, "explanation": "Pneumothorax: absent sounds, tracheal shift away, hyperresonant.", "srcItem": "Breath Sounds by Condition"},
    {"id": "q-f203-g01-051", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which findings fit atelectasis?", "choices": ["Diminished sounds, trachea toward the affected side, dullness", "Absent sounds, trachea away, hyperresonance", "Wheezing and hyperresonance", "Stridor"], "correct": 0, "explanation": "Atelectasis pulls the trachea toward the collapse; dull percussion.", "srcItem": "Breath Sounds by Condition"},
    {"id": "q-f203-g01-052", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which breath sounds does Hess give for emphysema?", "choices": ["Decreased or absent, with no adventitious sounds", "Bronchial with crackles", "Stridor", "Pleural rub"], "correct": 0, "explanation": "Hess Table 1-3: emphysema = decreased or absent, no adventitious sounds.", "srcItem": "Breath Sounds by Condition"},
    {"id": "q-f203-g01-053", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is orthopnea?", "choices": ["Difficult breathing when lying down, relieved by sitting up", "Difficult breathing only when upright", "Breathing that waxes and wanes", "Rapid deep breathing"], "correct": 0, "explanation": "Orthopnea: uncomfortable breathing when lying down, relieved by sitting/standing.", "srcItem": "Orthopnea"},
    {"id": "q-f203-g01-054", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why does lying flat worsen breathing in CHF?", "choices": ["Venous return increases and fluid redistributes into the lungs", "Lung compliance rises", "The diaphragm becomes stronger", "Cardiac output doubles"], "correct": 0, "explanation": "Supine: blood shifts centrally, filling pressures rise, interstitial edema forms.", "srcItem": "Orthopnea"},
    {"id": "q-f203-g01-055", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How can orthopnea be assessed at the bedside?", "choices": ["Ask how many pillows the patient sleeps on", "Measure the PaO₂ supine only", "Check the gag reflex", "Count the heart rate"], "correct": 0, "explanation": "Hess: orthopnea may be hidden in a patient sleeping on two or three pillows.", "srcItem": "Orthopnea"},
    {"id": "q-f203-g01-056", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How soon after falling asleep does paroxysmal nocturnal dyspnea wake the patient (exam answer)?", "choices": ["1–2 hours", "5 minutes", "8 hours", "Only in the morning"], "correct": 0, "explanation": "Use 1–2 hours; PND commonly suggests cardiac dysfunction.", "srcItem": "Orthopnea"},
    {"id": "q-f203-g01-057", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is platypnea?", "choices": ["Difficulty breathing unless lying flat", "Difficulty breathing when lying flat", "Apnea during sleep", "Deep rapid breathing"], "correct": 0, "explanation": "Hess: platypnea is the opposite of orthopnea.", "srcItem": "Orthopnea"},
    {"id": "q-f203-g01-058", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which pattern is deep and fast, regular, without apnea, and caused by metabolic acidosis?", "choices": ["Kussmaul", "Cheyne-Stokes", "Biot's", "Apneustic"], "correct": 0, "explanation": "Kussmaul: compensatory hyperventilation for DKA or severe metabolic acidosis.", "srcItem": "Kussmaul vs Cheyne-Stokes vs Biot"},
    {"id": "q-f203-g01-059", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which pattern waxes and wanes in a crescendo–decrescendo cycle with apnea?", "choices": ["Cheyne-Stokes", "Kussmaul", "Biot's", "Tachypnea"], "correct": 0, "explanation": "Cheyne-Stokes: CHF, stroke, brain injury, central sleep apnea.", "srcItem": "Kussmaul vs Cheyne-Stokes vs Biot"},
    {"id": "q-f203-g01-060", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which pattern has irregular breaths of equal tidal volume followed by apnea?", "choices": ["Biot's", "Cheyne-Stokes", "Kussmaul", "Eupnea"], "correct": 0, "explanation": "Biot's: CNS injury, ↑ ICP, brainstem damage, meningitis.", "srcItem": "Kussmaul vs Cheyne-Stokes vs Biot"},
    {"id": "q-f203-g01-061", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How do Biot's and Cheyne-Stokes breathing differ?", "choices": ["Biot's breaths are equal in size; Cheyne-Stokes breaths build and fade", "Both have equal breaths", "Biot's never has apnea", "Cheyne-Stokes is caused only by DKA"], "correct": 0, "explanation": "Biot's points to brainstem involvement and more severe neurologic dysfunction.", "srcItem": "Kussmaul vs Cheyne-Stokes vs Biot"},
    {"id": "q-f203-g01-062", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "For the exam, how is Kussmaul breathing described?", "choices": ["Deep and fast (rapid)", "Deep with reduced frequency", "Shallow and slow", "Irregular with apnea"], "correct": 0, "explanation": "Use the deck's deep and fast (Hess Ch 4's 'normal or reduced frequency' is the outlier).", "srcItem": "Kussmaul vs Cheyne-Stokes vs Biot"},
    {"id": "q-f203-g01-063", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why does Kussmaul breathing occur?", "choices": ["To blow off CO₂ and compensate for metabolic acidosis", "To raise the PaCO₂", "Because of brainstem damage", "Because of airway obstruction"], "correct": 0, "explanation": "Expelling CO₂ reduces acid; in the DKA case the compensation is only partial.", "srcItem": "Why each pattern happens"},
    {"id": "q-f203-g01-064", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What causes Cheyne-Stokes breathing in CHF?", "choices": ["Delayed circulation time makes the brain respond to CO₂ changes too late", "Excess surfactant", "Airway obstruction", "Metabolic alkalosis"], "correct": 0, "explanation": "The brain keeps overcorrecting because the CO₂ signal arrives late.", "srcItem": "Why each pattern happens"},
    {"id": "q-f203-g01-065", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How common is Cheyne-Stokes breathing in CHF patients (Hess)?", "choices": ["25–40%", "1–2%", "90–100%", "Never seen"], "correct": 0, "explanation": "Hess Ch 45: CSB in 25–40% of CHF patients; treat by improving cardiac function.", "srcItem": "Why each pattern happens"},
    {"id": "q-f203-g01-066", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which way does the trachea shift with atelectasis?", "choices": ["Toward the affected side", "Away from the affected side", "It never shifts", "Upward"], "correct": 0, "explanation": "\"Toward loss / Away from pressure\": volume loss pulls the trachea.", "srcItem": "Tracheal shift: which way, and what causes it"},
    {"id": "q-f203-g01-067", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which conditions push the trachea away from the affected side?", "choices": ["Tension pneumothorax and large pleural effusion", "Atelectasis and fibrosis", "Surgical resection", "Pneumonia without effusion"], "correct": 0, "explanation": "Space-occupying processes push the trachea away.", "srcItem": "Tracheal shift: which way, and what causes it"},
    {"id": "q-f203-g01-068", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is tracheal position checked at the bedside?", "choices": ["Index finger at the sternal notch, moved gently side to side", "With a stethoscope over the heart", "By chest radiograph only", "By measuring neck circumference"], "correct": 0, "explanation": "RCP 103: the trachea is normally midline above the sternal notch.", "srcItem": "Tracheal shift: which way, and what causes it"},
    {"id": "q-f203-g01-069", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why shouldn't you wait for tracheal deviation to treat a suspected tension pneumothorax?", "choices": ["It is a late and unreliable finding", "It appears first in every case", "It means the pneumothorax resolved", "It only occurs in children"], "correct": 0, "explanation": "Treat based on distress, unilateral ↓ sounds and instability.", "srcItem": "Tracheal shift: which way, and what causes it"},
    {"id": "q-f203-g01-070", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is paradoxical breathing?", "choices": ["The chest or abdomen moves in on inhalation and out on exhalation", "Normal outward movement on inspiration", "Breathing with long pauses", "Breathing through pursed lips"], "correct": 0, "explanation": "It signals respiratory distress and high WOB.", "srcItem": "Paradoxical breathing"},
    {"id": "q-f203-g01-071", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "The abdomen moves inward on inspiration. What does this suggest?", "choices": ["Diaphragm weakness or paralysis", "Normal breathing", "Bronchospasm", "Pleural effusion"], "correct": 0, "explanation": "Hess: abdominal paradox = diaphragm weakness; chest wall paradox = chest wall muscle paralysis or flail.", "srcItem": "Paradoxical breathing"},
    {"id": "q-f203-g01-072", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Thoracoabdominal paradox appears during an SBT. What should be done?", "choices": ["Stop the SBT", "Continue for 2 more hours", "Extubate", "Decrease the FiO₂"], "correct": 0, "explanation": "Paradox is an early sign of weaning failure.", "srcItem": "Paradoxical breathing"},
    {"id": "q-f203-g01-073", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does the deck define flail chest?", "choices": ["Three or more ribs fractured in two or more places, a sternal fracture or costochondral separation", "One rib fractured in one place", "Any bruise on the chest", "Two ribs bruised"], "correct": 0, "explanation": "Use the deck's three or more (Hess says two or more).", "srcItem": "Flail chest"},
    {"id": "q-f203-g01-074", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does a flail segment move?", "choices": ["In on inspiration and out on exhalation", "Out on inspiration and in on exhalation", "It does not move", "Only during coughing"], "correct": 0, "explanation": "Negative intrapleural pressure draws the segment in on inspiration.", "srcItem": "Flail chest"},
    {"id": "q-f203-g01-075", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why can a pulmonary contusion with flail chest worsen?", "choices": ["It may 'blossom' over 24–48 hours", "It always resolves in an hour", "It is never present", "It improves with fluids"], "correct": 0, "explanation": "Contusions worsen over 24–48 h; consider early elective intubation.", "srcItem": "Flail chest"},
    {"id": "q-f203-g01-076", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Does every flail chest patient need intubation?", "choices": ["No — treat with pain control, hygiene and O₂, ventilating when necessary", "Yes, always", "Only children", "Only if a rib is broken"], "correct": 0, "explanation": "Not every flail patient needs intubation or MV.", "srcItem": "Flail chest"},
    {"id": "q-f203-g01-077", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does a tension pneumothorax differ from a simple one?", "choices": ["Tension compromises both breathing and circulation", "Tension affects only breathing", "Simple pneumothorax causes shock", "They are identical"], "correct": 0, "explanation": "One-way valve → rising pressure → ↓ venous return → obstructive shock.", "srcItem": "Tension Pneumothorax (4)"},
    {"id": "q-f203-g01-078", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On volume control, what ventilator sign suggests a tension pneumothorax?", "choices": ["A sudden increase in airway pressure", "A sudden fall in PEEP", "A gradual fall in PIP", "No change"], "correct": 0, "explanation": "VC: sudden ↑ pressure; PC: sudden ↓ VT.", "srcItem": "Tension Pneumothorax (4)"},
    {"id": "q-f203-g01-079", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What should be recommended when tension pneumothorax is suspected and life-threatening?", "choices": ["Immediate needle decompression or a chest tube", "A CXR before any action", "Bronchoscopy", "Increase the PEEP"], "correct": 0, "explanation": "Also 100% O₂ and lower PIP/VT if on PPV.", "srcItem": "Tension Pneumothorax (4)"},
    {"id": "q-f203-g01-080", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why does 100% O₂ help a small pneumothorax resolve?", "choices": ["It washes out nitrogen, speeding reabsorption of pleural air", "It inflates the lung directly", "It seals the leak", "It raises the pleural pressure"], "correct": 0, "explanation": "Nitrogen washout lowers pleural gas pressure; no substitute for decompression under tension.", "srcItem": "Tension Pneumothorax (4)"},
    {"id": "q-f203-g01-081", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where is a needle thoracostomy performed per the Ch 15 deck?", "choices": ["2nd intercostal space, midclavicular line", "8th ICS posterior line", "5th ICS midclavicular line", "Below the xiphoid"], "correct": 0, "explanation": "Insert over the top of the third rib; then prepare for a chest tube.", "srcItem": "Tension Pneumothorax (5)"},
    {"id": "q-f203-g01-082", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is attached to the angiocath after needle decompression?", "choices": ["A flutter (Heimlich) valve", "A water-seal drainage system", "An oxygen flowmeter", "A suction catheter"], "correct": 0, "explanation": "A Heimlich valve is a one-way valve; its arrow points away from the patient.", "srcItem": "Tension Pneumothorax (5)"},
    {"id": "q-f203-g01-083", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which patients are predisposed to tension pneumothorax?", "choices": ["Patients on MV with airway pressures over 40–45 cm H₂O", "Patients on nasal cannula", "Patients with normal lungs at rest", "Patients with low PEEP only"], "correct": 0, "explanation": "Also chest trauma and very high compliance (advanced emphysema).", "srcItem": "Tension Pneumothorax (5)"},
    {"id": "q-f203-g01-084", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which CXR findings fit a tension pneumothorax?", "choices": ["Hyperlucent pleural space, collapsed lung, mediastinal shift to the opposite side", "Bilateral fluffy infiltrates", "Blunted costophrenic angles only", "Elevated diaphragm with volume loss"], "correct": 0, "explanation": "Also flattened diaphragm and widened rib spaces on the affected side.", "srcItem": "Tension Pneumothorax (5)"},
    {"id": "q-f203-g01-085", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Using the Ch 15 deck, which heart rate triggers a rapid response call?", "choices": ["> 130/min or < 40/min", "> 100/min", "< 60/min", "> 180/min only"], "correct": 0, "explanation": "Deck: HR < 40 or > 130 (Hess: > 140).", "srcItem": "The Ch 15 Deck’s MET / RRT Activation Criteria"},
    {"id": "q-f203-g01-086", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Using the Ch 15 deck, which respiratory rate triggers a rapid response call?", "choices": ["< 8 or > 30/min", "> 20/min", "< 12/min", "> 40/min only"], "correct": 0, "explanation": "Deck: RR < 8 or > 30 (Hess: > 28).", "srcItem": "The Ch 15 Deck’s MET / RRT Activation Criteria"},
    {"id": "q-f203-g01-087", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which SpO₂ triggers a MET call in the Ch 15 deck?", "choices": ["< 90%, especially on supplemental O₂", "< 95% on room air", "< 80% only", "< 99%"], "correct": 0, "explanation": "Deck: SpO₂ < 90% (Hess: < 89% despite O₂).", "srcItem": "The Ch 15 Deck’s MET / RRT Activation Criteria"},
    {"id": "q-f203-g01-088", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which urine output triggers a rapid response call?", "choices": ["< 50 mL over 4 hours", "< 500 mL over 24 hours only", "< 1 L per hour", "Any amount"], "correct": 0, "explanation": "Both sources agree: < 50 mL over 4 hours.", "srcItem": "The Ch 15 Deck’s MET / RRT Activation Criteria"},
    {"id": "q-f203-g01-089", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which systolic BP triggers a call in the Ch 15 deck?", "choices": ["< 90 mm Hg", "> 140 mm Hg", "< 110 mm Hg", "> 160 mm Hg"], "correct": 0, "explanation": "Deck: SBP < 90 (no high-BP trigger); Hess adds > 180.", "srcItem": "The Ch 15 Deck’s MET / RRT Activation Criteria"},
    {"id": "q-f203-g01-090", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which interventions do RTs commonly perform on a MET call?", "choices": ["Suctioning, FiO₂ changes, NIV, bronchodilators, ABGs and intubation", "Surgery", "Blood transfusion", "Dialysis"], "correct": 0, "explanation": "Ch 15: suctioning, FiO₂, NIV, bronchodilators, ABG monitoring, intubation, transport.", "srcItem": "The Ch 15 Deck’s MET / RRT Activation Criteria"},
    {"id": "q-f203-g01-091", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Can a staff member call the RRT for concern alone, with normal vital signs?", "choices": ["Yes — significant staff concern is a valid trigger", "No — vital signs must be abnormal", "Only a physician can call", "Only after 4 hours"], "correct": 0, "explanation": "Exam trap: staff concern alone is a valid trigger.", "srcItem": "Vital signs and findings that trigger a Rapid Response Team call"},
    {"id": "q-f203-g01-092", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In the Hess model criteria, which mental status finding triggers a call?", "choices": ["An acute change", "Chronic dementia", "Normal alertness", "Sleeping at night"], "correct": 0, "explanation": "Any acute change in mental status triggers an RRT call.", "srcItem": "Vital signs and findings that trigger a Rapid Response Team call"},
    {"id": "q-f203-g01-093", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the goal of a rapid response team?", "choices": ["Intervene in the pre-arrest period to prevent ICU transfer, arrest or death", "Run cardiac arrests only", "Discharge patients early", "Replace the ICU"], "correct": 0, "explanation": "Hess: RRTs intervene during the critical pre-arrest period.", "srcItem": "What the RRT is and who is on it"},
    {"id": "q-f203-g01-094", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which patients are at highest risk of needing an RRT call?", "choices": ["Postop patients in the first 12–24 hours and patients just transferred out of the ICU", "Patients ready for discharge", "Outpatients", "Patients on room air with normal vitals"], "correct": 0, "explanation": "Also: nighttime activation is associated with higher mortality.", "srcItem": "What the RRT is and who is on it"},
    {"id": "q-f203-g01-095", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Who is on the RRT in Hess Table 28-5?", "choices": ["A critical care nurse, a respiratory therapist and a physician backup", "A surgeon and anesthesiologist only", "Pharmacists only", "Family members"], "correct": 0, "explanation": "Hess calls the RT \"a valuable member of the rapid response team.\"", "srcItem": "What the RRT is and who is on it"},
    {"id": "q-f203-g01-096", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A serious adverse effect occurs during therapy. What is the triple-S rule?", "choices": ["Stop the therapy, Stay with the patient, Stabilize with O₂ and help", "Send for help, Sit down, Sign the chart", "Suction, Sedate, Stop", "Stop, Silence alarms, Leave"], "correct": 0, "explanation": "Stop, Stay, Stabilize — then notify nurse and physician.", "srcItem": "When to Stop a Therapy — the Triple-S Rule"},
    {"id": "q-f203-g01-097", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "During a treatment, SpO₂ falls by 5%. What should the RT do?", "choices": ["Stop the therapy — a > 4% drop is a reason to stop", "Chart it and continue", "Increase the dose", "Ignore it if above 90%"], "correct": 0, "explanation": "A > 4% SpO₂ drop or any fall below 90% is an adverse effect.", "srcItem": "When to Stop a Therapy — the Triple-S Rule"},
    {"id": "q-f203-g01-098", "topic": "f203-g01", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What are the two reasons to stop or recommend discontinuing a therapy?", "choices": ["The patient is in jeopardy, or the goals have been achieved", "Shift change or lunch", "The order expired or the patient refused once", "Low supplies or a busy unit"], "correct": 0, "explanation": "Ch 13: safety in jeopardy, or therapy goals achieved.", "srcItem": "When to Stop a Therapy — the Triple-S Rule"},
    {"id": "q-f203-g02-001", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How do mL and cc compare?", "choices": ["They are exactly the same volume", "1 mL = 10 cc", "1 cc = 1000 mL", "They measure different things"], "correct": 0, "explanation": "3 mL = 3 cc.", "srcItem": "Units and Conversions"},
    {"id": "q-f203-g02-002", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How many grams are in 4,500 mg?", "choices": ["4.5 g", "45 g", "0.45 g", "450 g"], "correct": 0, "explanation": "1,000 mg = 1 g; move the decimal 3 places.", "srcItem": "Units and Conversions"},
    {"id": "q-f203-g02-003", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How many mL are in one tablespoon?", "choices": ["15 mL", "5 mL", "30 mL", "240 mL"], "correct": 0, "explanation": "1 tsp = 5 mL; 1 tbsp = 15 mL; 1 cup = 240 mL.", "srcItem": "Units and Conversions"},
    {"id": "q-f203-g02-004", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A 1.5-kg infant needs caffeine citrate 20 mg/kg as a loading dose. What is the dose?", "choices": ["30 mg", "7.5 mg", "20 mg", "300 mg"], "correct": 0, "explanation": "20 mg/kg × 1.5 kg = 30 mg.", "srcItem": "The Proportion Method and mg/kg Dosing"},
    {"id": "q-f203-g02-005", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the first step in the proportion method?", "choices": ["Convert to consistent units", "Cross-multiply immediately", "Guess the dose", "Add the diluent"], "correct": 0, "explanation": "First convert to consistent units, then set Known Dose/Known Amount = Desired Dose/Desired Amount.", "srcItem": "The Proportion Method and mg/kg Dosing"},
    {"id": "q-f203-g02-006", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the beractant (Survanta) dose in the decks?", "choices": ["4 mg/kg birth weight", "4 mL/kg", "25 mg/kg", "1 mg total"], "correct": 0, "explanation": "Beractant 4 mg/kg birth weight; poractant 2.5 mL/kg (max 5 mL/kg).", "srcItem": "The Proportion Method and mg/kg Dosing"},
    {"id": "q-f203-g02-007", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How do you convert a percent-strength solution to mg/mL?", "choices": ["Multiply the % by 10", "Divide the % by 10", "Multiply by 100", "Multiply by 1,000"], "correct": 0, "explanation": "1% = 1 g/100 mL = 10 mg/mL, so % × 10 = mg/mL.", "srcItem": "Percentage-Strength Solutions: % → mg/mL → Dose"},
    {"id": "q-f203-g02-008", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How many mg of albuterol are in 3 mL of a 0.083% solution?", "choices": ["About 2.5 mg", "About 25 mg", "About 0.25 mg", "About 8.3 mg"], "correct": 0, "explanation": "0.083 × 10 = 0.83 mg/mL × 3 mL = 2.49 ≈ 2.5 mg.", "srcItem": "Percentage-Strength Solutions: % → mg/mL → Dose"},
    {"id": "q-f203-g02-009", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How many mL of 0.5% albuterol give 2.5 mg?", "choices": ["0.5 mL", "5 mL", "2.5 mL", "0.05 mL"], "correct": 0, "explanation": "0.5 × 10 = 5 mg/mL; 2.5 ÷ 5 = 0.5 mL.", "srcItem": "Percentage-Strength Solutions: % → mg/mL → Dose"},
    {"id": "q-f203-g02-010", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How much drug is in 0.5 mL of 2.25% racemic epinephrine?", "choices": ["About 11.25 mg", "About 2.25 mg", "About 22.5 mg", "About 1.1 mg"], "correct": 0, "explanation": "2.25 × 10 = 22.5 mg/mL × 0.5 mL = 11.25 mg.", "srcItem": "Percentage-Strength Solutions: % → mg/mL → Dose"},
    {"id": "q-f203-g02-011", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the most common mistake in percent-solution problems?", "choices": ["Forgetting to convert the % to mg/mL first", "Using too much diluent", "Rounding the answer", "Using a calculator"], "correct": 0, "explanation": "Trap: forgetting to convert %, or mixing up mg (weight) and mL (volume).", "srcItem": "Percentage-Strength Solutions: % → mg/mL → Dose"},
    {"id": "q-f203-g02-012", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "2.5 mg of albuterol is mixed with 5 mL of saline instead of 2 mL. What changes?", "choices": ["Only the treatment time — the dose is the same", "The dose is weaker", "The dose doubles", "The drug becomes ineffective"], "correct": 0, "explanation": "Diluent changes only the time to deliver; \"more saline = weaker treatment\" is wrong.", "srcItem": "Diluent Does Not Change the Dose"},
    {"id": "q-f203-g02-013", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why is diluent added to small-volume nebulizer drugs?", "choices": ["Most nebulizers don't aerosolize well below about 1 mL of dead volume", "To weaken the drug", "To change the drug's chemistry", "To make it taste better"], "correct": 0, "explanation": "Aim for about 2.5–3 mL total so the nebulizer works efficiently.", "srcItem": "Diluent Does Not Change the Dose"},
    {"id": "q-f203-g02-014", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How much drug is in a 1:1000 solution?", "choices": ["1 mg/mL", "10 mg/mL", "0.1 mg/mL", "100 mg/mL"], "correct": 0, "explanation": "1:1000 = 1 g in 1000 mL = 1 mg/mL, so 0.3–0.5 mg of 1:1000 epi is 0.3–0.5 mL.", "srcItem": "Ratio Solutions, w/w – w/v – v/v, and Diluting a Stock Solution"},
    {"id": "q-f203-g02-015", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How much 20% stock is needed to make 5 mL of a 10% solution?", "choices": ["2.5 mL of stock plus 2.5 mL water", "5 mL of stock", "1 mL of stock plus 4 mL water", "10 mL of stock"], "correct": 0, "explanation": "V₁ × C₁ = V₂ × C₂ → x × 20 = 5 × 10 → x = 2.5 mL.", "srcItem": "Ratio Solutions, w/w – w/v – v/v, and Diluting a Stock Solution"},
    {"id": "q-f203-g02-016", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How many ppm equal 1%?", "choices": ["10,000 ppm", "100 ppm", "1,000 ppm", "1,000,000 ppm"], "correct": 0, "explanation": "Hess: 10,000 ppm = 1%.", "srcItem": "Ratio Solutions, w/w – w/v – v/v, and Diluting a Stock Solution"},
    {"id": "q-f203-g02-017", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does acetylcysteine (Mucomyst) reduce mucus viscosity?", "choices": ["Its free sulfhydryl groups break disulfide bonds in mucoproteins", "It dilates the bronchi", "It hydrates mucus by osmosis", "It kills bacteria in the mucus"], "correct": 0, "explanation": "NAC substitutes free thiol groups for disulfide bonds connecting mucin proteins.", "srcItem": "Acetylcysteine (N-Acetylcysteine, NAC, Mucomyst)"},
    {"id": "q-f203-g02-018", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the most important hazard of aerosolized acetylcysteine?", "choices": ["Bronchospasm, especially in asthmatics", "Tachycardia", "Hyperkalemia", "Hypoglycemia"], "correct": 0, "explanation": "Bronchospasm (less with 10%), nausea, rotten-egg odor, mechanical obstruction; give a bronchodilator first.", "srcItem": "Acetylcysteine (N-Acetylcysteine, NAC, Mucomyst)"},
    {"id": "q-f203-g02-019", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is acetylcysteine's most important use today?", "choices": ["Antidote for acetaminophen overdose to protect the liver", "Routine mucolytic for COPD", "Treatment of status asthmaticus", "Reversal of opioids"], "correct": 0, "explanation": "\"NAC saves the liver!\" — very testable. Routine aerosolized NAC for airway clearance is not recommended.", "srcItem": "Acetylcysteine (N-Acetylcysteine, NAC, Mucomyst)"},
    {"id": "q-f203-g02-020", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the critical rule about neuromuscular blocking agents?", "choices": ["They do not sedate or relieve pain — give analgesia, then sedation, then the paralytic", "They provide full sedation", "They relieve pain", "They stimulate breathing"], "correct": 0, "explanation": "\"Paralysis ≠ sedation\"; order: analgesia → sedation → paralytic, and the patient must be ventilated.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f203-g02-021", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is the only depolarizing neuromuscular blocker?", "choices": ["Succinylcholine", "Vecuronium", "Rocuronium", "Cisatracurium"], "correct": 0, "explanation": "Succinylcholine is the only depolarizing NMBA; it causes fasciculations first.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f203-g02-022", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the most important complication of succinylcholine?", "choices": ["Hyperkalemia", "Hypokalemia", "Hypoglycemia", "Hypertension only"], "correct": 0, "explanation": "\"If you remember ONE complication\" — hyperkalemia; caution in burns, trauma, denervation.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f203-g02-023", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the difference between sedation and analgesia?", "choices": ["Sedation diminishes awareness; analgesia relieves pain", "They are the same", "Sedation relieves pain; analgesia causes sleep", "Analgesia paralyzes muscles"], "correct": 0, "explanation": "\"Sedative ≠ Analgesic\": propofol/midazolam sedate; morphine/fentanyl relieve pain.", "srcItem": "Sedatives"},
    {"id": "q-f203-g02-024", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which sedative gives sedation, anxiolysis and some analgesia without respiratory depression?", "choices": ["Dexmedetomidine (Precedex)", "Midazolam", "Propofol", "Lorazepam"], "correct": 0, "explanation": "Dexmedetomidine, a selective α₂ agonist; it can be continued through extubation.", "srcItem": "Sedatives"},
    {"id": "q-f203-g02-025", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why is propofol called 'milk of amnesia', and what must be watched?", "choices": ["It is a lipid emulsion; watch for hypotension and rising triglycerides", "It is a water solution; watch for hypertension", "It is a gas; watch for fire", "It is a pill; watch for nausea"], "correct": 0, "explanation": "Propofol is a lipid emulsion (adds calories, raises triglycerides); watch BP, apnea, bradycardia.", "srcItem": "Sedatives"},
    {"id": "q-f203-g02-026", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the deck call the #1 thing opioids can kill?", "choices": ["Breathing", "The heart", "The liver", "The kidneys"], "correct": 0, "explanation": "Respiratory depression is the most important opioid side effect.", "srcItem": "Opiates (Opioids)"},
    {"id": "q-f203-g02-027", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What reverses opioids?", "choices": ["Naloxone (Narcan)", "Flumazenil", "Neostigmine", "Dantrolene"], "correct": 0, "explanation": "Naloxone, which also comes as a nasal spray; withdrawal may appear within minutes in dependent patients.", "srcItem": "Opiates (Opioids)"},
    {"id": "q-f203-g02-028", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How much stronger is hydromorphone (Dilaudid) than morphine?", "choices": ["5–10 times", "About half as strong", "100 times", "Equal"], "correct": 0, "explanation": "Hydromorphone is 5–10× stronger than morphine.", "srcItem": "Opiates (Opioids)"},
    {"id": "q-f203-g02-029", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is a drug's plasma half-life?", "choices": ["The time for plasma concentration to fall by one-half", "The time to reach peak effect", "Half the dose given", "The duration of action"], "correct": 0, "explanation": "T½ = time for the plasma concentration to decrease by one-half.", "srcItem": "Half-Life of Medications"},
    {"id": "q-f203-g02-030", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why are older adults and patients with liver or kidney disease at greater risk of drug toxicity?", "choices": ["Drug half-lives are longer in these conditions", "Their drugs are absorbed faster", "They metabolize drugs too quickly", "They have more receptors"], "correct": 0, "explanation": "Hess: half-lives are longer with age and hepatic or renal impairment.", "srcItem": "Half-Life of Medications"},
    {"id": "q-f203-g02-031", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which drug has an extremely short half-life of about 12 seconds?", "choices": ["Adenosine", "Lorazepam", "Omalizumab", "Theophylline"], "correct": 0, "explanation": "Adenosine ~12 seconds (\"super short\").", "srcItem": "Half-Life of Medications"},
    {"id": "q-f203-g02-032", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which route is 'parenteral'?", "choices": ["Intravenous", "Oral tablet", "Rectal suppository", "Sublingual"], "correct": 0, "explanation": "Parenteral = any route other than enteral (IV, IM, SubQ, IO, IT).", "srcItem": "Routes of Administration"},
    {"id": "q-f203-g02-033", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is an advantage of the inhaled route?", "choices": ["Smaller dose with fewer side effects and rapid onset", "Always 100% bioavailable", "Requires no technique", "Avoids the lungs"], "correct": 0, "explanation": "Inhaled: smaller dose, fewer side effects, rapid onset, targets the lungs, painless.", "srcItem": "Routes of Administration"},
    {"id": "q-f203-g02-034", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why must nondepolarizing NMBAs be given IV?", "choices": ["They are poorly absorbed in the GI tract", "They cause vomiting", "They are inhaled gases", "They need the liver to activate"], "correct": 0, "explanation": "Nondepolarizing NMBAs are poorly absorbed orally, so IV only.", "srcItem": "Routes of Administration"},
    {"id": "q-f203-g02-035", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does bioavailability indicate?", "choices": ["The proportion of a drug that reaches the systemic circulation", "How fast a drug is eliminated", "The drug's half-life", "The drug's cost"], "correct": 0, "explanation": "IV is the standard at 100% bioavailability.", "srcItem": "Bioavailability"},
    {"id": "q-f203-g02-036", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does high first-pass metabolism do to an oral drug?", "choices": ["Reduces its bioavailability", "Increases its bioavailability", "Has no effect", "Makes it inhaled"], "correct": 0, "explanation": "The liver inactivates much of the drug before it reaches the circulation.", "srcItem": "Bioavailability"},
    {"id": "q-f203-g02-037", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which practice raises the lung/total (L/T) ratio of an inhaled drug?", "choices": ["Mouth rinsing and a breath hold", "Swallowing the drug", "Using no spacer", "Inhaling rapidly without holding"], "correct": 0, "explanation": "Higher L/T = more efficient lung delivery: efficient devices, reservoirs, rinse and spit, breath hold, instruction.", "srcItem": "Bioavailability"},
    {"id": "q-f203-g02-038", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What are the major organs of drug elimination (Hess)?", "choices": ["The kidney and, to a lesser extent, the liver", "The lungs and skin", "The spleen and heart", "The stomach and intestines"], "correct": 0, "explanation": "Kidney and liver are major; lungs, saliva and sweat are minor routes.", "srcItem": "Organs of Elimination"},
    {"id": "q-f203-g02-039", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What primarily determines how quickly drugs are eliminated?", "choices": ["Renal function measured by creatinine clearance or eGFR", "Hair growth", "Body temperature only", "Blood type"], "correct": 0, "explanation": "Elimination depends primarily on renal function (CrCl or eGFR).", "srcItem": "Organs of Elimination"},
    {"id": "q-f203-g02-040", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "According to Chang's memory line, where are benzodiazepines metabolized and excreted?", "choices": ["Liver = metabolism; kidneys = excretion", "Kidneys = metabolism; liver = excretion", "Lungs = both", "Spleen = both"], "correct": 0, "explanation": "\"Liver = Metabolism, Kidneys = Excretion.\"", "srcItem": "Organs of Elimination"},
    {"id": "q-f203-g02-041", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is more specific for kidney function?", "choices": ["Creatinine", "BUN", "Glucose", "Albumin"], "correct": 0, "explanation": "Creatinine (from muscle) is filtered with little reabsorption; BUN reflects protein metabolism and hydration.", "srcItem": "Creatinine vs Blood Urea Nitrogen (BUN)"},
    {"id": "q-f203-g02-042", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal BUN range in the RCP 202 Renal deck?", "choices": ["7–20 mg/dL", "0.7–1.3 mg/dL", "70–110 mg/dL", "135–145 mg/dL"], "correct": 0, "explanation": "BUN 7–20 mg/dL; creatinine men 0.7–1.3, women 0.6–1.1.", "srcItem": "Creatinine vs Blood Urea Nitrogen (BUN)"},
    {"id": "q-f203-g02-043", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A patient has a high BUN with a normal creatinine. What does this suggest?", "choices": ["Dehydration or high protein intake", "Kidney failure", "Low muscle mass", "Liver failure only"], "correct": 0, "explanation": "High BUN with normal creatinine → dehydration or high protein; both high → kidney disease/AKI.", "srcItem": "Creatinine vs Blood Urea Nitrogen (BUN)"},
    {"id": "q-f203-g02-044", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is beclomethasone (QVAR)?", "choices": ["An inhaled corticosteroid controller, not a rescue agent", "A short-acting rescue bronchodilator", "An anticholinergic", "A leukotriene inhibitor"], "correct": 0, "explanation": "ICS: maintenance control of chronic asthma; not for acute severe asthma.", "srcItem": "Beclomethasone Dipropionate (QVAR)"},
    {"id": "q-f203-g02-045", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What are the most common side effects of inhaled corticosteroids?", "choices": ["Oropharyngeal candidiasis (thrush) and dysphonia", "Tachycardia and tremor", "Hypokalemia", "Dry mouth and mydriasis"], "correct": 0, "explanation": "Prevent with the minimal dose, a reservoir, and rinsing the mouth.", "srcItem": "Beclomethasone Dipropionate (QVAR)"},
    {"id": "q-f203-g02-046", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How do inhaled steroids interact with β-agonists?", "choices": ["They restore β-responsiveness by increasing β-receptors", "They block β-receptors", "They have no interaction", "They replace β-agonists in acute attacks"], "correct": 0, "explanation": "Steroids increase the number and availability of β-receptors.", "srcItem": "Beclomethasone Dipropionate (QVAR)"},
    {"id": "q-f203-g02-047", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the onset and duration of a SABA per the class slide?", "choices": ["Onset 15 minutes, duration 4–6 hours", "Onset 2 hours, duration 24 hours", "Onset 1 minute, duration 30 minutes", "Onset 20 minutes, duration 12 hours"], "correct": 0, "explanation": "Use the class slide's 4–6 hours for albuterol and levalbuterol.", "srcItem": "Albuterol and Levalbuterol (SABAs)"},
    {"id": "q-f203-g02-048", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does levalbuterol differ from albuterol?", "choices": ["It is the pure R-isomer", "It is a long-acting drug", "It is an anticholinergic", "It is the pure S-isomer"], "correct": 0, "explanation": "Albuterol is 50:50 R and S; levalbuterol is pure R (less tremor/HR, superiority unproven).", "srcItem": "Albuterol and Levalbuterol (SABAs)"},
    {"id": "q-f203-g02-049", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the standard albuterol nebulizer dose (RCP 103)?", "choices": ["2.5 mg in 3 mL normal saline", "25 mg in 3 mL", "0.25 mg in 10 mL", "10 mg undiluted"], "correct": 0, "explanation": "RCP 103 Asthma: 2.5 mg/3 mL NS.", "srcItem": "Albuterol and Levalbuterol (SABAs)"},
    {"id": "q-f203-g02-050", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is a side effect of β-agonists?", "choices": ["Tremor and hypokalemia", "Bradycardia", "Hyperkalemia", "Thrush"], "correct": 0, "explanation": "β-agonist effects: tremor, ↑ HR, tolerance, ↓ K⁺, ↑ glucose, paradoxical bronchospasm.", "srcItem": "Albuterol and Levalbuterol (SABAs)"},
    {"id": "q-f203-g02-051", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What class of drug is ipratropium (Atrovent)?", "choices": ["An anticholinergic (muscarinic antagonist) bronchodilator", "A β₂-agonist", "A corticosteroid", "A mucolytic"], "correct": 0, "explanation": "Hess: a short-acting muscarinic antagonist (SAMA).", "srcItem": "Ipratropium Bromide (Atrovent)"},
    {"id": "q-f203-g02-052", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the most common side effect of ipratropium?", "choices": ["Dry mouth", "Tremor", "Thrush", "Hyperglycemia"], "correct": 0, "explanation": "Also cough and mydriasis (protect the eyes); cardiac changes not usually seen.", "srcItem": "Ipratropium Bromide (Atrovent)"},
    {"id": "q-f203-g02-053", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why does ipratropium stay mostly in the lungs?", "choices": ["As a quaternary ammonium compound it crosses lipid membranes poorly", "It is absorbed only by mucus", "It is too large to inhale", "It binds to hemoglobin"], "correct": 0, "explanation": "It does not distribute well across lipid membranes.", "srcItem": "Ipratropium Bromide (Atrovent)"},
    {"id": "q-f203-g02-054", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the deck's ipratropium MDI dose?", "choices": ["17 µg/puff, 2 puffs QID", "90 µg/puff prn", "500 µg once daily", "1 mg every hour"], "correct": 0, "explanation": "Deck: MDI 17 µg × 2 puffs QID; SVN 0.5 mg QID.", "srcItem": "Ipratropium Bromide (Atrovent)"},
    {"id": "q-f203-g02-055", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How do LABAs differ from SABAs?", "choices": ["LABAs are controllers lasting 12–24 h; SABAs are rescue drugs lasting 4–6 h", "LABAs are rescue drugs", "SABAs last 24 hours", "LABAs act on muscarinic receptors"], "correct": 0, "explanation": "LABA onset ~20 min, duration 12–24 h; lipophilic.", "srcItem": "LABAs vs SABAs"},
    {"id": "q-f203-g02-056", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Can a LABA be used alone in asthma?", "choices": ["No — always with an inhaled corticosteroid, and never for rescue", "Yes — as monotherapy", "Yes — for acute attacks", "Only in children"], "correct": 0, "explanation": "LABAs may mask inflammation; combine with ICS.", "srcItem": "LABAs vs SABAs"},
    {"id": "q-f203-g02-057", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is a long-acting β₂-agonist?", "choices": ["Salmeterol", "Albuterol", "Ipratropium", "Montelukast"], "correct": 0, "explanation": "LABAs: salmeterol, formoterol, arformoterol; ultra-LABAs indacaterol, olodaterol, vilanterol.", "srcItem": "LABAs vs SABAs"},
    {"id": "q-f203-g02-058", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does montelukast work?", "choices": ["It blocks the CysLT1 leukotriene receptor", "It inhibits 5-lipoxygenase", "It binds IgE", "It blocks muscarinic receptors"], "correct": 0, "explanation": "Montelukast: receptor antagonist; zileuton blocks production via 5-LO.", "srcItem": "Leukotriene Inhibitors (Antileukotrienes)"},
    {"id": "q-f203-g02-059", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which antileukotriene requires liver-function monitoring?", "choices": ["Zileuton", "Montelukast", "Albuterol", "Tiotropium"], "correct": 0, "explanation": "Zileuton inhibits 5-LO; monitor liver function; interacts with theophylline and warfarin.", "srcItem": "Leukotriene Inhibitors (Antileukotrienes)"},
    {"id": "q-f203-g02-060", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Are leukotriene inhibitors used for acute asthma attacks?", "choices": ["No — they are prophylactic controllers", "Yes — first-line rescue", "Yes — IV in the ER", "Only with heliox"], "correct": 0, "explanation": "They protect against exercise-, aspirin- and allergen-induced asthma; effective in ~50–70%.", "srcItem": "Leukotriene Inhibitors (Antileukotrienes)"},
    {"id": "q-f203-g02-061", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which immunoglobulin is the 'asthma antibody' that attaches to mast cells?", "choices": ["IgE", "IgA", "IgG", "IgM"], "correct": 0, "explanation": "IgE triggers allergic reactions; IgA protects mucosa; IgG most common; IgM first responder.", "srcItem": "Immunoglobulins and Monoclonal Antibodies"},
    {"id": "q-f203-g02-062", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does omalizumab (Xolair) work?", "choices": ["It binds IgE, blocking its attachment to mast cells", "It blocks IL-5", "It inhibits RSV replication", "It blocks β-receptors"], "correct": 0, "explanation": "Omalizumab for allergic (IgE) asthma, SC every 2–4 weeks.", "srcItem": "Immunoglobulins and Monoclonal Antibodies"},
    {"id": "q-f203-g02-063", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which biologics block interleukin-5 for eosinophilic asthma?", "choices": ["Mepolizumab, reslizumab and benralizumab", "Omalizumab and palivizumab", "Montelukast and zileuton", "Tiotropium and ipratropium"], "correct": 0, "explanation": "Anti-IL-5 reduces eosinophils.", "srcItem": "Immunoglobulins and Monoclonal Antibodies"},
    {"id": "q-f203-g02-064", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does palivizumab (Synagis) prevent?", "choices": ["RSV infection in high-risk infants", "Asthma attacks", "CMV in transplant", "Influenza"], "correct": 0, "explanation": "For BPD, prematurity < 35 weeks, congenital heart disease; 15 mg/kg IM monthly in season.", "srcItem": "Immunoglobulins and Monoclonal Antibodies"},
    {"id": "q-f203-g02-065", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the most severe side effect of monoclonal antibody biologics?", "choices": ["Anaphylaxis", "Thrush", "Tremor", "Dry mouth"], "correct": 0, "explanation": "Biologics are add-ons, not for acute relief and not a replacement for ICS.", "srcItem": "Immunoglobulins and Monoclonal Antibodies"},
    {"id": "q-f203-g02-066", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How often is tiotropium (LAMA) given?", "choices": ["Once daily", "Four times daily", "Every 2 hours", "Weekly"], "correct": 0, "explanation": "Deck: tiotropium and umeclidinium once daily; aclidinium bid.", "srcItem": "Standard Dosing Frequency and Sites of Action"},
    {"id": "q-f203-g02-067", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is tobramycin (TOBI) dosed?", "choices": ["300 mg BID, 28 days on / 28 days off", "Once weekly", "Continuously", "10 mg daily"], "correct": 0, "explanation": "Deck: TOBI 300 mg BID on alternating 28-day cycles.", "srcItem": "Standard Dosing Frequency and Sites of Action"},
    {"id": "q-f203-g02-068", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the dornase alfa dose and mechanism?", "choices": ["2.5 mg daily; breaks down DNA in secretions", "25 mg weekly; dilates airways", "0.5 mg QID; blocks IgE", "5 mg BID; thins mucus by osmosis"], "correct": 0, "explanation": "Dornase alfa: 2.5 mg daily.", "srcItem": "Standard Dosing Frequency and Sites of Action"},
    {"id": "q-f203-g02-069", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which receptor mediates bronchodilation?", "choices": ["β₂", "β₁", "α₁", "M3"], "correct": 0, "explanation": "β₁ heart, β₂ lungs, α₁ vasoconstriction, M3 airway smooth muscle constriction.", "srcItem": "Standard Dosing Frequency and Sites of Action"},
    {"id": "q-f203-g02-070", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the recommended order for multiple inhaled medications?", "choices": ["Bronchodilator → mucolytic → airway clearance → steroid → antibiotic", "Antibiotic → steroid → bronchodilator", "Steroid → antibiotic → mucolytic", "Mucolytic → antibiotic → bronchodilator"], "correct": 0, "explanation": "Open the airway, thin and clear secretions, then deliver steroid and antibiotic.", "srcItem": "Giving Inhaled Drugs"},
    {"id": "q-f203-g02-071", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "For which patient should an SVN be reserved?", "choices": ["Acutely ill adults who cannot use a DPI or MDI", "All outpatients", "Adolescents with strong inspiratory flow", "Patients who prefer DPIs"], "correct": 0, "explanation": "Infants: MDI with holding chamber and mask; outpatient adults: DPI if flow is adequate.", "srcItem": "Giving Inhaled Drugs"},
    {"id": "q-f203-g02-072", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In an acute asthma exacerbation, how often is the SABA repeated?", "choices": ["Every 20 minutes up to 3 times, or continuous nebulization", "Every 8 hours", "Once daily", "Only once"], "correct": 0, "explanation": "Ch 12 deck.", "srcItem": "Giving Inhaled Drugs"},
    {"id": "q-f203-g02-073", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When are aerosolized antibiotics such as TOBI or Cayston generally indicated?", "choices": ["Cystic fibrosis with Pseudomonas infection", "All pneumonias", "Asthma maintenance", "Bronchiolitis"], "correct": 0, "explanation": "Generally only CF with suspected or confirmed Pseudomonas.", "srcItem": "Giving Inhaled Drugs"},
    {"id": "q-f203-g02-074", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is an emergency drug given down the ETT?", "choices": ["2–2.5× the IV dose, diluted in 10 mL, followed by 5–10 rapid inflations", "The same as the IV dose, undiluted", "Half the IV dose", "Through the cuff pilot line"], "correct": 0, "explanation": "LEAN drugs; patient supine, compressions halted, catheter past the ETT tip.", "srcItem": "Drugs Down the Tube"},
    {"id": "q-f203-g02-075", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is surfactant instilled?", "choices": ["Through a catheter up to, not past, the ETT tip, split between each dependent bronchus", "Nebulized through a mask", "Injected IV", "Given orally"], "correct": 0, "explanation": "Confirm ETT position by CXR first; avoid suctioning for 6 hours if possible.", "srcItem": "Drugs Down the Tube"},
    {"id": "q-f203-g02-076", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Is prophylactic or rescue surfactant recommended for infants under 30 weeks?", "choices": ["Prophylactic", "Rescue only", "Neither", "Only after 24 hours"], "correct": 0, "explanation": "Prophylactic reduces pneumothorax, PIE and neonatal mortality.", "srcItem": "Drugs Down the Tube"},
    {"id": "q-f203-g02-077", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does albuterol lower serum potassium?", "choices": ["β₂ stimulation increases Na⁺/K⁺-ATPase activity, moving K⁺ into cells", "It makes the kidneys excrete K⁺", "It binds K⁺ in the gut", "It removes K⁺ through the lungs"], "correct": 0, "explanation": "Total body K⁺ is unchanged — a bridge therapy that can rebound.", "srcItem": "Albuterol for Hyperkalemia"},
    {"id": "q-f203-g02-078", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What albuterol dose is used for hyperkalemia?", "choices": ["10–20 mg nebulized", "2.5 mg nebulized", "90 µg MDI", "0.5 mg IV"], "correct": 0, "explanation": "Far above the bronchodilator dose; lowers K⁺ ~0.5–1.0 mEq/L.", "srcItem": "Albuterol for Hyperkalemia"},
    {"id": "q-f203-g02-079", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the RASS target for moderate sedation?", "choices": ["−3", "0", "+4", "−5"], "correct": 0, "explanation": "RASS runs +4 (combative) to −5 (unarousable); 0 = alert and calm.", "srcItem": "Moderate"},
    {"id": "q-f203-g02-080", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What principle permits comfort dosing that may hasten death during withdrawal of life support?", "choices": ["The principle of double effect", "Euthanasia", "Implied consent", "Beneficence only"], "correct": 0, "explanation": "Relief must be the intent; raising doses to hasten death is euthanasia.", "srcItem": "Moderate"},
    {"id": "q-f203-g02-081", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Before withdrawing life support, which drugs should be stopped?", "choices": ["Paralytics and drugs that don't add comfort", "All opioids", "All sedatives", "Oxygen only"], "correct": 0, "explanation": "Comfort comes from analgesia and sedation; FiO₂ is lowered to 30% first.", "srcItem": "Moderate"},
    {"id": "q-f203-g02-082", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In the 40-50-60 / 70-80-90 rule, what SpO₂ corresponds to a PaO₂ of 50 torr?", "choices": ["About 80%", "About 70%", "About 90%", "About 95%"], "correct": 0, "explanation": "PaO₂ 40 ≈ 70%, 50 ≈ 80%, 60 ≈ 90%.", "srcItem": "The Rule and How to Use It"},
    {"id": "q-f203-g02-083", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "An SpO₂ of 70% suggests about what PaO₂?", "choices": ["40 torr", "60 torr", "80 torr", "100 torr"], "correct": 0, "explanation": "The rule applies when SpO₂ is below 90%.", "srcItem": "The Rule and How to Use It"},
    {"id": "q-f203-g02-084", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When does RCP 203 say the 40-50-60 rule applies?", "choices": ["When SpO₂ is below 90%", "Only above 95%", "Only on room air above 98%", "Never in adults"], "correct": 0, "explanation": "It is approximate (\"about equal\").", "srcItem": "The Rule and How to Use It"},
    {"id": "q-f203-g02-085", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why is the 60/90 pair important?", "choices": ["It is the threshold for hypoxemia and supplemental O₂", "It is the normal value", "It is the CO poisoning cutoff", "It is the ventilator weaning ceiling"], "correct": 0, "explanation": "Hypoxemia = PaO₂ < 60 or SaO₂ < 90% on room air.", "srcItem": "Why 60/90 Is the Key Pair"},
    {"id": "q-f203-g02-086", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "At what saturation does central cyanosis first appear with normal Hb?", "choices": ["SaO₂ below 80% (PaO₂ 45–50 torr)", "SaO₂ below 98%", "SaO₂ below 95%", "SaO₂ below 50% only"], "correct": 0, "explanation": "Near the rule's 80/50 pair.", "srcItem": "Why 60/90 Is the Key Pair"},
    {"id": "q-f203-g02-087", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How accurate are pulse oximeters with good perfusion?", "choices": ["± 2–4%", "± 0.1%", "± 20%", "Perfectly accurate"], "correct": 0, "explanation": "They also overestimate saturation when HbCO is present.", "srcItem": "Why 60/90 Is the Key Pair"},
    {"id": "q-f203-g02-088", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What air:O₂ ratio gives an FiO₂ of 40%?", "choices": ["3:1", "1:1", "10:1", "25:1"], "correct": 0, "explanation": "Magic box: air 100 − 40 = 60; O₂ 40 − 20 = 20 → 3:1.", "srcItem": "Step 1"},
    {"id": "q-f203-g02-089", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What air:O₂ ratio gives an FiO₂ of 60%?", "choices": ["1:1", "3:1", "5:1", "0.3:1"], "correct": 0, "explanation": "100 − 60 = 40; 60 − 20 = 40 → 1:1.", "srcItem": "Step 1"},
    {"id": "q-f203-g02-090", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What air:O₂ ratio gives 28% in Hess Table 14-2?", "choices": ["10:1", "3:1", "1:1", "25:1"], "correct": 0, "explanation": "24% 25:1; 28% 10:1; 30% 8:1; 35% 5:1; 40% 3:1.", "srcItem": "Step 1"},
    {"id": "q-f203-g02-091", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is total flow from an air-entrainment device calculated?", "choices": ["O₂ flow × total ratio parts", "O₂ flow ÷ ratio parts", "FiO₂ × 100", "Air parts only"], "correct": 0, "explanation": "Total parts = air parts + 1.", "srcItem": "Step 2: Total Flow = O₂ Flow × Total Ratio Parts"},
    {"id": "q-f203-g02-092", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A 40% device runs at 10 L/min. What is the total flow?", "choices": ["40 L/min", "30 L/min", "10 L/min", "50 L/min"], "correct": 0, "explanation": "3:1 → 4 parts × 10 = 40 L/min.", "srcItem": "Step 2: Total Flow = O₂ Flow × Total Ratio Parts"},
    {"id": "q-f203-g02-093", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "The same 40% device is turned down to 5 L/min. What changes?", "choices": ["Total flow falls to 20 L/min; FiO₂ stays 40%", "FiO₂ rises", "FiO₂ falls", "Nothing changes"], "correct": 0, "explanation": "Changing O₂ flow changes only total flow, not the ratio.", "srcItem": "Step 2: Total Flow = O₂ Flow × Total Ratio Parts"},
    {"id": "q-f203-g02-094", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "As the set FiO₂ rises on an entrainment device, what happens to total flow?", "choices": ["It falls", "It rises", "It stays the same", "It doubles"], "correct": 0, "explanation": "Higher FiO₂ → less air entrained → lower total flow.", "srcItem": "Step 2: Total Flow = O₂ Flow × Total Ratio Parts"},
    {"id": "q-f203-g02-095", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What total flow does the deck target for an air-entrainment device?", "choices": ["At least 40 L/min", "At least 10 L/min", "At least 100 L/min always", "Exactly 15 L/min"], "correct": 0, "explanation": "The device is high-flow only if it meets the patient's inspiratory flow.", "srcItem": "Matching Total Flow to the Patient"},
    {"id": "q-f203-g02-096", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How much O₂ flow is needed for a 60% device to deliver 40 L/min?", "choices": ["20 L/min", "10 L/min", "40 L/min", "5 L/min"], "correct": 0, "explanation": "60% = 2 parts; 40 ÷ 2 = 20 L/min.", "srcItem": "Matching Total Flow to the Patient"},
    {"id": "q-f203-g02-097", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What minimum flow does Hess give relative to minute ventilation?", "choices": ["3–4 times the minute ventilation", "Equal to the minute ventilation", "Half the minute ventilation", "10 times the minute ventilation"], "correct": 0, "explanation": "About 40 L/min for adults.", "srcItem": "Matching Total Flow to the Patient"},
    {"id": "q-f203-g02-098", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How can you tell a patient is out-breathing an aerosol entrainment device?", "choices": ["The mist disappears from the mask or T-piece during inspiration", "The mist increases", "The FiO₂ rises", "The patient's SpO₂ rises"], "correct": 0, "explanation": "FiO₂ then falls and the system becomes low-flow.", "srcItem": "Matching Total Flow to the Patient"},
    {"id": "q-f203-g02-099", "topic": "f203-g02", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What should be used for FiO₂ > 0.60 at flows > 40 L/min?", "choices": ["A blending system", "A simple mask", "A nasal cannula", "A larger entrainment port"], "correct": 0, "explanation": "The deck says use a blender.", "srcItem": "Matching Total Flow to the Patient"},
    {"id": "q-f203-g03-001", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why do the decks say to 'learn how the mode works — not just the name'?", "choices": ["Mode names are not standardized between manufacturers", "Every ventilator uses the same mode names", "Mode names determine the FiO₂", "Only Servo ventilators have modes"], "correct": 0, "explanation": "Names are manufacturer-dependent (e.g. PRVC on Servo = VC+ on PB840 = AutoFlow on Dräger).", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f203-g03-002", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "According to the golden rule, how many variables can a ventilator control at once?", "choices": ["Only one — pressure or volume", "Both pressure and volume", "Pressure, volume and flow together", "None — the patient controls all"], "correct": 0, "explanation": "Control volume and pressure varies; control pressure and volume varies.", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f203-g03-003", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A breath is triggered by the patient but cycled by the ventilator. How is it classified?", "choices": ["Mandatory", "Spontaneous", "Assisted spontaneous", "Apneic"], "correct": 0, "explanation": "\"If the patient controls both = Spontaneous. If the ventilator controls either one = it's Mandatory.\"", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f203-g03-004", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In volume control, a patient develops ARDS. What happens?", "choices": ["VT stays the same and pressure increases", "VT falls and pressure stays the same", "Both VT and pressure fall", "Nothing changes"], "correct": 0, "explanation": "VC guarantees VT; pressure is the dependent variable and rises as compliance falls.", "srcItem": "VC vs PC: the Difference and When to Use Each"},
    {"id": "q-f203-g03-005", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In pressure control, a patient develops ARDS. What happens?", "choices": ["Pressure stays the same and VT decreases", "VT stays the same and pressure rises", "Both rise", "PEEP rises automatically"], "correct": 0, "explanation": "PC guarantees pressure; VT falls with decreased compliance.", "srcItem": "VC vs PC: the Difference and When to Use Each"},
    {"id": "q-f203-g03-006", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PC is set at 20 cm H₂O with PEEP 10 cm H₂O. What is the PIP?", "choices": ["30 cm H₂O", "20 cm H₂O", "10 cm H₂O", "40 cm H₂O"], "correct": 0, "explanation": "PIP = pressure control + PEEP = 20 + 10 = 30 cm H₂O.", "srcItem": "VC vs PC: the Difference and When to Use Each"},
    {"id": "q-f203-g03-007", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the key difference between the control mode (CMV) and assist/control?", "choices": ["A/C allows patient-triggered breaths; CMV (control) does not", "CMV allows spontaneous breaths between mandatory breaths", "A/C has no set rate", "CMV always uses pressure support"], "correct": 0, "explanation": "The slide's one-line difference: A/C allows patient-triggered breaths; control mode does not.", "srcItem": "CMV (and How It Differs from Assist/Control)"},
    {"id": "q-f203-g03-008", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A/C is set at 12 breaths/min and the patient triggers 24. How many full breaths are delivered?", "choices": ["24", "12", "36", "6"], "correct": 0, "explanation": "In A/C every triggered breath gets the full preset support; the set rate is a minimum.", "srcItem": "CMV (and How It Differs from Assist/Control)"},
    {"id": "q-f203-g03-009", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is a patient-triggered (assisted) breath identified on the pressure waveform?", "choices": ["A negative deflection below baseline before inspiration", "A positive spike after exhalation", "A flat line", "A sudden drop in PEEP to zero"], "correct": 0, "explanation": "Assist = negative deflection before inspiration; time-triggered control breaths have none.", "srcItem": "CMV (and How It Differs from Assist/Control)"},
    {"id": "q-f203-g03-010", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What problem does IMV (unsynchronized) cause that SIMV avoids?", "choices": ["Breath stacking", "Low FiO₂", "Excess PS", "Hypercapnia only"], "correct": 0, "explanation": "IMV can deliver a mandatory breath before a spontaneous one is exhaled → breath stacking, auto-PEEP.", "srcItem": "IMV vs SIMV"},
    {"id": "q-f203-g03-011", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In SIMV with PS 8, which breaths receive the pressure support?", "choices": ["Only the spontaneous breaths between mandatory breaths", "Only the mandatory breaths", "All breaths equally", "No breaths — PS is inactive in SIMV"], "correct": 0, "explanation": "PS applies only to spontaneous breaths; mandatory breaths deliver the preset VT.", "srcItem": "IMV vs SIMV"},
    {"id": "q-f203-g03-012", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why is SIMV usually combined with pressure support?", "choices": ["To prevent muscle fatigue and high WOB on spontaneous breaths", "To increase the mandatory rate", "To guarantee VT on every breath", "To lower the FiO₂"], "correct": 0, "explanation": "Without PS, SIMV can cause muscle fatigue and weaning failure; PS helps the spontaneous breaths.", "srcItem": "IMV vs SIMV"},
    {"id": "q-f203-g03-013", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is pressure support classified?", "choices": ["Patient-triggered, pressure-limited, flow-cycled", "Time-triggered, volume-limited, time-cycled", "Patient-triggered, volume-limited, volume-cycled", "Time-triggered, pressure-limited, time-cycled"], "correct": 0, "explanation": "PSV = patient-triggered, pressure-limited, flow-cycled — a phrase on NBRC-style exams repeatedly.", "srcItem": "Pressure Support"},
    {"id": "q-f203-g03-014", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When does a pressure-supported breath end?", "choices": ["When inspiratory flow falls to a preset percentage of peak flow, often ~25%", "After a fixed inspiratory time", "When the preset VT is reached", "When the patient coughs"], "correct": 0, "explanation": "PS breaths flow-cycle, often at about 25% of peak flow.", "srcItem": "Pressure Support"},
    {"id": "q-f203-g03-015", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why can PSV not be used alone in an apneic patient?", "choices": ["Every PS breath must be patient-triggered", "PS gives too much volume", "PS has no FiO₂ setting", "PS requires paralysis"], "correct": 0, "explanation": "PS is active only on spontaneous breaths, so it needs an intact respiratory drive.", "srcItem": "Pressure Support"},
    {"id": "q-f203-g03-016", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does MMV ensure adequate ventilation?", "choices": ["It increases mandatory breaths when spontaneous V̇E falls below a preset minimum", "It guarantees VT on every breath", "It raises PEEP automatically", "It increases the FiO₂ to 1.0"], "correct": 0, "explanation": "MMV is a \"minimum ventilation safety net\": low V̇E → more volume-cycled mandatory breaths.", "srcItem": "MMV (Mandatory/Minimum Minute Ventilation)"},
    {"id": "q-f203-g03-017", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On MMV with a target of 8 L/min, the patient breathes 9 L/min alone. What does the ventilator do?", "choices": ["Adds no extra mandatory ventilation", "Adds 1 L/min of mandatory breaths", "Switches to A/C", "Lowers the patient's rate"], "correct": 0, "explanation": "If the patient breathes enough, MMV stays out of the way.", "srcItem": "MMV (Mandatory/Minimum Minute Ventilation)"},
    {"id": "q-f203-g03-018", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does MMV NOT guarantee?", "choices": ["That every breath has an adequate VT", "A minimum total minute ventilation", "Backup mandatory breaths", "Volume-cycled mandatory breaths"], "correct": 0, "explanation": "MMV guarantees minimum total V̇E, not an adequate VT on every breath.", "srcItem": "MMV (Mandatory/Minimum Minute Ventilation)"},
    {"id": "q-f203-g03-019", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which mode automatically adjusts inspiratory pressure to maintain a target VT while minimizing airway pressure?", "choices": ["PRVC", "APRV", "PAV", "HFOV"], "correct": 0, "explanation": "Board pearl: PRVC delivers the target VT at the lowest PIP possible.", "srcItem": "PRVC (Pressure-Regulated Volume Control)"},
    {"id": "q-f203-g03-020", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On PRVC, the patient's compliance worsens. What does the ventilator do?", "choices": ["Raises the inspiratory pressure to deliver the target VT", "Lowers the inspiratory pressure", "Drops the VT", "Switches to CPAP"], "correct": 0, "explanation": "Compliance worsens → PRVC raises pressure; compliance improves → it lowers pressure.", "srcItem": "PRVC (Pressure-Regulated Volume Control)"},
    {"id": "q-f203-g03-021", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On Automode, the patient makes two consecutive patient-triggered breaths. What happens?", "choices": ["It switches from PRVC to Volume Support", "It switches to apnea ventilation", "It switches to CPAP with no support", "It stops ventilating"], "correct": 0, "explanation": "Automode: sleeping patient → PRVC; awake patient (two triggered breaths) → Volume Support.", "srcItem": "PRVC (Pressure-Regulated Volume Control)"},
    {"id": "q-f203-g03-022", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is Volume Control Plus (VC+) on the PB 840?", "choices": ["Puritan Bennett's version of PRVC", "A form of APRV", "A type of HFOV", "A CPAP mode"], "correct": 0, "explanation": "VC+ = PB's PRVC: preset VT and I-time with variable pressure and flow.", "srcItem": "VV+ (Volume Ventilation Plus, PB 840)"},
    {"id": "q-f203-g03-023", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does Volume Support differ from pressure support?", "choices": ["VS guarantees volume and lets pressure vary; PS guarantees pressure and lets volume vary", "VS is time-cycled; PS is flow-cycled", "VS needs a set rate; PS does not", "They are identical"], "correct": 0, "explanation": "Both are patient-triggered, pressure-limited, flow-cycled; VS targets volume.", "srcItem": "VV+ (Volume Ventilation Plus, PB 840)"},
    {"id": "q-f203-g03-024", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On Volume Support, the patient makes more effort. What happens to the support pressure?", "choices": ["It decreases", "It increases", "It stays fixed", "It drops to zero immediately"], "correct": 0, "explanation": "Less effort → higher PS; more effort → lower PS, to hold the target VT.", "srcItem": "VV+ (Volume Ventilation Plus, PB 840)"},
    {"id": "q-f203-g03-025", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does PAV target?", "choices": ["No set flow, volume or pressure — support is proportional to the patient's effort", "A fixed tidal volume", "A fixed inspiratory pressure", "A fixed minute ventilation"], "correct": 0, "explanation": "\"With PAV there is no target flow, volume, or pressure\"; pull harder → more assist.", "srcItem": "PAV (Proportional Assist Ventilation)"},
    {"id": "q-f203-g03-026", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What happens if the PAV % assist is set too high?", "choices": ["'Runaway' with excessive volume and pressure", "Excessive patient work of breathing", "Apnea", "Hypoxemia from low FiO₂"], "correct": 0, "explanation": "Too high → runaway; too low → excessive patient WOB.", "srcItem": "PAV (Proportional Assist Ventilation)"},
    {"id": "q-f203-g03-027", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which patient is NOT suitable for PAV?", "choices": ["An apneic patient with no respiratory drive", "A COPD patient being weaned", "A patient coming off sedation", "A patient with variable drive"], "correct": 0, "explanation": "PAV requires intact drive and a functional neuromuscular system.", "srcItem": "PAV (Proportional Assist Ventilation)"},
    {"id": "q-f203-g03-028", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is APRV defined in the decks?", "choices": ["Inverse ratio, pressure-controlled IMV with unrestricted spontaneous breathing", "Volume-controlled CMV with high rates", "High-frequency oscillation", "Pressure support with backup rate"], "correct": 0, "explanation": "APRV: inverse ratio, pressure-controlled, intermittent mandatory ventilation with unrestricted spontaneous breathing.", "srcItem": "APRV (Airway Pressure Release Ventilation)"},
    {"id": "q-f203-g03-029", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which settings are used in APRV?", "choices": ["FiO₂, Phigh, Plow, Thigh and Tlow", "VT, rate, PEEP and flow", "Amplitude, Hz and mean airway pressure", "Target V̇E only"], "correct": 0, "explanation": "APRV has no VT or rate setting; Thigh and Tlow set the release frequency.", "srcItem": "APRV (Airway Pressure Release Ventilation)"},
    {"id": "q-f203-g03-030", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How long does an adult spend at Plow during APRV (Hess)?", "choices": ["About 0.2–0.8 seconds", "About 5 seconds", "About 30 seconds", "Half of each cycle"], "correct": 0, "explanation": "Tlow 0.2–0.8 s; 80–95% of the cycle is at Phigh, producing intrinsic PEEP.", "srcItem": "APRV (Airway Pressure Release Ventilation)"},
    {"id": "q-f203-g03-031", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On HFOV, how is CO₂ removal improved?", "choices": ["Increase the amplitude or decrease the frequency (Hz)", "Increase the frequency", "Increase the mean airway pressure", "Increase the FiO₂"], "correct": 0, "explanation": "↓ Hz → larger oscillatory VT → ↑ CO₂ removal — \"backwards from conventional ventilation.\"", "srcItem": "HFOV (High-Frequency Oscillatory Ventilation)"},
    {"id": "q-f203-g03-032", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On HFOV, how is oxygenation improved?", "choices": ["Increase the mean airway pressure or FiO₂", "Decrease the amplitude", "Increase the frequency", "Decrease the bias flow"], "correct": 0, "explanation": "Oxygenation: ↑ mean airway pressure or ↑ FiO₂.", "srcItem": "HFOV (High-Frequency Oscillatory Ventilation)"},
    {"id": "q-f203-g03-033", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does HFOV exhalation differ from conventional ventilation?", "choices": ["Exhalation is active — the oscillator pulls gas out", "Exhalation is passive", "There is no exhalation", "Exhalation is time-cycled at 1 Hz"], "correct": 0, "explanation": "HFOV actively pushes gas in and pulls it out; conventional exhalation is passive.", "srcItem": "HFOV (High-Frequency Oscillatory Ventilation)"},
    {"id": "q-f203-g03-034", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which mode gives a target VT at the lowest PIP with pressure auto-adjusted breath to breath?", "choices": ["PRVC", "PAV", "MMV", "APRV"], "correct": 0, "explanation": "Side-by-side table: PRVC = target VT at lowest PIP, pressure auto-adjusted.", "srcItem": "All the Listed Modes Side by Side"},
    {"id": "q-f203-g03-035", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which mode is listed as historical and not offered on new adult ventilators?", "choices": ["IMV (unsynchronized)", "SIMV", "PRVC", "Pressure support"], "correct": 0, "explanation": "IMV causes breath stacking; all current ventilators offer SIMV instead.", "srcItem": "All the Listed Modes Side by Side"},
    {"id": "q-f203-g03-036", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is patient–ventilator asynchrony?", "choices": ["The ventilator's breath delivery is out of phase with the patient's effort", "The patient's heart rate is irregular", "The ventilator alarms are silenced", "The FiO₂ is set incorrectly"], "correct": 0, "explanation": "Hess: synchrony = breath delivery in phase with patient effort; asynchrony = out of phase.", "srcItem": "Patient–Ventilator Asynchrony"},
    {"id": "q-f203-g03-037", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is a consequence of patient–ventilator asynchrony?", "choices": ["Increased WOB and sedation needs, and longer ventilation", "Lower oxygen cost of breathing", "Shorter weaning", "Improved comfort"], "correct": 0, "explanation": "Asynchrony decreases comfort, increases WOB and sedation needs, and prolongs ventilation.", "srcItem": "Patient–Ventilator Asynchrony"},
    {"id": "q-f203-g03-038", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A COPD patient's respiratory rate is higher than the ventilator's measured rate. What is the likely cause?", "choices": ["Auto-PEEP preventing some efforts from triggering", "An overly sensitive trigger", "A circuit leak", "Cardiac oscillations"], "correct": 0, "explanation": "Patient rate > ventilator rate means efforts are missed, commonly from auto-PEEP raising the trigger threshold.", "srcItem": "Patient–Ventilator Asynchrony"},
    {"id": "q-f203-g03-039", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "During VC, a vigorous patient effort pulls the pressure waveform downward and PIP varies breath to breath. What is the problem?", "choices": ["Flow starvation (flow asynchrony)", "Auto-triggering", "Delayed cycling", "Excess PEEP"], "correct": 0, "explanation": "The ventilator isn't meeting inspiratory flow demand; fix by raising flow or switching to PC/PS.", "srcItem": "Flow and Cycle Asynchrony"},
    {"id": "q-f203-g03-040", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A pressure dip early in inspiration on the waveform suggests what?", "choices": ["Inadequate peak flow — 'I need more flow'", "Too much volume", "Delayed cycling", "A leak"], "correct": 0, "explanation": "Early dip = \"I need more flow\"; late dip = \"I want more volume.\"", "srcItem": "Flow and Cycle Asynchrony"},
    {"id": "q-f203-g03-041", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A patient receives a second breath almost immediately after the first, nearly doubling the set VT. What is this?", "choices": ["Double triggering from premature cycling", "Auto-PEEP", "Delayed cycling", "Flow starvation only"], "correct": 0, "explanation": "Premature cycling: the patient's effort continues after the breath ends and double-triggers.", "srcItem": "Flow and Cycle Asynchrony"},
    {"id": "q-f203-g03-042", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the recommended order for fixing asynchrony?", "choices": ["Adjust settings → reconsider the mode → sedation/analgesia → neuromuscular blockade last", "Paralyze first, then adjust settings", "Change the mode first, then sedate", "Sedate heavily, then never paralyze"], "correct": 0, "explanation": "Troubleshoot and adjust settings first; \"Paralytics don't fix problems — they hide them.\"", "srcItem": "Mode Asynchrony and the Fix Sequence"},
    {"id": "q-f203-g03-043", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does Hess call a common cause of failure to breathe in synchrony with the ventilator?", "choices": ["Anxiety", "Low FiO₂", "High PEEP", "A cuff leak"], "correct": 0, "explanation": "\"Anxiety is a common cause of failure to breathe in synchrony with the ventilator.\"", "srcItem": "Mode Asynchrony and the Fix Sequence"},
    {"id": "q-f203-g03-044", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why can SIMV itself cause mode asynchrony?", "choices": ["The respiratory center cannot adapt to the varying breath types", "SIMV has no mandatory breaths", "SIMV always uses HFOV", "SIMV gives identical breaths"], "correct": 0, "explanation": "Mode asynchrony occurs when the ventilator delivers different breath types, as in SIMV.", "srcItem": "Mode Asynchrony and the Fix Sequence"},
    {"id": "q-f203-g03-045", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is normal adult inspiratory flow per the Principles deck?", "choices": ["40–60 L/min", "5–10 L/min", "100–150 L/min", "200 L/min"], "correct": 0, "explanation": "Principles deck: normal adult inspiratory flow = 40–60 L/min.", "srcItem": "Ventilator Variables"},
    {"id": "q-f203-g03-046", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "With constant flow of 60 L/min for 1 second, what tidal volume is delivered?", "choices": ["1 L", "60 mL", "6 L", "0.5 L"], "correct": 0, "explanation": "60 L/min = 1 L/s; VT = flow × TI = 1 L.", "srcItem": "Ventilator Variables"},
    {"id": "q-f203-g03-047", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What are the three control variables per the Principles deck?", "choices": ["Volume, pressure and time", "Trigger, limit and cycle", "Flow, FiO₂ and PEEP", "Rate, VT and I:E"], "correct": 0, "explanation": "Control variables: volume, pressure and time; trigger/limit/cycle are phase variables.", "srcItem": "Ventilator Variables"},
    {"id": "q-f203-g03-048", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the 'independent variable' on a ventilator?", "choices": ["Whatever the ventilator guarantees", "Whatever changes with the patient", "The alarm limit", "The FiO₂ only"], "correct": 0, "explanation": "\"Whatever the ventilator guarantees is called the independent variable\"; the other floats.", "srcItem": "Independent vs Dependent Variables"},
    {"id": "q-f203-g03-049", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In PC, which change increases the delivered VT?", "choices": ["A higher driving pressure (PIP − PEEP)", "More auto-PEEP", "Lower compliance", "Higher resistance"], "correct": 0, "explanation": "Box 20-5: VT rises with ↑ driving pressure, longer TI (while flow present) and more effort.", "srcItem": "Independent vs Dependent Variables"},
    {"id": "q-f203-g03-050", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In VC, which change raises PIP?", "choices": ["Increased airway resistance", "Switching to descending-ramp flow", "Lower VT", "Improved compliance"], "correct": 0, "explanation": "Box 20-4: PIP rises with ↑ flow, constant flow, ↑ PEEP, auto-PEEP, ↑ VT, ↑ Raw, ↓ compliance.", "srcItem": "Independent vs Dependent Variables"},
    {"id": "q-f203-g03-051", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What starts a time-triggered breath?", "choices": ["A clinician-set rate or timer", "A patient's negative deflection", "A drop in circuit flow", "A cough"], "correct": 0, "explanation": "Rate 12 → a breath every 5 s; time-triggered breaths show no negative deflection.", "srcItem": "Trigger: What Starts the Breath"},
    {"id": "q-f203-g03-052", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Base flow is 10 L/min and flow sensitivity is 3 L/min. When does the ventilator trigger?", "choices": ["When expiratory-circuit flow drops to 7 L/min", "When flow rises to 13 L/min", "When flow drops to 3 L/min", "When flow drops to zero"], "correct": 0, "explanation": "Hess's example: it triggers at 7 L/min, assuming the patient inhaled 3 L/min.", "srcItem": "Trigger: What Starts the Breath"},
    {"id": "q-f203-g03-053", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A trigger set at −5 cm H₂O is too insensitive. What results?", "choices": ["The patient may not be able to trigger and fatigues", "Auto-triggering", "Double triggering", "Excess VT"], "correct": 0, "explanation": "Too high (not sensitive enough) → can't trigger; too sensitive (−0.5) → auto-trigger.", "srcItem": "Trigger: What Starts the Breath"},
    {"id": "q-f203-g03-054", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "According to the deck's memory line, how is pressure control cycled?", "choices": ["Time-cycled", "Volume-cycled", "Flow-cycled", "Pressure-cycled"], "correct": 0, "explanation": "\"Volume Control is volume-cycled. Pressure Control is time-cycled. PSV is flow-cycled.\"", "srcItem": "Cycle: What Ends the Breath"},
    {"id": "q-f203-g03-055", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When does pressure cycling most often occur?", "choices": ["As an alarm condition when the high-pressure limit is reached", "In every PS breath", "In every VC breath", "Only in HFOV"], "correct": 0, "explanation": "Pressure cycling most often occurs as a high-pressure alarm condition (e.g. a cough during VC).", "srcItem": "Cycle: What Ends the Breath"},
    {"id": "q-f203-g03-056", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is Volume Support classified (trigger/limit/cycle)?", "choices": ["Patient / pressure / flow", "Time / volume / time", "Patient / volume / volume", "Time / pressure / time"], "correct": 0, "explanation": "VS: patient-triggered, pressure-limited, flow-cycled — like PS but volume-targeted.", "srcItem": "Cycle: What Ends the Breath"},
    {"id": "q-f203-g03-057", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the number one ventilator adjustment for improving oxygenation?", "choices": ["PEEP", "Respiratory rate", "Tidal volume", "Inspiratory flow"], "correct": 0, "explanation": "Pearl: PEEP is primarily an oxygenation intervention, not a ventilation intervention.", "srcItem": "PEEP: What It Is, What It Does, How Much"},
    {"id": "q-f203-g03-058", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does PEEP improve oxygenation?", "choices": ["It keeps alveoli open at end-expiration, increasing FRC and reducing shunt", "It increases the respiratory rate", "It removes CO₂ directly", "It decreases FRC"], "correct": 0, "explanation": "PEEP prevents end-expiratory collapse → ↑ FRC → ↑ V/Q → better oxygenation.", "srcItem": "PEEP: What It Is, What It Does, How Much"},
    {"id": "q-f203-g03-059", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is CPAP?", "choices": ["PEEP applied to a patient breathing entirely on their own", "A mandatory mode", "Pressure support with backup rate", "A high-frequency mode"], "correct": 0, "explanation": "CPAP = PEEP with all spontaneous breaths; on BiPAP, EPAP = PEEP.", "srcItem": "PEEP: What It Is, What It Does, How Much"},
    {"id": "q-f203-g03-060", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What PEEP level is associated with an increased incidence of barotrauma?", "choices": ["> 10 cm H₂O", "> 3 cm H₂O", "> 5 cm H₂O", "> 30 cm H₂O"], "correct": 0, "explanation": "\"PEEP > 10 (or P̄aw > 30, or PIP > 50) is associated with increased alveolar rupture or barotrauma.\"", "srcItem": "PEEP Complications and the Dangerous Level"},
    {"id": "q-f203-g03-061", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the major downside of PEEP?", "choices": ["Decreased venous return, cardiac output and blood pressure", "Increased venous return", "Hypercapnia", "Increased FRC"], "correct": 0, "explanation": "↑ PEEP → ↑ intrathoracic pressure → ↓ venous return → ↓ CO → ↓ BP.", "srcItem": "PEEP Complications and the Dangerous Level"},
    {"id": "q-f203-g03-062", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How can PEEP raise ICP?", "choices": ["Higher intrathoracic pressure impedes venous drainage from the brain", "It dilates cerebral arteries", "It lowers PaCO₂", "It increases CSF production"], "correct": 0, "explanation": "PEEP raises intrathoracic pressure, impeding cerebral venous drainage.", "srcItem": "PEEP Complications and the Dangerous Level"},
    {"id": "q-f203-g03-063", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is auto-PEEP?", "choices": ["Unintentional PEEP from gas trapped because exhalation did not finish before the next breath", "PEEP set by the clinician", "PEEP produced by a leak", "PEEP used only in neonates"], "correct": 0, "explanation": "Auto-PEEP (intrinsic, inadvertent, occult PEEP) = trapped gas; total PEEP = set PEEP + auto-PEEP.", "srcItem": "Auto-PEEP"},
    {"id": "q-f203-g03-064", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is auto-PEEP detected on the flow–time waveform?", "choices": ["Expiratory flow does not return to zero before the next breath", "Inspiratory flow is square", "Pressure returns to baseline", "There is a negative deflection before every breath"], "correct": 0, "explanation": "Expiratory flow failing to reach baseline before the next breath = air trapping.", "srcItem": "Auto-PEEP"},
    {"id": "q-f203-g03-065", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is auto-PEEP measured?", "choices": ["An end-expiratory pause; pause pressure minus set PEEP", "An end-inspiratory pause; Pplat minus PEEP", "PIP minus Pplat", "Exhaled VT minus set VT"], "correct": 0, "explanation": "Occlude just before the next breath; e.g. 12 − 5 = 7 cm H₂O auto-PEEP. The patient must be relaxed.", "srcItem": "Auto-PEEP"},
    {"id": "q-f203-g03-066", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does PIP overcome, compared with plateau pressure?", "choices": ["PIP overcomes resistance and compliance; Pplat overcomes compliance only", "PIP overcomes compliance only; Pplat overcomes resistance", "Both overcome only resistance", "Both overcome only compliance"], "correct": 0, "explanation": "Pplat is measured with no flow, so it excludes airway resistance; PIP − Pplat = flow × resistance.", "srcItem": "High Pressures and Their Causes"},
    {"id": "q-f203-g03-067", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PIP rises from 25 to 40 cm H₂O while Pplat stays at 20. What is the likely cause?", "choices": ["Increased airway resistance, such as secretions or bronchospasm", "Decreased compliance, such as ARDS", "Pneumothorax", "Atelectasis"], "correct": 0, "explanation": "\"When only PIP moves, think airways.\"", "srcItem": "High Pressures and Their Causes"},
    {"id": "q-f203-g03-068", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PIP and Pplat both rise by 10 cm H₂O. What is the likely cause?", "choices": ["Decreased compliance, such as pulmonary edema or pneumothorax", "Mucus plug in the ETT", "Patient biting the tube", "Water in the circuit"], "correct": 0, "explanation": "\"When PIP and Plateau move together, think lungs.\"", "srcItem": "High Pressures and Their Causes"},
    {"id": "q-f203-g03-069", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "According to Hess, what is the most important ventilator alarm?", "choices": ["The patient-disconnect alarm", "The high FiO₂ alarm", "The low battery alarm", "The high rate alarm"], "correct": 0, "explanation": "Hess: the patient-disconnect alarm — a low-pressure and/or low exhaled volume alarm.", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f203-g03-070", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Expired VT is lower than set VT on every breath and PIP is lower than before. What is the problem?", "choices": ["A leak", "Air trapping", "Bronchospasm", "Pneumothorax"], "correct": 0, "explanation": "A leak is low on every breath; with air trapping, expired VT is low for 2–3 breaths, then high.", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f203-g03-071", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "The low PEEP alarm sounds. What is the usual cause?", "choices": ["A leak in the circuit or ETT cuff", "Auto-PEEP", "Bronchospasm", "An overly sensitive trigger"], "correct": 0, "explanation": "\"Failure of the circuit to hold PEEP is usually due to leakage in the circuit or ETT cuff.\"", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f203-g03-072", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which circuit type is used on noninvasive ventilators?", "choices": ["Single-limb without an exhalation valve (a leak port)", "Double-limb with a wye", "Single-limb with a mushroom valve only", "No circuit"], "correct": 0, "explanation": "NIV uses a known leak port; the ventilator calculates and subtracts the leak.", "srcItem": "Ventilator Circuits"},
    {"id": "q-f203-g03-073", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where is the exhalation valve in a double-limb (wye) ICU circuit?", "choices": ["Built into the ventilator", "At the patient end", "In the humidifier", "There is none"], "correct": 0, "explanation": "Double-limb circuits carry exhaled gas back to the ventilator's expiratory/PEEP valve.", "srcItem": "Ventilator Circuits"},
    {"id": "q-f203-g03-074", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Circuit compliance is 3 mL/cm H₂O, PIP 60 and PEEP 10. How much volume is compressed in the circuit?", "choices": ["150 mL", "30 mL", "180 mL", "600 mL"], "correct": 0, "explanation": "3 mL/cm H₂O × (60 − 10) = 150 mL; corrected VT = expired VT − 150 mL.", "srcItem": "Ventilator Circuits"},
    {"id": "q-f203-g03-075", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What are the two jobs of the exhalation valve?", "choices": ["Separate inspiration from expiration and set PEEP", "Humidify gas and filter bacteria", "Measure FiO₂ and trigger breaths", "Warm the gas and measure VT"], "correct": 0, "explanation": "Closed in inspiration, open for exhalation; the expiratory valve controls PEEP.", "srcItem": "Exhalation Valves"},
    {"id": "q-f203-g03-076", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which circuit obstruction is the more serious?", "choices": ["Expiratory obstruction — it can cause rebreathing, asphyxia or barotrauma", "Inspiratory obstruction", "Humidifier obstruction", "Temperature probe obstruction"], "correct": 0, "explanation": "Expiratory obstruction is more serious; it comes with low-volume and high-pressure alarms.", "srcItem": "Exhalation Valves"},
    {"id": "q-f203-g03-077", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why must the expiratory valve be checked during aerosolized ribavirin?", "choices": ["Ribavirin can crystallize and occlude valves and sensors", "Ribavirin raises the FiO₂", "Ribavirin dissolves the circuit", "Ribavirin causes auto-triggering"], "correct": 0, "explanation": "Ribavirin crystals impair expiratory valves and sensors; watch for ↑ peak pressures.", "srcItem": "Exhalation Valves"},
    {"id": "q-f203-g03-078", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the equation of motion describe?", "choices": ["The pressure needed to deliver a breath to overcome airway resistance and lung/chest wall elastance", "The relationship between FiO₂ and PaO₂", "Cardiac output", "The oxygen content of blood"], "correct": 0, "explanation": "Pressure must overcome R × flow (resistive load) and E × volume (elastic load).", "srcItem": "The Equation of Motion"},
    {"id": "q-f203-g03-079", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In the equation of motion, what is elastance?", "choices": ["The inverse of compliance", "The same as resistance", "The flow rate", "The PEEP level"], "correct": 0, "explanation": "E = respiratory system elastance (lungs + chest wall), the inverse of compliance.", "srcItem": "The Equation of Motion"},
    {"id": "q-f203-g03-080", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "During full ventilatory support, what is Pmus in the equation of motion?", "choices": ["Zero — all pressure comes from the ventilator", "Equal to Paw", "Equal to PEEP", "Maximal"], "correct": 0, "explanation": "Full support: Pmus = 0. Spontaneous breathing: Paw = 0. Partial: both contribute.", "srcItem": "The Equation of Motion"},
    {"id": "q-f203-g03-081", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which four ventilator modes does the Ch 11 deck say to 'KNOW THESE' for the NBRC?", "choices": ["VC-A/C, VC-SIMV, PC-A/C and PC-SIMV", "APRV, HFOV, PAV and NAVA", "CPAP, BiPAP, HFNC and NC", "MMV, ASV, ATC and IRV"], "correct": 0, "explanation": "Control variable (volume or pressure) × A/C or SIMV; PS and PEEP are add-ons.", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f203-g03-082", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "According to the Ch 11 deck, what are the three categories of patient–ventilator asynchrony?", "choices": ["Trigger, flow and cycle", "Trigger, cycle and mode", "Rate, volume and pressure", "Leak, kink and secretion"], "correct": 0, "explanation": "Use the deck's trigger, flow, cycle (Hess says trigger, cycle, mode).", "srcItem": "Patient–Ventilator Asynchrony"},
    {"id": "q-f203-g03-083", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is adult HFOV weaned per the Ch 11 deck?", "choices": ["FiO₂ to 0.40 first, then lower mean airway pressure 2–3 cm H₂O every 4–6 h to ≤ 20, then switch to PC", "Raise the amplitude to maximum", "Stop it abruptly and extubate", "Lower the FiO₂ only"], "correct": 0, "explanation": "Then consider PC (limit ≤ 30, PEEP 10–12) and a standard SBT.", "srcItem": "HFOV (High-Frequency Oscillatory Ventilation)"},
    {"id": "q-f203-g03-084", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where does the Ch 11 deck set the high-pressure alarm before PIP is measured?", "choices": ["35 cm H₂O, then 10 above the observed PIP once stable", "60 cm H₂O permanently", "Equal to the PEEP", "5 cm H₂O below PIP"], "correct": 0, "explanation": "Ch 11 (AARC): 35 initially, then 10 above observed PIP.", "srcItem": "High Pressures and Their Causes"},
    {"id": "q-f203-g03-085", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where does the Ch 11 deck set the low inspiratory pressure alarm?", "choices": ["10 cm H₂O below the observed PIP (or the set pressure in PC)", "At the PEEP level", "Above the PIP", "At 0 cm H₂O"], "correct": 0, "explanation": "With the low VT alarm (150 mL above and below set VT), it detects leaks or disconnection.", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f203-g03-086", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "The volume–time curve does not return to baseline. What does the Ch 11 deck say this means?", "choices": ["A leak — often the ETT cuff", "Auto-PEEP", "Bronchospasm", "Normal ventilation"], "correct": 0, "explanation": "Likely on the NBRC: find the leak (cuff, connections, humidifier, mask, chest tube/BPF).", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f203-g03-087", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is static compliance calculated, and what pressure is ignored?", "choices": ["VT ÷ (Pplat − PEEP); ignore PIP", "VT ÷ (PIP − PEEP); ignore Pplat", "(PIP − Pplat) ÷ flow", "VT × (Pplat − PEEP)"], "correct": 0, "explanation": "Ch 11: in a static-compliance table, disregard PIP — \"it is there to confuse you.\"", "srcItem": "Static and Dynamic Compliance"},
    {"id": "q-f203-g03-088", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "VT 600 mL, Pplat 27, PEEP 10, PIP 40. What is the static compliance?", "choices": ["About 35 mL/cm H₂O", "About 20 mL/cm H₂O", "About 60 mL/cm H₂O", "About 15 mL/cm H₂O"], "correct": 0, "explanation": "600 ÷ (27 − 10) = 35.3; PIP is a distractor.", "srcItem": "Static and Dynamic Compliance"},
    {"id": "q-f203-g03-089", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What normal static compliance does RCP 203 give for intubated adults?", "choices": ["40–80 mL/cm H₂O", "5–10 mL/cm H₂O", "150–200 mL/cm H₂O", "20–25 mL/cm H₂O"], "correct": 0, "explanation": "Use RCP 203's 40–80; < 25–30 → ↑ WOB and weaning difficulty.", "srcItem": "Static and Dynamic Compliance"},
    {"id": "q-f203-g03-090", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does dynamic compliance compare with static compliance?", "choices": ["It is always less, the difference being airway resistance", "It is always greater", "They are equal", "It cannot be calculated"], "correct": 0, "explanation": "Cdyn = VT ÷ (PIP − PEEP); PIP includes resistive pressure.", "srcItem": "Static and Dynamic Compliance"},
    {"id": "q-f203-g03-091", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is alveolar ventilation calculated?", "choices": ["f × (VT − VD)", "VT × f", "VD ÷ VT", "f ÷ VT"], "correct": 0, "explanation": "V̇A accounts for dead space; V̇E = VT × f does not.", "srcItem": "Minute Ventilation vs Alveolar Ventilation"},
    {"id": "q-f203-g03-092", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A 125-lb patient breathes 15/min with VT 400 mL. What is the alveolar ventilation?", "choices": ["About 4,125 mL/min", "6,000 mL/min", "400 mL/min", "1,875 mL/min"], "correct": 0, "explanation": "15 × (400 − 125) = 4,125 mL/min; V̇E = 6,000 mL/min.", "srcItem": "Minute Ventilation vs Alveolar Ventilation"},
    {"id": "q-f203-g03-093", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does lowering VT affect VD/VT?", "choices": ["It raises VD/VT and lowers alveolar ventilation", "It lowers VD/VT", "It has no effect", "It eliminates dead space"], "correct": 0, "explanation": "150/500 = 30% → 150/300 = 50%.", "srcItem": "Minute Ventilation vs Alveolar Ventilation"},
    {"id": "q-f203-g03-094", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How much water vapor does fully saturated gas hold at 37 °C?", "choices": ["44 mg/L", "10 mg/L", "100 mg/L", "4 mg/L"], "correct": 0, "explanation": "At 37 °C, 100% RH = 44 mg/L.", "srcItem": "Relative Humidity and Rain-Out"},
    {"id": "q-f203-g03-095", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Condensate is visible in the inspiratory tubing near the patient. What does this indicate?", "choices": ["The gas is fully saturated (100% RH)", "The gas is dry", "The humidifier is off", "The temperature is too low to matter"], "correct": 0, "explanation": "No visible condensate = RH could be anywhere 0–99%.", "srcItem": "Relative Humidity and Rain-Out"},
    {"id": "q-f203-g03-096", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How should circuit condensate be handled?", "choices": ["Drained with gloves away from the patient and discarded as contaminated waste", "Poured back into the humidifier", "Drained toward the patient", "Left in the tubing"], "correct": 0, "explanation": "Never let it reach the airway; never return it to the reservoir.", "srcItem": "Relative Humidity and Rain-Out"},
    {"id": "q-f203-g03-097", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What humidity does an HME provide per the deck?", "choices": ["70–90% RH at 30–31 °C", "100% RH at 37 °C", "10% RH at 20 °C", "Any humidity, depending on flow"], "correct": 0, "explanation": "Heated humidifier: near 100% RH at body temperature; HME 70–90% at 30–31 °C.", "srcItem": "Relative Humidity and Rain-Out"},
    {"id": "q-f203-g03-098", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What happens if cuff pressure is too high?", "choices": ["Tracheal mucosal ischemia, ulceration and necrosis", "Leakage-type aspiration", "Hypoventilation", "Auto-PEEP"], "correct": 0, "explanation": "Too high (> 25–30) obstructs mucosal blood flow; too low (< 20) allows aspiration.", "srcItem": "Cuff Pressures"},
    {"id": "q-f203-g03-099", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A cuff needs more than 30 cm H₂O to seal. What does this suggest?", "choices": ["The tube may be too small — evaluate and recommend exchange", "Normal function", "The patient needs more PEEP", "The cuff is overinflated on purpose"], "correct": 0, "explanation": "Rising pressures over time suggest tracheal dilation or cuff/pilot balloon malfunction.", "srcItem": "Cuff Pressures"},
    {"id": "q-f203-g03-100", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Is the minimal leak technique recommended for cuff management?", "choices": ["No — it is no longer recommended", "Yes, for all patients", "Only for LMAs", "Only in children"], "correct": 0, "explanation": "RCP 203 and the VAP strategies: avoid the minimal leak technique.", "srcItem": "Cuff Pressures"},
    {"id": "q-f203-g03-101", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What pressure is the King LT cuff inflated to?", "choices": ["About 60 cm H₂O", "About 25 cm H₂O", "About 10 cm H₂O", "About 100 cm H₂O"], "correct": 0, "explanation": "ETT 20–30; LMA ≤ 60; King LT ~60 cm H₂O.", "srcItem": "Cuff Pressures"},
    {"id": "q-f203-g03-102", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Rate 15, VT 600 mL, and the physician orders I:E 1:4. What inspiratory flow is needed?", "choices": ["45 L/min", "9 L/min", "36 L/min", "60 L/min"], "correct": 0, "explanation": "V̇E 9 L/min ÷ %I-time 0.20 = 45 L/min.", "srcItem": "I"},
    {"id": "q-f203-g03-103", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What %I-time corresponds to an I:E ratio of 1:2?", "choices": ["33%", "50%", "20%", "67%"], "correct": 0, "explanation": "1:4 = 20%, 1:3 = 25%, 1:2 = 33%, 1:1 = 50%, 2:1 = 67%.", "srcItem": "I"},
    {"id": "q-f203-g03-104", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A ventilated COPD patient has auto-PEEP with an I:E of 1:2. What should be done?", "choices": ["Decrease the ratio toward 1:4 or 1:5 by lengthening E-time", "Increase the ratio to 1:1", "Add inverse ratio ventilation", "Increase the rate"], "correct": 0, "explanation": "Severe obstruction needs long E-times; lowering the rate lengthens E-time.", "srcItem": "I"},
    {"id": "q-f203-g03-105", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the permissive hypercapnia floor in the Ch 13 deck?", "choices": ["pH below 7.25–7.30 — then raise the rate or give bicarbonate", "PaCO₂ above 50", "pH below 7.40", "PaCO₂ above 100"], "correct": 0, "explanation": "pH is the stop sign, not PaCO₂.", "srcItem": "I"},
    {"id": "q-f203-g03-106", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What must be programmed into the ventilator to use automatic tube compensation (ATC)?", "choices": ["The patient's airway type and size", "The patient's weight only", "The PEEP level", "The FiO₂"], "correct": 0, "explanation": "ATC dynamically offsets tube resistance for spontaneous breaths.", "srcItem": "I"},
    {"id": "q-f203-g03-107", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In the ARDSNet protocol, what VT is used at the start and the target?", "choices": ["Start 8 mL/kg PBW; reduce by 1 mL/kg to 6 mL/kg", "Start 12 mL/kg; keep it", "Start 4 mL/kg; raise to 10", "Start 6 mL/kg; raise to 8"], "correct": 0, "explanation": "Reduce 1 mL/kg at intervals ≤ 2 h until VT = 6 mL/kg PBW.", "srcItem": "The ARDSNet Protocol Step by Step (Ch 14)"},
    {"id": "q-f203-g03-108", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In ARDSNet, what is done if Pplat exceeds 30 cm H₂O?", "choices": ["Decrease VT in 1 mL/kg steps to a minimum of 4 mL/kg", "Increase the VT", "Increase the PEEP to 20", "Ignore it"], "correct": 0, "explanation": "Pplat ≤ 30; measure every 4 h and after each PEEP or VT change.", "srcItem": "The ARDSNet Protocol Step by Step (Ch 14)"},
    {"id": "q-f203-g03-109", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In ARDSNet, the pH is 7.10 with the rate already at 35. What is done?", "choices": ["Increase VT in 1 mL/kg steps until pH > 7.15; consider NaHCO₃", "Decrease the rate", "Lower the PEEP", "Stop ventilation"], "correct": 0, "explanation": "For pH < 7.15, raise rate to 35 first; then VT (Pplat may be exceeded).", "srcItem": "The ARDSNet Protocol Step by Step (Ch 14)"},
    {"id": "q-f203-g03-110", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What pH goal does the ARDSNet protocol use?", "choices": ["7.30–7.45", "7.20–7.25", "7.45–7.55", "7.10–7.20"], "correct": 0, "explanation": "pH goal 7.30–7.45; PaO₂ 55–80 or SpO₂ 88–95%.", "srcItem": "The ARDSNet Protocol Step by Step (Ch 14)"},
    {"id": "q-f203-g03-111", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does a recruitment maneuver do?", "choices": ["Briefly raises transpulmonary pressure to reopen collapsed alveoli", "Removes secretions", "Lowers PEEP to zero", "Increases the rate"], "correct": 0, "explanation": "Recruitment opens; adequate PEEP afterward keeps alveoli open.", "srcItem": "Recruitment Maneuvers and Decremental PEEP"},
    {"id": "q-f203-g03-112", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Are recruitment maneuvers routinely recommended in ARDS per the revised Ch 11 deck?", "choices": ["No — lung-protective ventilation, PEEP and proning come first", "Yes, every shift", "Yes, before every SBT", "Only with HFOV"], "correct": 0, "explanation": "Better oxygenation does not guarantee a better outcome.", "srcItem": "Recruitment Maneuvers and Decremental PEEP"},
    {"id": "q-f203-g03-113", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is decremental PEEP titration done after a recruitment maneuver?", "choices": ["Lower PEEP in small steps, then set it slightly above where compliance starts to fall", "Raise PEEP until the BP drops", "Remove all PEEP", "Set PEEP to 25 permanently"], "correct": 0, "explanation": "In the deck's example, PEEP was chosen at 18 cm H₂O.", "srcItem": "Recruitment Maneuvers and Decremental PEEP"},
    {"id": "q-f203-g03-114", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When should a recruitment maneuver be stopped?", "choices": ["If MAP falls below 60–65 mm Hg or the patient deteriorates", "When SpO₂ improves", "After 10 seconds always", "When the PIP reaches 25"], "correct": 0, "explanation": "Do RMs only in hemodynamically stable patients (MAP ≥ 65).", "srcItem": "Recruitment Maneuvers and Decremental PEEP"},
    {"id": "q-f203-g03-115", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Is there a sourced 'normal' range for adult PIP?", "choices": ["No — sources give only ceilings, such as 'safe' < 50 cm H₂O", "Yes — 5–10 cm H₂O", "Yes — 40–60 cm H₂O", "Yes — exactly 25 cm H₂O"], "correct": 0, "explanation": "Only ceilings exist; Pplat is the one to watch (< 30).", "srcItem": "Normal (Target) Levels of PIP, Pplat and PEEP"},
    {"id": "q-f203-g03-116", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What Pplat ceiling should be used for this exam?", "choices": ["< 30 cm H₂O", "< 35 cm H₂O", "< 50 cm H₂O", "< 20 cm H₂O"], "correct": 0, "explanation": "Conflict: Chang prints < 35; use < 30 (ARDSNet, Hess, Ch 11).", "srcItem": "Normal (Target) Levels of PIP, Pplat and PEEP"},
    {"id": "q-f203-g03-117", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What low-level PEEP is often used to prevent atelectasis in ventilated patients (Hess)?", "choices": ["3–5 cm H₂O", "15–20 cm H₂O", "0 cm H₂O", "25 cm H₂O"], "correct": 0, "explanation": "Initial PEEP 5 (NBRC range 2–6); 'safe' < 10.", "srcItem": "Normal (Target) Levels of PIP, Pplat and PEEP"},
    {"id": "q-f203-g03-118", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What normal airway resistance does RCP 203 give for intubated adults?", "choices": ["5–12 cm H₂O/L/s", "0.1–0.5 cm H₂O/L/s", "20–40 cm H₂O/L/s", "50–80 cm H₂O/L/s"], "correct": 0, "explanation": "RCP 203 intubated normals: Crs 40–80 mL/cm H₂O, Raw 5–12 cm H₂O/L/s.", "srcItem": "Normal (Target) Levels of PIP, Pplat and PEEP"},
    {"id": "q-f203-g03-119", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does PIP − Pplat represent?", "choices": ["The airway-resistance (transairway) pressure", "The elastic pressure", "The auto-PEEP", "The PEEP"], "correct": 0, "explanation": "Depends on flow setting and airway resistance.", "srcItem": "What Each Pressure Tells You"},
    {"id": "q-f203-g03-120", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which pressure is used for the < 15 cm H₂O lung-protective driving-pressure limit?", "choices": ["Pplat − PEEP", "PIP − PEEP", "PIP − Pplat", "Mean airway pressure"], "correct": 0, "explanation": "In PC, VT is changed via ΔP = PIP − PEEP (Ch 11), but the < 15 limit is Pplat − PEEP.", "srcItem": "What Each Pressure Tells You"},
    {"id": "q-f203-g03-121", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why does Pplat reflect only compliance?", "choices": ["It is measured during an end-inspiratory hold with no flow", "It is measured during peak flow", "It includes airway resistance", "It is measured at end-expiration"], "correct": 0, "explanation": "No flow means no resistive pressure.", "srcItem": "What Each Pressure Tells You"},
    {"id": "q-f203-g03-122", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PIP rises while Pplat stays normal. What is the lung condition?", "choices": ["Increased airway resistance", "Decreased compliance", "Improved compliance", "A leak"], "correct": 0, "explanation": "Bronchospasm, secretions, edema, water in circuit, kinked ETT.", "srcItem": "Lung Condition When PIP and Pplat Rise or Fall"},
    {"id": "q-f203-g03-123", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PIP and Pplat rise together. Which is a likely cause?", "choices": ["Pleural effusion or pulmonary edema", "Bronchospasm", "Secretions in the ETT", "Water in the circuit"], "correct": 0, "explanation": "↓ compliance (stiff lungs): ARDS, edema, pneumonia, effusion, pneumothorax, mainstem intubation.", "srcItem": "Lung Condition When PIP and Pplat Rise or Fall"},
    {"id": "q-f203-g03-124", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PIP is lower than the previous breath on every breath, but pressure returns to baseline. What is it?", "choices": ["A circuit leak", "Auto-PEEP", "Bronchospasm", "Pneumothorax"], "correct": 0, "explanation": "A leak lowers PIP every breath.", "srcItem": "Lung Condition When PIP and Pplat Rise or Fall"},
    {"id": "q-f203-g03-125", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In pressure control, how does a stiffer lung show up?", "choices": ["As a fall in VT", "As a rise in PIP", "As a rise in PEEP", "No change at all"], "correct": 0, "explanation": "Pressure is fixed in PC, so worse mechanics reduce VT.", "srcItem": "Lung Condition When PIP and Pplat Rise or Fall"},
    {"id": "q-f203-g03-126", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What happens with too little PEEP?", "choices": ["Alveoli collapse, causing shunt and poor oxygenation", "Alveoli overdistend", "Cardiac output falls", "Barotrauma"], "correct": 0, "explanation": "Too little → collapse; too much → overdistension, barotrauma, ↓ CO.", "srcItem": "PEEP Too Low vs Too High"},
    {"id": "q-f203-g03-127", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the Ch 11 deck call optimal PEEP?", "choices": ["The PEEP that keeps SpO₂ ≥ 88–90% without lowering BP", "The highest tolerable PEEP", "Always 5 cm H₂O", "The PEEP that gives PaO₂ > 200"], "correct": 0, "explanation": "Optimal PEEP balances oxygenation against hemodynamics.", "srcItem": "PEEP Too Low vs Too High"},
    {"id": "q-f203-g03-128", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Is PEEP > 10 cm H₂O an absolute ceiling?", "choices": ["No — it is Chang's barotrauma risk threshold; ARDS may need more", "Yes — never exceed 10", "Yes — for all patients", "Only in children"], "correct": 0, "explanation": "Ch 11's optimal-PEEP examples are 15 and 18.", "srcItem": "PEEP Too Low vs Too High"},
    {"id": "q-f203-g03-129", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does raised intrathoracic pressure lower urine output?", "choices": ["Reduced cardiac output lowers renal blood flow, and ADH rises", "It increases renal blood flow", "It blocks the ureters", "It raises ANP"], "correct": 0, "explanation": "PPV → ↓ CO → ↓ renal flow; ↑ ADH and ↓ ANP retain fluid.", "srcItem": "Effects on the Body When Pressures Rise"},
    {"id": "q-f203-g03-130", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why can CVP rise with PEEP even though preload is falling?", "choices": ["Intrathoracic pressure raises the measured CVP while venous return falls", "PEEP adds blood volume", "CVP always equals preload", "The catheter moves"], "correct": 0, "explanation": "\"High CVP does not always mean lots of preload.\"", "srcItem": "Effects on the Body When Pressures Rise"},
    {"id": "q-f203-g03-131", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which organ is hit first by falling cardiac output from PPV?", "choices": ["The kidneys", "The liver", "The brain", "The lungs"], "correct": 0, "explanation": "The kidneys are more sensitive than the liver; hepatic perfusion falls only when PEEP is added.", "srcItem": "Effects on the Body When Pressures Rise"},
    {"id": "q-f203-g03-132", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How can PPV benefit a patient with left heart failure?", "choices": ["It lowers LV afterload", "It raises LV afterload", "It increases preload", "It has no cardiac effect"], "correct": 0, "explanation": "Hess: the drop in LV afterload can help fluid overload or LV failure.", "srcItem": "Effects on the Body When Pressures Rise"},
    {"id": "q-f203-g03-133", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does the deck define auto-PEEP in the pressures topic?", "choices": ["Residual alveolar pressure at end-exhalation from air trapping", "PEEP set by the clinician", "Pressure from a leak", "Pressure at peak inspiration"], "correct": 0, "explanation": "Aka occult/intrinsic PEEP, dynamic hyperinflation; common in COPD and asthma.", "srcItem": "Auto-PEEP: What It Is and How to Find It"},
    {"id": "q-f203-g03-134", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "End-expiratory pause pressure is 12 with set PEEP 5. What is the auto-PEEP?", "choices": ["7 cm H₂O", "17 cm H₂O", "5 cm H₂O", "12 cm H₂O"], "correct": 0, "explanation": "Auto-PEEP = pause pressure − set PEEP.", "srcItem": "Auto-PEEP: What It Is and How to Find It"},
    {"id": "q-f203-g03-135", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which graphic does the Ch 11 deck say is likely on the NBRC for auto-PEEP?", "choices": ["Expiratory flow not returning to zero before the next breath", "Volume curve not returning to baseline", "A pressure spike at end-inspiration", "A negative deflection before inspiration"], "correct": 0, "explanation": "Volume not returning to baseline = a leak; flow not returning to zero = air trapping.", "srcItem": "Auto-PEEP: What It Is and How to Find It"},
    {"id": "q-f203-g03-136", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which change does NOT help resolve auto-PEEP?", "choices": ["Increasing the respiratory rate", "Decreasing the respiratory rate", "Increasing inspiratory flow in VC", "Giving a bronchodilator"], "correct": 0, "explanation": "Fixes lengthen expiratory time: ↓ RR, ↑ flow, ↓ VT, ↓ TI, bronchodilators.", "srcItem": "How to Resolve Auto-PEEP"},
    {"id": "q-f203-g03-137", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How much extrinsic PEEP may be applied to counter auto-PEEP per RCP 203?", "choices": ["Up to 80–90% of measured auto-PEEP, in spontaneously breathing patients", "150% of auto-PEEP", "Equal to the PIP", "Never any PEEP"], "correct": 0, "explanation": "Use RCP 203's 80–90% (Hess: 75–85%); it helps patients trigger.", "srcItem": "How to Resolve Auto-PEEP"},
    {"id": "q-f203-g03-138", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which axes does a pressure–volume loop use?", "choices": ["Pressure on the x-axis, volume on the y-axis", "Volume on the x-axis, flow on the y-axis", "Time on both axes", "Flow on the x-axis, pressure on the y-axis"], "correct": 0, "explanation": "The P-V loop is the \"compliance\" loop.", "srcItem": "The Pressure-Volume (P-V) Loop: How to Read It"},
    {"id": "q-f203-g03-139", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the slope of the static P-V curve represent?", "choices": ["Compliance (ΔV/ΔP)", "Resistance", "Dead space", "Oxygen content"], "correct": 0, "explanation": "Ch 11: \"the higher the slope, the higher the compliance.\"", "srcItem": "The Pressure-Volume (P-V) Loop: How to Read It"},
    {"id": "q-f203-g03-140", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does a spontaneous breath look on a P-V loop?", "choices": ["Oval and symmetric with no sharp corners", "Well defined with sharp angles", "A straight vertical line", "A small trigger dip then machine assistance"], "correct": 0, "explanation": "Controlled = sharp angles; assisted = small trigger effort, then assistance.", "srcItem": "The Pressure-Volume (P-V) Loop: How to Read It"},
    {"id": "q-f203-g03-141", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Compliance decreases. How does the P-V loop shift?", "choices": ["Toward the pressure axis (right) and flatter", "Toward the volume axis (left) and steeper", "Upward with no tilt", "It disappears"], "correct": 0, "explanation": "↓ compliance: ↑ PIP and ↑ PAlv; ARDS, edema, atelectasis, fibrosis.", "srcItem": "Compliance Changes on the P-V Loop"},
    {"id": "q-f203-g03-142", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which condition shifts the P-V loop toward the volume axis (steeper)?", "choices": ["Emphysema", "ARDS", "Pulmonary edema", "Fibrosis"], "correct": 0, "explanation": "Emphysema has high compliance with poor recoil.", "srcItem": "Compliance Changes on the P-V Loop"},
    {"id": "q-f203-g03-143", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does PEEP or surfactant do to the P-V curve when compliance improves?", "choices": ["Makes it more vertical", "Makes it flatter", "Shifts it right", "Removes the loop"], "correct": 0, "explanation": "Improved compliance → steeper curve.", "srcItem": "Compliance Changes on the P-V Loop"},
    {"id": "q-f203-g03-144", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does a 'beak' (duckbill) at the top of the P-V loop indicate?", "choices": ["Overdistension from excessive VT", "Under-recruitment", "A leak", "Auto-PEEP"], "correct": 0, "explanation": "Beyond the UIP, small volume rises cause large pressure rises; reduce VT.", "srcItem": "Overdistension and the Inflection Points"},
    {"id": "q-f203-g03-145", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the lower inflection point?", "choices": ["The pressure where alveoli begin to open (critical opening pressure)", "The point of overdistension", "The end of exhalation", "The peak pressure"], "correct": 0, "explanation": "Below it the curve is flat (under-recruitment).", "srcItem": "Overdistension and the Inflection Points"},
    {"id": "q-f203-g03-146", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where does Ch 11 set PEEP relative to the lower inflection point?", "choices": ["Typically 2–3 cm H₂O above it", "Exactly at zero", "10 cm H₂O below it", "At the upper inflection point"], "correct": 0, "explanation": "Optimal PEEP = the lowest pressure that exceeds the LIP.", "srcItem": "Overdistension and the Inflection Points"},
    {"id": "q-f203-g03-147", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is overdistension on the P-V loop fixed?", "choices": ["Reduce VT until the beak disappears", "Increase VT", "Increase PEEP", "Increase the rate"], "correct": 0, "explanation": "Or use pressure control.", "srcItem": "Overdistension and the Inflection Points"},
    {"id": "q-f203-g03-148", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On the P-V loop, what does a wider loop indicate (exam answer)?", "choices": ["Higher airway resistance", "Lower resistance", "Higher compliance", "A leak"], "correct": 0, "explanation": "Use \"wider = more resistance\" (slide 74 notes; RCP 203 Ch 4).", "srcItem": "Resistance, Leaks, Auto-PEEP and WOB"},
    {"id": "q-f203-g03-149", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On which scalar does Ch 11 show a leak?", "choices": ["Volume–time: exhaled volume doesn't return to baseline", "Flow–time: flow doesn't return to zero", "Pressure–time: a spike", "None"], "correct": 0, "explanation": "Flow not returning to zero = auto-PEEP; volume not returning = leak.", "srcItem": "Resistance, Leaks, Auto-PEEP and WOB"},
    {"id": "q-f203-g03-150", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal work of breathing range that both books share?", "choices": ["0.5–0.7 J/L", "5–7 J/L", "50–70 J/L", "0.05 J/L"], "correct": 0, "explanation": "Hess 0.3–0.7, Heuer 0.5–0.7 J/L; 0.5–0.7 is the overlap.", "srcItem": "Resistance, Leaks, Auto-PEEP and WOB"},
    {"id": "q-f203-g03-151", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which loop should you 'think resistance' for?", "choices": ["The flow–volume loop", "The pressure–volume loop", "The pressure–time scalar", "The CO₂ waveform"], "correct": 0, "explanation": "\"Volume/Pressure Loop = compliance; Flow/Volume Loop = resistance.\"", "srcItem": "Flow-Volume Loop on the Ventilator"},
    {"id": "q-f203-g03-152", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On a ventilator flow–volume loop, what does bronchospasm do to the expiratory limb?", "choices": ["Lowers peak expiratory flow and makes the limb flatter", "Raises peak expiratory flow", "Changes only the inspiratory limb", "Nothing"], "correct": 0, "explanation": "Inspiratory flow is preset; look at the expiratory limb.", "srcItem": "Flow-Volume Loop on the Ventilator"},
    {"id": "q-f203-g03-153", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is bronchodilator response seen on a flow–volume loop?", "choices": ["Peak expiratory flow improves after the bronchodilator", "Inspiratory flow falls", "The loop disappears", "Volume falls"], "correct": 0, "explanation": "Ch 11 Fig 11-10: compare before and after.", "srcItem": "Flow-Volume Loop on the Ventilator"},
    {"id": "q-f203-g03-154", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which spirometry flow–volume shape fits obstruction?", "choices": ["A concave ('scooped') expiratory curve, L-shaped when severe", "An upside-down ice cream cone", "A normal sail", "A flat inspiratory limb only"], "correct": 0, "explanation": "Obstructive: concave downward; restrictive: tall narrow 'ice cream cone'.", "srcItem": "Spirometry Flow-Volume Loop Shapes"},
    {"id": "q-f203-g03-155", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Flow is reduced equally on inspiration and expiration. What does this suggest?", "choices": ["Fixed upper-airway obstruction such as tracheal stenosis", "Variable extrathoracic lesion", "Restrictive disease", "Normal lungs"], "correct": 0, "explanation": "A variable lesion (vocal cord paralysis) reduces flow only on forced inhalation.", "srcItem": "Spirometry Flow-Volume Loop Shapes"},
    {"id": "q-f203-g03-156", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which spirometry loop shape is restrictive?", "choices": ["An 'upside-down ice cream cone' with rapid emptying", "A scooped 'ocean wave'", "A flattened top and bottom", "A normal sail"], "correct": 0, "explanation": "Hess Ch 8.", "srcItem": "Spirometry Flow-Volume Loop Shapes"},
    {"id": "q-f203-g03-157", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which setting does RCP 105 say controls CO₂?", "choices": ["Rate", "FiO₂", "PEEP", "Flow trigger"], "correct": 0, "explanation": "\"Rate controls CO₂. FiO₂ and PEEP control oxygenation.\"", "srcItem": "The decision table"},
    {"id": "q-f203-g03-158", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A ventilated patient has respiratory acidosis. What does RCP 203 say to change first?", "choices": ["Increase the set rate (keeping it 12–24/min)", "Increase the FiO₂", "Increase the PEEP", "Decrease the VT"], "correct": 0, "explanation": "↑ rate first; if that fails, ↑ VT within 4–8 mL/kg PBW and Pplat ≤ 30.", "srcItem": "The decision table"},
    {"id": "q-f203-g03-159", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Will raising the FiO₂ lower a high PaCO₂?", "choices": ["No", "Yes, always", "Only above FiO₂ 0.80", "Only in COPD"], "correct": 0, "explanation": "Exam trap: raising FiO₂ does not lower PaCO₂.", "srcItem": "The decision table"},
    {"id": "q-f203-g03-160", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A COPD patient on the ventilator has PaCO₂ 55 and pH 7.37. What should be done?", "choices": ["Nothing to drive the PaCO₂ to 40 — the pH is normal", "Increase the rate to bring PaCO₂ to 40", "Decrease the rate", "Add 10 of PEEP"], "correct": 0, "explanation": "In chronic CO₂ retention a normal pH can come with PaCO₂ ≥ 55; don't force it to 40.", "srcItem": "The decision table"},
    {"id": "q-f203-g03-161", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Rate, VT and Pplat are at their limits and the pH is still below 7.30. What does RCP 203 allow?", "choices": ["Permissive hypercapnia, keeping pH above 7.20–7.25", "Increase the VT to 12 mL/kg", "Raise the Pplat to 45", "Stop ventilation"], "correct": 0, "explanation": "Let PaCO₂ rise as long as pH stays > 7.20–7.25.", "srcItem": "The decision table"},
    {"id": "q-f203-g03-162", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Set rate 14, PaCO₂ 60, desired PaCO₂ 40. What is the new rate?", "choices": ["21/min", "9/min", "28/min", "14/min"], "correct": 0, "explanation": "14 × 60 ÷ 40 = 840 ÷ 40 = 21.", "srcItem": "Calculating the new rate for a target PaCO₂"},
    {"id": "q-f203-g03-163", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why does raising the rate lower PaCO₂?", "choices": ["PaCO₂ varies inversely with alveolar ventilation", "Rate increases CO₂ production", "Rate raises the FiO₂", "Rate lowers dead space to zero"], "correct": 0, "explanation": "With constant CO₂ production, ↑ V̇E lowers PaCO₂.", "srcItem": "Calculating the new rate for a target PaCO₂"},
    {"id": "q-f203-g03-164", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the risk of setting a very high rate in COPD?", "choices": ["Shortened expiratory time causing air trapping and auto-PEEP", "Hypercapnia from too little ventilation", "Hypoxemia from low FiO₂", "Low airway pressures"], "correct": 0, "explanation": "Too high a rate shortens TE → air trapping and auto-PEEP.", "srcItem": "Calculating the new rate for a target PaCO₂"},
    {"id": "q-f203-g03-165", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A ventilated patient has a low PaCO₂ compensating for diabetic ketoacidosis. What should be done?", "choices": ["Do not reduce ventilation", "Reduce the rate to normalize PaCO₂", "Add dead space", "Lower the VT"], "correct": 0, "explanation": "A compensatory PaCO₂ must not be normalized.", "srcItem": "When the ABG says change the vent but you should not"},
    {"id": "q-f203-g03-166", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A patient's PaCO₂ drops because they are hypoxic. What is the correct action?", "choices": ["Fix the hypoxia first; don't reduce ventilation", "Reduce the rate", "Reduce the VT", "Increase the pressure support"], "correct": 0, "explanation": "Low PaCO₂ as a response to hypoxia: fix the hypoxia.", "srcItem": "When the ABG says change the vent but you should not"},
    {"id": "q-f203-g03-167", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "An ABG shows metabolic acidosis on the ventilator. What ventilator change is indicated?", "choices": ["None — don't increase support for a metabolic problem", "Increase the rate", "Increase the FiO₂", "Increase the PEEP"], "correct": 0, "explanation": "No ventilator adjustment for metabolic disorders; treat the cause.", "srcItem": "When the ABG says change the vent but you should not"},
    {"id": "q-f203-g03-168", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "pH 7.30, PaCO₂ 50 from oversedation. What does the deck say?", "choices": ["Find and correct the cause; increasing the rate is not the proper action", "Increase the rate immediately", "Decrease the FiO₂", "Switch to CPAP"], "correct": 0, "explanation": "For high PaCO₂ from oversedation or fatigue, correct the cause (e.g. delay weaning).", "srcItem": "When the ABG says change the vent but you should not"},
    {"id": "q-f203-g03-169", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Oxygenation is acceptable on less than 50% O₂. What should be adjusted to fine-tune it?", "choices": ["The FiO₂", "The PEEP", "The rate", "The VT"], "correct": 0, "explanation": "RCP 203: if acceptable on < 50% O₂, adjust FiO₂; if not, adjust PEEP.", "srcItem": "Oxygenation targets, FiO₂ limits, FiO₂ vs PEEP"},
    {"id": "q-f203-g03-170", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "As oxygenation improves, which is lowered first?", "choices": ["FiO₂ to ≤ 50%, then PEEP", "PEEP first, then FiO₂", "Both together", "Neither"], "correct": 0, "explanation": "Lower FiO₂ to ≤ 0.50 first, then PEEP.", "srcItem": "Oxygenation targets, FiO₂ limits, FiO₂ vs PEEP"},
    {"id": "q-f203-g03-171", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What FiO₂ ceiling should be used to avoid O₂ toxicity on this exam?", "choices": ["< 50%", "< 90%", "< 21%", "< 100%"], "correct": 0, "explanation": "Conflict resolved: use < 50% (RCP 105 Initiation, and RCP 203's switch point).", "srcItem": "Oxygenation targets, FiO₂ limits, FiO₂ vs PEEP"},
    {"id": "q-f203-g03-172", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What PaO₂/SpO₂ goals apply in ARDS lung-protective ventilation?", "choices": ["PaO₂ 55–80, SpO₂ 88–95%", "PaO₂ 100–150, SpO₂ 100%", "PaO₂ 40–50", "SpO₂ 75–80%"], "correct": 0, "explanation": "ARDSNet goals: PaO₂ 55–80, SpO₂ 88–95%.", "srcItem": "Oxygenation targets, FiO₂ limits, FiO₂ vs PEEP"},
    {"id": "q-f203-g03-173", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A BiPAP patient on 10/5 needs better ventilation only. What is the NBRC change?", "choices": ["Raise IPAP only to 15/5", "Raise both to 12/7", "Raise EPAP only to 10/7", "Lower both"], "correct": 0, "explanation": "Ventilation only → ↑ IPAP, so ΔP rises and baseline stays.", "srcItem": "Adjusting BiPAP after the ABG"},
    {"id": "q-f203-g03-174", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A BiPAP patient on 10/5 needs better oxygenation and ventilation. What is the change?", "choices": ["Raise both, IPAP more — 15/7", "Raise EPAP only", "Lower IPAP", "Raise both equally to 12/7"], "correct": 0, "explanation": "Both → raise both, IPAP more than EPAP.", "srcItem": "Adjusting BiPAP after the ABG"},
    {"id": "q-f203-g03-175", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On BiPAP, which pressures adjust oxygenation?", "choices": ["FiO₂ and EPAP", "IPAP and ΔP", "Rate and rise", "Ramp and IPAP"], "correct": 0, "explanation": "Ventilation via IPAP/ΔP; oxygenation via FiO₂/EPAP.", "srcItem": "Adjusting BiPAP after the ABG"},
    {"id": "q-f203-g03-176", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PEEP 10 with FiO₂ 75% and PaO₂ 130. Which should be lowered first?", "choices": ["FiO₂ — oxygen toxicity is the concern", "PEEP — barotrauma is the concern", "Neither", "The rate"], "correct": 0, "explanation": "Lower whichever is more dangerous: high FiO₂ → oxygen toxicity.", "srcItem": "Which Knob for Hypoxemia"},
    {"id": "q-f203-g03-177", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PEEP 18 with FiO₂ 45% and PaO₂ 120. Which should be lowered first?", "choices": ["PEEP — barotrauma is the concern", "FiO₂", "The rate", "Nothing"], "correct": 0, "explanation": "High PEEP with modest FiO₂ → PEEP is the concern.", "srcItem": "Which Knob for Hypoxemia"},
    {"id": "q-f203-g03-178", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PaO₂ 52 on FiO₂ 0.70. What does the 60-60 rule say?", "choices": ["Shunt — add or increase PEEP", "V/Q mismatch — increase FiO₂", "Hypoventilation — increase rate", "Normal — no change"], "correct": 0, "explanation": "PaO₂ < 60 on FiO₂ > 0.6 = shunt → PEEP/CPAP.", "srcItem": "Which Knob for Hypoxemia"},
    {"id": "q-f203-g03-179", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PaO₂ 55 on FiO₂ 0.35. What is the likely mechanism and fix?", "choices": ["V/Q mismatch — increase FiO₂", "Shunt — add PEEP", "Diffusion block — give heliox", "Dead space — decrease rate"], "correct": 0, "explanation": "FiO₂ below 0.6 → V/Q imbalance responds to a simple FiO₂ increase.", "srcItem": "Which Knob for Hypoxemia"},
    {"id": "q-f203-g03-180", "topic": "f203-g03", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When VT is properly set (6–8 mL/kg PBW, Pplat < 30), what is preferred to change V̇E?", "choices": ["Respiratory rate", "VT", "PEEP", "FiO₂"], "correct": 0, "explanation": "RR changes are the preferred method once VT is set correctly.", "srcItem": "Which Knob for Hypoxemia"},
    {"id": "q-f203-g04-001", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What ETT size does RCP 203 give for an adult man?", "choices": ["8.0–9.0 mm ID", "6.0–7.0 mm ID", "9.5–10.5 mm ID", "5.0–6.0 mm ID"], "correct": 0, "explanation": "Deck: women 7.0–8.0, men 8.0–9.0 mm ID.", "srcItem": "Adult ETT Size"},
    {"id": "q-f203-g04-002", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How are adult ETTs sized?", "choices": ["By sex, not height or weight", "By height only", "By weight only", "By age"], "correct": 0, "explanation": "Adults are sized by sex; the LMA is sized by weight and the King LT by height.", "srcItem": "Adult ETT Size"},
    {"id": "q-f203-g04-003", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the typical oral ETT depth at the teeth for a man?", "choices": ["21–23 cm", "15–17 cm", "25–27 cm", "10–12 cm"], "correct": 0, "explanation": "Women 19–21, men 21–23 cm; confirm with CXR (tip 4–6 cm above carina).", "srcItem": "Adult ETT Size"},
    {"id": "q-f203-g04-004", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why is an ETT of 8 mm or larger preferred when possible?", "choices": ["An ETT raises WOB by 54–240% depending on size", "Larger tubes are cheaper", "Smaller tubes cause pneumonia", "Larger tubes don't need cuffs"], "correct": 0, "explanation": "Bigger tubes reduce resistance and work of breathing.", "srcItem": "Adult ETT Size"},
    {"id": "q-f203-g04-005", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What uncuffed ETT size does the formula give for a 4-year-old?", "choices": ["5.0 mm", "4.0 mm", "6.0 mm", "3.5 mm"], "correct": 0, "explanation": "(age ÷ 4) + 4 = 1 + 4 = 5.0 mm; cuffed 4.5 mm.", "srcItem": "Children"},
    {"id": "q-f203-g04-006", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What cuffed ETT size fits an 8-year-old?", "choices": ["5.5 mm", "6.0 mm", "4.5 mm", "7.0 mm"], "correct": 0, "explanation": "Cuffed = (age ÷ 4) + 3.5 = 2 + 3.5 = 5.5 mm.", "srcItem": "Children"},
    {"id": "q-f203-g04-007", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What insertion depth from the lips does Hess give for children?", "choices": ["Age + 10 cm", "Age × 2 cm", "Weight + 6 cm", "Always 21 cm"], "correct": 0, "explanation": "Depth = age + 10; a 4-year-old → 14 cm.", "srcItem": "Children"},
    {"id": "q-f203-g04-008", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the Broselow Tape used for?", "choices": ["Length-based emergency equipment sizing for children ≤ 35 kg", "Measuring adult cuff pressure", "Calibrating spirometers", "Measuring head circumference"], "correct": 0, "explanation": "A color-coded length-based tape recommends airways and equipment.", "srcItem": "Children"},
    {"id": "q-f203-g04-009", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What ETT size does Hess give for a neonate weighing less than 1000 g?", "choices": ["2.5 mm", "3.5 mm", "4.0 mm", "2.0 mm"], "correct": 0, "explanation": "< 1000 g → 2.5; 1000–2000 g → 3.0; 2000–3000 g → 3.5.", "srcItem": "Neonates: Size by Weight or Gestational Age"},
    {"id": "q-f203-g04-010", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How deep is a neonatal ETT placed from the lips?", "choices": ["Weight (kg) + 6 cm", "Age + 10 cm", "Always 10 cm", "Weight × 2 cm"], "correct": 0, "explanation": "1 kg → 7 cm; confirm by auscultation and chest x-ray.", "srcItem": "Neonates: Size by Weight or Gestational Age"},
    {"id": "q-f203-g04-011", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which ETT is used for premature infants or infants under 3 kg?", "choices": ["Uncuffed", "Cuffed only", "Double-lumen", "Fenestrated"], "correct": 0, "explanation": "RCP 203: uncuffed for premature or < 3 kg; cuffed now routine in older children.", "srcItem": "Neonates: Size by Weight or Gestational Age"},
    {"id": "q-f203-g04-012", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A neonate's weight is unknown but gestational age is 32 weeks. What ETT size fits?", "choices": ["3.0 mm", "2.5 mm", "3.5 mm", "4.5 mm"], "correct": 0, "explanation": "GA < 30 → 2.5; 30–35 → 3.0; > 35 → 3.5.", "srcItem": "Neonates: Size by Weight or Gestational Age"},
    {"id": "q-f203-g04-013", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the purpose of diagnostic bronchoscopy?", "choices": ["To find out what's wrong — gather information or confirm a diagnosis", "To remove foreign bodies", "To place a stent", "To dilate a stenosis"], "correct": 0, "explanation": "Diagnostic = Look; therapeutic = Treat.", "srcItem": "Diagnostic vs Therapeutic Bronchoscopy"},
    {"id": "q-f203-g04-014", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is a THERAPEUTIC indication for bronchoscopy (RCP 203)?", "choices": ["Clearing mucus plugs causing lobar atelectasis", "Evaluating a lesion of unknown etiology", "Finding the source of hemoptysis", "Obtaining cell washings"], "correct": 0, "explanation": "Therapeutic: difficult intubation, mucus plugs, foreign body/tissue removal, stents, balloon dilation.", "srcItem": "Diagnostic vs Therapeutic Bronchoscopy"},
    {"id": "q-f203-g04-015", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is a DIAGNOSTIC indication for bronchoscopy?", "choices": ["Unexplained localized wheeze or stridor", "Placing an airway stent", "Selective mainstem intubation", "Balloon dilatation of stenosis"], "correct": 0, "explanation": "Diagnostic: unexplained cough/wheeze/stridor, CXR lesions, hemoptysis source, sampling.", "srcItem": "Diagnostic vs Therapeutic Bronchoscopy"},
    {"id": "q-f203-g04-016", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which three sedation drugs does the RCP 202 deck say to focus on?", "choices": ["Midazolam, fentanyl and propofol", "Morphine, diazepam and codeine", "Ketamine, etomidate and vecuronium", "Atropine, lidocaine and epinephrine"], "correct": 0, "explanation": "Plus their reversal agents.", "srcItem": "Medications Used for the Procedure"},
    {"id": "q-f203-g04-017", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which reversal agent can precipitate seizures and is not given routinely to speed recovery?", "choices": ["Flumazenil", "Naloxone", "Atropine", "Neostigmine"], "correct": 0, "explanation": "Flumazenil reverses midazolam but can precipitate seizures.", "srcItem": "Medications Used for the Procedure"},
    {"id": "q-f203-g04-018", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is bleeding controlled through the bronchoscope?", "choices": ["Epinephrine, thrombin or iced saline via the working channel", "Lidocaine 4%", "Acetylcysteine", "Albuterol"], "correct": 0, "explanation": "RCP 105 gives topical 1:1000 epinephrine; thrombin helps blood clot.", "srcItem": "Medications Used for the Procedure"},
    {"id": "q-f203-g04-019", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why is lidocaine given before bronchoscopy?", "choices": ["It is a local anesthetic that suppresses cough", "It reverses sedation", "It dilates bronchi", "It stops bleeding"], "correct": 0, "explanation": "RCP 105: 5–10 mL of 1–4% via aerosol or through the channel.", "srcItem": "Medications Used for the Procedure"},
    {"id": "q-f203-g04-020", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How long should a patient be NPO before bronchoscopy per the Ch 16 deck?", "choices": ["At least 8 hours", "30 minutes", "24 hours", "No fasting is needed"], "correct": 0, "explanation": "NPO ≥ 8 h before; ≥ 2 h after or until the gag reflex returns.", "srcItem": "Assisting with Bronchoscopy"},
    {"id": "q-f203-g04-021", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "During bronchoscopy, SpO₂ falls below 90%. What should be done?", "choices": ["Increase the FiO₂ at once, or stop and give O₂ through the scope channel", "Continue without changes", "Remove all oxygen", "Give more sedation"], "correct": 0, "explanation": "PaO₂ usually falls; always give O₂ and react to SpO₂ < 90%.", "srcItem": "Assisting with Bronchoscopy"},
    {"id": "q-f203-g04-022", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is the scope passed in a ventilated patient?", "choices": ["Through the ETT via a Bodai or swivel-Y adaptor so FiO₂ and PEEP continue", "By disconnecting the ventilator", "Through the nose beside the ETT", "Through a chest tube"], "correct": 0, "explanation": "The adaptor lets ventilation continue during the procedure.", "srcItem": "Assisting with Bronchoscopy"},
    {"id": "q-f203-g04-023", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which special bronchoscopies reach peripheral lesions?", "choices": ["EBUS, electromagnetic navigation and robotic bronchoscopy", "Rigid bronchoscopy only", "Laryngoscopy", "Esophagoscopy"], "correct": 0, "explanation": "EBUS, ENB and Ion robotic bronchoscopy can be combined.", "srcItem": "Assisting with Bronchoscopy"},
    {"id": "q-f203-g04-024", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which labs rule out a bleeding disorder before a bronchoscopic biopsy?", "choices": ["INR, PT, PTT, CBC and platelet count", "Glucose and HbA1c", "BUN only", "Lipid panel"], "correct": 0, "explanation": "Ch 16: check INR, PT, PTT, CBC and platelets before biopsy.", "srcItem": "Assisting with Bronchoscopy"},
    {"id": "q-f203-g04-025", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the main purpose of a transtracheal oxygen catheter?", "choices": ["O₂ conservation by bypassing upper-airway dead space", "Ventilating apneic patients", "Suctioning secretions", "Measuring PETCO₂"], "correct": 0, "explanation": "It delivers equivalent oxygenation at a lower continuous flow.", "srcItem": "Transtracheal Catheter"},
    {"id": "q-f203-g04-026", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the key complication of a transtracheal O₂ catheter?", "choices": ["Mucus plugging", "Pneumothorax every time", "Hypercapnia", "Esophageal intubation"], "correct": 0, "explanation": "Humidification and catheter cleaning matter (RCP 202 Lssn 10).", "srcItem": "Transtracheal Catheter"},
    {"id": "q-f203-g04-027", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is a transtracheal catheter classed as an O₂ device?", "choices": ["A low-flow (variable FiO₂) conserving device", "A high-flow fixed-FiO₂ device", "A ventilator", "A reservoir mask"], "correct": 0, "explanation": "Hess lists it with O₂-conserving devices; it also improves adherence because it's hidden.", "srcItem": "Transtracheal Catheter"},
    {"id": "q-f203-g04-028", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which patient may receive an oropharyngeal airway?", "choices": ["An unconscious patient without a gag reflex", "A conscious patient with a strong gag", "A patient eating a meal", "A patient with a basilar skull fracture who is awake"], "correct": 0, "explanation": "An OPA in a patient with a gag reflex causes gagging, vomiting and aspiration.", "srcItem": "Oropharyngeal Airway (OPA)"},
    {"id": "q-f203-g04-029", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is an OPA sized per RCP 203?", "choices": ["From the corner of the mouth to the angle of the jaw", "From the nose to the earlobe", "By the patient's age only", "By weight"], "correct": 0, "explanation": "Size by anatomy; too large presses the epiglottis, too small pushes the tongue back.", "srcItem": "Oropharyngeal Airway (OPA)"},
    {"id": "q-f203-g04-030", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is an OPA inserted in an infant?", "choices": ["Depress the tongue with a tongue depressor and insert directly, without rotation", "Insert upside down and rotate 180°", "Insert through the nose", "Insert during a cough"], "correct": 0, "explanation": "Adults: rotate 180°; infants/small children: no rotation.", "srcItem": "Oropharyngeal Airway (OPA)"},
    {"id": "q-f203-g04-031", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which patient is better suited to a nasopharyngeal airway than an OPA?", "choices": ["A semi-conscious patient with an intact gag reflex", "An apneic patient", "A patient with midface trauma", "A patient with a basilar skull fracture"], "correct": 0, "explanation": "NPAs are better tolerated with a gag reflex.", "srcItem": "Nasopharyngeal Airway (NPA)"},
    {"id": "q-f203-g04-032", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is an NPA sized per RCP 203?", "choices": ["From the nares to the earlobe (or tragus)", "From the mouth to the jaw angle", "By the patient's height", "By the patient's age"], "correct": 0, "explanation": "Choose the largest diameter that passes without force.", "srcItem": "Nasopharyngeal Airway (NPA)"},
    {"id": "q-f203-g04-033", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the major contraindication to an NPA?", "choices": ["Suspected basilar skull fracture or significant midface trauma", "An intact gag reflex", "Frequent nasotracheal suctioning", "A conscious patient"], "correct": 0, "explanation": "Complications: laryngospasm, nosebleeds, sinus infection with prolonged use.", "srcItem": "Nasopharyngeal Airway (NPA)"},
    {"id": "q-f203-g04-034", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where does an LMA sit?", "choices": ["Above the glottis, sealing around the laryngeal inlet", "In the trachea below the cords", "In the esophagus", "In the nasopharynx"], "correct": 0, "explanation": "Supraglottic; it does not enter the trachea.", "srcItem": "Laryngeal Mask Airway (LMA)"},
    {"id": "q-f203-g04-035", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What LMA size fits a 60-kg adult per the deck?", "choices": ["Size 4", "Size 2", "Size 5", "Size 1"], "correct": 0, "explanation": "Size 4 = 50–70 kg; size 5 = 70–100 kg.", "srcItem": "Laryngeal Mask Airway (LMA)"},
    {"id": "q-f203-g04-036", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the maximum LMA cuff pressure?", "choices": ["≤ 60 cm H₂O", "20–30 cm H₂O", "≤ 10 cm H₂O", "100 cm H₂O"], "correct": 0, "explanation": "LMA cuff ≤ 60 (an ETT cuff is 20–30).", "srcItem": "Laryngeal Mask Airway (LMA)"},
    {"id": "q-f203-g04-037", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the main limitation of an LMA compared with a cuffed ETT?", "choices": ["Less protection from aspiration", "It cannot be used in anesthesia", "It requires seeing the cords", "It must be placed surgically"], "correct": 0, "explanation": "The LMA protects less against aspiration.", "srcItem": "Laryngeal Mask Airway (LMA)"},
    {"id": "q-f203-g04-038", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A patient with an LMA regurgitates. What should be done?", "choices": ["Leave it in, position head-down or side-lying, suction, prepare to intubate", "Remove the LMA immediately", "Inflate the cuff more", "Increase ventilation pressure"], "correct": 0, "explanation": "RCP 203: don't remove it; position, disconnect, suction, prepare to intubate.", "srcItem": "Laryngeal Mask Airway (LMA)"},
    {"id": "q-f203-g04-039", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is probably the most common reason for a tracheostomy?", "choices": ["Long-term mechanical ventilation", "Short-term surgery", "Mild asthma", "Pneumonia without ventilation"], "correct": 0, "explanation": "Three reasons: bypass upper obstruction, remove secretions, long-term ventilation.", "srcItem": "Tracheostomy and Tracheostomy Button"},
    {"id": "q-f203-g04-040", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What must be done before capping a fenestrated trach or placing a speaking valve?", "choices": ["Deflate the cuff fully", "Inflate the cuff fully", "Remove the inner cannula and leave the cuff up", "Increase the FiO₂"], "correct": 0, "explanation": "Never cap or place a speaking valve with the cuff inflated.", "srcItem": "Tracheostomy and Tracheostomy Button"},
    {"id": "q-f203-g04-041", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What should be kept at the bedside after tracheostomy insertion?", "choices": ["The obturator and a spare inner cannula", "Nothing", "Only a suction catheter", "An LMA"], "correct": 0, "explanation": "Remove the obturator immediately after insertion and keep it at the bedside.", "srcItem": "Tracheostomy and Tracheostomy Button"},
    {"id": "q-f203-g04-042", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is a tracheostomy button?", "choices": ["A short cannula that keeps the stoma open without a full tube", "A cuffed trach tube for ventilation", "A speaking valve", "A suction port"], "correct": 0, "explanation": "It has no cuff, so PPV leaks; it is not a secure airway.", "srcItem": "Tracheostomy and Tracheostomy Button"},
    {"id": "q-f203-g04-043", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A Combitube is placed blindly. Which lumen is ventilated first?", "choices": ["The blue pharyngeal lumen", "The clear tracheal lumen", "Both together", "Neither"], "correct": 0, "explanation": "\"BLUE FIRST\": it usually lands in the esophagus; switch to clear if in the trachea.", "srcItem": "Rescue Airways"},
    {"id": "q-f203-g04-044", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where does the King LT tip normally sit?", "choices": ["In the esophagus", "In the trachea", "Above the epiglottis", "In the nasopharynx"], "correct": 0, "explanation": "The distal cuff blocks the esophagus; gas exits between the cuffs toward the larynx.", "srcItem": "Rescue Airways"},
    {"id": "q-f203-g04-045", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the definitive tracheal airway in the deck's ladder?", "choices": ["The ETT", "The OPA", "The LMA", "The King LT"], "correct": 0, "explanation": "OPA/NPA basic; King/Combitube/LMA supraglottic rescue; ETT definitive.", "srcItem": "Rescue Airways"},
    {"id": "q-f203-g04-046", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A ventilated patient's ETT becomes obstructed. What is the first step?", "choices": ["Remove the patient from the ventilator and manually ventilate with 100% O₂", "Increase the ventilator pressure limit", "Wait for the obstruction to clear", "Remove the tube immediately without ventilating"], "correct": 0, "explanation": "Then reassess; try an airway exchange catheter through the blocked tube if available.", "srcItem": "Lost or Obstructed Airway"},
    {"id": "q-f203-g04-047", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A fresh tracheostomy tube comes out. What should be done?", "choices": ["Call for help, cover the stoma with petroleum gauze, BVM-ventilate with O₂", "Reinsert any tube immediately", "Leave the stoma open and observe", "Insert an NPA into the stoma"], "correct": 0, "explanation": "A fresh stoma can close or misdirect a tube.", "srcItem": "Lost or Obstructed Airway"},
    {"id": "q-f203-g04-048", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "After a failed intubation attempt, SpO₂ falls below 90% and BVM fails. What next?", "choices": ["Insert a supraglottic airway immediately", "Try 5 more intubation attempts", "Stop all ventilation", "Give more sedation"], "correct": 0, "explanation": "CICO: supraglottic airway; if that fails, emergency surgical airway.", "srcItem": "Lost or Obstructed Airway"},
    {"id": "q-f203-g04-049", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the only absolute contraindication to intubation?", "choices": ["A documented DNR/DNI order", "Mallampati class 4", "A full stomach", "Facial hair"], "correct": 0, "explanation": "Ch 16: relative contraindications include airway trauma, C-spine injury, Mallampati 4.", "srcItem": "Assisting with Intubation and Tracheotomy"},
    {"id": "q-f203-g04-050", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does Mallampati class IV show?", "choices": ["Only the hard palate — most difficult", "Soft palate, uvula and pillars — easiest", "Soft palate and uvula", "Base of the uvula"], "correct": 0, "explanation": "Class I easiest → class IV most difficult.", "srcItem": "Assisting with Intubation and Tracheotomy"},
    {"id": "q-f203-g04-051", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How long should each intubation attempt last?", "choices": ["No longer than 30 seconds", "2 minutes", "5 minutes", "Until the tube is placed"], "correct": 0, "explanation": "Call out the time; resume bagging with 100% O₂ between attempts.", "srcItem": "Assisting with Intubation and Tracheotomy"},
    {"id": "q-f203-g04-052", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A colorimetric CO₂ detector turns yellow with each exhalation. What does this mean?", "choices": ["CO₂ is detected — consistent with tracheal placement", "The tube is in the esophagus", "The detector is broken", "The patient is hypoxemic"], "correct": 0, "explanation": "Purple (< 0.5%) → yellow (≥ 2%); in cardiac arrest it may stay purple despite correct placement.", "srcItem": "Assisting with Intubation and Tracheotomy"},
    {"id": "q-f203-g04-053", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Can CO₂ detection identify a mainstem intubation?", "choices": ["No — record the depth and confirm with a chest x-ray", "Yes, always", "Only with waveform capnography", "Only in children"], "correct": 0, "explanation": "CO₂ confirms tracheal, not mainstem, placement.", "srcItem": "Assisting with Intubation and Tracheotomy"},
    {"id": "q-f203-g04-054", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which position is used for intubation without suspected C-spine injury?", "choices": ["Sniffing position", "Trendelenburg", "Prone", "Neck fully flexed"], "correct": 0, "explanation": "Neck slightly flexed, head extended; with suspected C-spine injury use MILS.", "srcItem": "Assisting with Intubation and Tracheotomy"},
    {"id": "q-f203-g04-055", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How long is each postural drainage position held?", "choices": ["5–10 minutes", "30 seconds", "1 hour", "24 hours"], "correct": 0, "explanation": "Deck and Hess: 5–10 min per position; sessions 20–40 min.", "srcItem": "Manual Percussion, Vibration and Postural Drainage"},
    {"id": "q-f203-g04-056", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In postural drainage, how is the affected segment positioned?", "choices": ["Up, so gravity moves mucus to the larger airways", "Down against the bed", "Level with the heart", "It doesn't matter"], "correct": 0, "explanation": "Gravity drains the elevated segment toward the larger airways.", "srcItem": "Manual Percussion, Vibration and Postural Drainage"},
    {"id": "q-f203-g04-057", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When should postural drainage be stopped?", "choices": ["When sputum drops below 30 mL/day with an effective cough", "After one session", "When sputum exceeds 30 mL/day", "Never"], "correct": 0, "explanation": "Sputum > 30 mL/day indicates airway clearance; stop when below with effective cough.", "srcItem": "Manual Percussion, Vibration and Postural Drainage"},
    {"id": "q-f203-g04-058", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When should CPT sessions be timed?", "choices": ["Before meals or 2 hours after", "Right after meals", "During meals", "Only at night"], "correct": 0, "explanation": "Deck: before meals or 2 h after (Hess says > 1 h).", "srcItem": "Manual Percussion, Vibration and Postural Drainage"},
    {"id": "q-f203-g04-059", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is a contraindication to postural drainage and percussion?", "choices": ["Unstable head injury", "Productive cough", "Atelectasis", "Bronchiectasis"], "correct": 0, "explanation": "Also recent spinal surgery, uncontrolled hypertension; no head-down with gross hemoptysis.", "srcItem": "Manual Percussion, Vibration and Postural Drainage"},
    {"id": "q-f203-g04-060", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does the deck compare mechanical percussors with cupped hands?", "choices": ["Equally effective, with consistent force and no user fatigue", "Less effective", "More dangerous", "They don't loosen secretions"], "correct": 0, "explanation": "Deck: equally effective; Hess says data are lacking.", "srcItem": "Mechanical Percussion"},
    {"id": "q-f203-g04-061", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is HFCWO (the vest)?", "choices": ["An inflatable vest giving rapid positive-pressure bursts at about 5–20 Hz", "A device that inhales aerosol only", "A CPAP mask", "A manual percussion technique"], "correct": 0, "explanation": "Used mainly for CF and bronchiectasis, especially at home without caregiver help.", "srcItem": "Mechanical Percussion"},
    {"id": "q-f203-g04-062", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which therapy does the deck say replaced IPPB?", "choices": ["Intrapulmonary percussive ventilation (IPV)", "Incentive spirometry", "Postural drainage", "Heliox"], "correct": 0, "explanation": "IPV gives high-flow mini-bursts with aerosol at 300–400 pulses/min.", "srcItem": "Mechanical Percussion"},
    {"id": "q-f203-g04-063", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the Metaneb combine?", "choices": ["Continuous PEP for lung expansion and high-frequency oscillation for secretions", "Heliox and nitric oxide", "Suction and lavage", "Oxygen and humidity only"], "correct": 0, "explanation": "CPEP + CHFO with aerosol; can run in-line with a ventilator.", "srcItem": "Mechanical Percussion"},
    {"id": "q-f203-g04-064", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What pressure range do PEP devices typically create during exhalation?", "choices": ["6–25 cm H₂O", "40–60 cm H₂O", "1–2 cm H₂O", "−20 cm H₂O"], "correct": 0, "explanation": "PEP: 6–25 cm H₂O on exhalation with unrestricted inspiration.", "srcItem": "PEP and Vibratory (Oscillatory) PEP"},
    {"id": "q-f203-g04-065", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "To mobilize secretions, which PEP device is probably the best choice?", "choices": ["A vibratory (oscillatory) PEP device", "A simple PEP mask", "An incentive spirometer", "An IPPB machine"], "correct": 0, "explanation": "Vibratory PEP (Flutter, Acapella) helps mobilize secretions.", "srcItem": "PEP and Vibratory (Oscillatory) PEP"},
    {"id": "q-f203-g04-066", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does the Acapella differ from the Flutter?", "choices": ["The Acapella works independently of gravity", "The Acapella needs a specific angle", "The Flutter uses a magnet", "The Flutter is electrically powered"], "correct": 0, "explanation": "Flutter: steel ball, gravity-dependent; Acapella: lever and magnet, any position.", "srcItem": "PEP and Vibratory (Oscillatory) PEP"},
    {"id": "q-f203-g04-067", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is a contraindication to PEP therapy?", "choices": ["Untreated pneumothorax", "Cystic fibrosis", "Atelectasis", "Chronic bronchitis"], "correct": 0, "explanation": "Also high ICP, hemodynamic instability, bullous emphysema, sinusitis, middle-ear problems.", "srcItem": "PEP and Vibratory (Oscillatory) PEP"},
    {"id": "q-f203-g04-068", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How many sets are done in a PEP session per the deck?", "choices": ["Sets of 10–20 breaths repeated 4–8 times, ≤ 20 minutes", "One set of 5 breaths", "100 breaths without a cough", "Continuous for an hour"], "correct": 0, "explanation": "Directed cough after each set.", "srcItem": "PEP and Vibratory (Oscillatory) PEP"},
    {"id": "q-f203-g04-069", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is IPPB's status on NBRC exams per the deck?", "choices": ["Removed — no longer recommended and replaced by IPV", "The first-line lung-expansion therapy", "Required for all postop patients", "Used for aerosol delivery"], "correct": 0, "explanation": "Use the deck: IPPB is off the exam and replaced by IPV.", "srcItem": "IPPB"},
    {"id": "q-f203-g04-070", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is an IPPB machine classified (Hess)?", "choices": ["Pneumatically driven, pressure-triggered and pressure-cycled", "Electrically driven and time-cycled", "Volume-cycled", "Flow-triggered and time-cycled"], "correct": 0, "explanation": "Patient-triggered, passively inflating the lungs.", "srcItem": "IPPB"},
    {"id": "q-f203-g04-071", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Should IPPB be used for aerosol therapy (Hess)?", "choices": ["No", "Yes, always", "Only for antibiotics", "Only in children"], "correct": 0, "explanation": "Hess: IPPB should not be used for aerosol therapy.", "srcItem": "IPPB"},
    {"id": "q-f203-g04-072", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does IPV deliver?", "choices": ["Rapid short bursts of pressurized air combined with aerosol", "Continuous high PEEP", "A single large breath", "Heliox only"], "correct": 0, "explanation": "IPV mobilizes mucus, opens airways and improves lung expansion.", "srcItem": "What IPV Is and How It Works"},
    {"id": "q-f203-g04-073", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What rate should be used on the exam for IPV?", "choices": ["More than 200 cycles/min", "10–20 breaths/min", "1,000 breaths/min", "Under 60 per minute"], "correct": 0, "explanation": "Deck and glossary: > 200 cycles/min (Hess text 300–400).", "srcItem": "What IPV Is and How It Works"},
    {"id": "q-f203-g04-074", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is IPV's key advantage over IPPB?", "choices": ["It combines airway clearance and lung expansion in one therapy", "It is cheaper", "It needs no gas", "It is only for children"], "correct": 0, "explanation": "The deck says IPPB has been replaced by IPV.", "srcItem": "What IPV Is and How It Works"},
    {"id": "q-f203-g04-075", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is exhalation achieved during IPV (Hess)?", "choices": ["Passively by chest-wall recoil", "By active suction", "By the oscillator pulling gas out", "It does not occur"], "correct": 0, "explanation": "The patient keeps breathing spontaneously during the oscillations.", "srcItem": "What IPV Is and How It Works"},
    {"id": "q-f203-g04-076", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How long is a typical MetaNeb session?", "choices": ["About 10 minutes alternating modes", "2 hours", "1 minute", "24 hours continuous"], "correct": 0, "explanation": "MetaNeb: CPEP (expansion) and CHFO (clearance) with aerosol.", "srcItem": "Devices and Settings"},
    {"id": "q-f203-g04-077", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which percussive device cannot be used with a ventilator?", "choices": ["PercussiveNeb", "MetaNeb", "Breas IMP2", "Percussionator"], "correct": 0, "explanation": "PercussiveNeb: 11–30 Hz, single-patient use, not with a ventilator.", "srcItem": "Devices and Settings"},
    {"id": "q-f203-g04-078", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What are the two MetaNeb modes per RCP 203?", "choices": ["CPEP for lung expansion and CHFO for secretion clearance", "PEEP and PS", "IPAP and EPAP", "Inspiration and expiration"], "correct": 0, "explanation": "It can run in-line with a ventilator.", "srcItem": "Devices and Settings"},
    {"id": "q-f203-g04-079", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is a contraindication to IPV?", "choices": ["Untreated pneumothorax", "Cystic fibrosis", "Atelectasis", "Thick secretions"], "correct": 0, "explanation": "Also active hemoptysis, recent facial/oral surgery, unstable CV status, elevated ICP.", "srcItem": "Using IPV in CF"},
    {"id": "q-f203-g04-080", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the CF Foundation recommend about airway clearance?", "choices": ["Regular ACT for all CF patients, individualized — no therapy shown superior", "IPV only", "No airway clearance", "Postural drainage head-down only"], "correct": 0, "explanation": "Individualize by age, preference and adverse events.", "srcItem": "Using IPV in CF"},
    {"id": "q-f203-g04-081", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why are CF patients generally no longer placed head-down for postural drainage?", "choices": ["Reflux risk", "It is too slow", "It raises the FiO₂", "It causes bronchospasm"], "correct": 0, "explanation": "RCP 203 Lssn 6b.", "srcItem": "Using IPV in CF"},
    {"id": "q-f203-g04-082", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How much of the ETT internal diameter may an adult suction catheter occlude?", "choices": ["< 50%", "< 90%", "< 25%", "100%"], "correct": 0, "explanation": "< 50% for adults, < 70% for infants, so gas can flow around it.", "srcItem": "How to Pick the Catheter Size"},
    {"id": "q-f203-g04-083", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What suction catheter fits a 6.0-mm ETT per the deck?", "choices": ["10 Fr", "12 Fr", "14 Fr", "6 Fr"], "correct": 0, "explanation": "2 × 6 = 12, then the next smallest size = 10 Fr.", "srcItem": "How to Pick the Catheter Size"},
    {"id": "q-f203-g04-084", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What suction catheter fits an 8.0-mm ETT using the deck's rule?", "choices": ["14 Fr", "16 Fr", "8 Fr", "18 Fr"], "correct": 0, "explanation": "2 × 8 = 16 → next smallest = 14 Fr.", "srcItem": "How to Pick the Catheter Size"},
    {"id": "q-f203-g04-085", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does a French size measure?", "choices": ["The outer circumference (Fr ≈ diameter in mm × 3)", "The inner diameter in mm", "The length in cm", "The suction pressure"], "correct": 0, "explanation": "Hess: Fr ≈ diameter (mm) × 3.", "srcItem": "How to Pick the Catheter Size"},
    {"id": "q-f203-g04-086", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What suction pressure range does the deck give for adults?", "choices": ["−100 to −120 mm Hg", "−60 to −80 mm Hg", "−200 to −250 mm Hg", "−20 to −40 mm Hg"], "correct": 0, "explanation": "Children −80 to −100; infants −60 to −80.", "srcItem": "Suction Pressures and Time Limits"},
    {"id": "q-f203-g04-087", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What suction pressure range is used for infants?", "choices": ["−60 to −80 mm Hg", "−100 to −120 mm Hg", "−150 mm Hg", "−20 mm Hg"], "correct": 0, "explanation": "Use the deck's Ch 10 ranges.", "srcItem": "Suction Pressures and Time Limits"},
    {"id": "q-f203-g04-088", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How long may each suction attempt last?", "choices": ["No more than 15 seconds", "30 seconds", "1 minute", "Until secretions clear"], "correct": 0, "explanation": "Use 15 s (RCP 105 says 10 s).", "srcItem": "Suction Pressures and Time Limits"},
    {"id": "q-f203-g04-089", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How should a patient be oxygenated before suctioning (Ch 11)?", "choices": ["100% O₂ for 30–60 seconds", "Room air", "Remove O₂ for 1 minute", "No preparation"], "correct": 0, "explanation": "Hess: FiO₂ 1.0; neonates +0.1 for 30–60 s.", "srcItem": "Suction Pressures and Time Limits"},
    {"id": "q-f203-g04-090", "topic": "f203-g04", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What continuous suction pressure does a CASS (subglottic) port use?", "choices": ["−20 to −25 mm Hg", "−120 mm Hg", "−200 mm Hg", "−5 mm Hg"], "correct": 0, "explanation": "Continuous low suction removes pooled secretions above the cuff.", "srcItem": "Suction Pressures and Time Limits"},
    {"id": "q-f203-g05-001", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which three premixed heliox mixtures does the deck list?", "choices": ["80/20, 70/30 and 60/40 He/O₂", "50/50, 40/60 and 30/70", "90/10, 95/5 and 99/1", "100% helium only"], "correct": 0, "explanation": "Always at least 20% O₂; premixed cylinders prevent delivering 100% He.", "srcItem": "Heliox Concentrations"},
    {"id": "q-f203-g05-002", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does heliox reduce the work of breathing?", "choices": ["Helium is much less dense than nitrogen, so it flows more easily through narrowed airways", "It increases the FiO₂", "It dilates the bronchi", "It dissolves mucus"], "correct": 0, "explanation": "Useful in large-airway obstruction and severe asthma.", "srcItem": "Heliox Concentrations"},
    {"id": "q-f203-g05-003", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why is 100% helium dangerous?", "choices": ["If the O₂ source fails the patient breathes 100% He and becomes anoxic", "It is flammable", "It is toxic to the liver", "It causes bronchospasm"], "correct": 0, "explanation": "That is why premixed cylinders with ≥ 20% O₂ are used.", "srcItem": "Heliox Concentrations"},
    {"id": "q-f203-g05-004", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Is heliox a treatment for hypoxemia?", "choices": ["No — it is not a replacement for O₂ therapy", "Yes — it raises PaO₂ more than O₂", "Yes — at 80/20", "Only in neonates"], "correct": 0, "explanation": "Heliox reduces WOB but does not replace O₂ in hypoxemic patients.", "srcItem": "Heliox Concentrations"},
    {"id": "q-f203-g05-005", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is heliox delivered to a spontaneously breathing patient?", "choices": ["A tight-fitting nonrebreathing mask at a flow meeting inspiratory demand", "A simple nasal cannula at 2 L/min", "An open face tent", "A venturi mask"], "correct": 0, "explanation": "Or a high-flow cannula; monitor FiO₂ with an analyzer with alarms.", "srcItem": "Methods of Delivering Heliox"},
    {"id": "q-f203-g05-006", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why must heliox be given in a tightly sealed system?", "choices": ["Helium leaks through small holes", "Helium is heavier than air", "Helium freezes the circuit", "Helium reacts with oxygen"], "correct": 0, "explanation": "Hess: a tightly sealed, closed system is required.", "srcItem": "Methods of Delivering Heliox"},
    {"id": "q-f203-g05-007", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What correction factor is used for 80/20 heliox on an O₂ flowmeter?", "choices": ["1.8", "1.4", "1.6", "2.5"], "correct": 0, "explanation": "80/20 → 1.8; 70/30 → 1.6; 60/40 → 1.4.", "srcItem": "Flowmeter Correction Factor (worked example)"},
    {"id": "q-f203-g05-008", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "An O₂ flowmeter reads 10 L/min with 80/20 heliox. What is the actual flow?", "choices": ["18 L/min", "10 L/min", "5.6 L/min", "28 L/min"], "correct": 0, "explanation": "10 × 1.8 = 18 L/min.", "srcItem": "Flowmeter Correction Factor (worked example)"},
    {"id": "q-f203-g05-009", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "You need 15 L/min of 80/20 heliox. What should the O₂ flowmeter be set to?", "choices": ["About 8.3 L/min", "27 L/min", "15 L/min", "1.8 L/min"], "correct": 0, "explanation": "Reverse it: 15 ÷ 1.8 ≈ 8.3 L/min.", "srcItem": "Flowmeter Correction Factor (worked example)"},
    {"id": "q-f203-g05-010", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does the flowmeter correction change as the helium percentage rises?", "choices": ["The factor gets larger", "The factor gets smaller", "It stays at 1.0", "It becomes negative"], "correct": 0, "explanation": "More helium → larger factor and lower FiO₂.", "srcItem": "Flowmeter Correction Factor (worked example)"},
    {"id": "q-f203-g05-011", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why has heliox by oxyhood fallen out of favor for infants?", "choices": ["Helium's high thermal conductivity causes heat loss and hypothermia", "It cannot be humidified", "It makes infants cry", "It is too expensive"], "correct": 0, "explanation": "Preference is now for high-flow nasal cannula.", "srcItem": "Heliox in Infants, and Heliox Driving a Nebulizer"},
    {"id": "q-f203-g05-012", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When heliox drives a nebulizer, how should the flow change?", "choices": ["Increase it by 50–100%", "Decrease it by half", "Keep it the same", "Stop the nebulizer"], "correct": 0, "explanation": "Low density reduces nebulizer efficiency; raising flow restores inhaled dose.", "srcItem": "Heliox in Infants, and Heliox Driving a Nebulizer"},
    {"id": "q-f203-g05-013", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does the nebulizer flow increase differ from the flowmeter correction factor?", "choices": ["One changes a setting to make the nebulizer work; the other corrects a reading", "They are identical", "Both lower the flow", "Neither applies to heliox"], "correct": 0, "explanation": "Flowmeter factor corrects a reading; the 50–100% increase is a deliberate setting change.", "srcItem": "Heliox in Infants, and Heliox Driving a Nebulizer"},
    {"id": "q-f203-g05-014", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does a low-flow O₂ device differ from a high-flow device?", "choices": ["Low-flow gives a variable FiO₂; high-flow gives a fixed FiO₂", "Low-flow always gives a lower FiO₂", "High-flow gives a variable FiO₂", "They are identical"], "correct": 0, "explanation": "High-flow meets or exceeds the patient's inspiratory flow.", "srcItem": "The Four Masks Side by Side"},
    {"id": "q-f203-g05-015", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What FiO₂ does a partial rebreathing mask deliver (Hess)?", "choices": ["0.40–0.70", "0.24–0.40", "0.90–1.0", "0.21 only"], "correct": 0, "explanation": "Partial rebreather: 0.40–0.70 at 8–15 L/min.", "srcItem": "The Four Masks Side by Side"},
    {"id": "q-f203-g05-016", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What FiO₂ does a nonrebreathing mask deliver in practice?", "choices": ["0.6–0.8", "1.0 guaranteed", "0.3–0.4", "0.21"], "correct": 0, "explanation": "The mask doesn't seal, so 60–80% in reality.", "srcItem": "The Four Masks Side by Side"},
    {"id": "q-f203-g05-017", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "During use of a nonrebreathing mask, how should the reservoir bag look?", "choices": ["It should not empty by more than half", "It should collapse fully each breath", "It should be removed", "It should be overinflated to bursting"], "correct": 0, "explanation": "Set flow (10–15 L/min) high enough that the bag never collapses.", "srcItem": "The Four Masks Side by Side"},
    {"id": "q-f203-g05-018", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On an aerosol mask, the mist disappears during inspiration. What does this mean?", "choices": ["Room air is diluting the gas — the flow is inadequate", "The FiO₂ is too high", "The patient is not breathing", "The nebulizer is overfilled"], "correct": 0, "explanation": "The 'high-flow' system has become low-flow with a variable FiO₂.", "srcItem": "The Four Masks Side by Side"},
    {"id": "q-f203-g05-019", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the key difference between a partial rebreather and a nonrebreather?", "choices": ["The nonrebreather has one-way valves", "The partial rebreather has valves", "The nonrebreather has no reservoir", "They are identical"], "correct": 0, "explanation": "Removing the valves turns an NRB into a partial rebreather.", "srcItem": "Partial Rebreathing vs Nonrebreathing Mask"},
    {"id": "q-f203-g05-020", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What safety feature may a nonrebreathing mask have?", "choices": ["A spring-loaded antisuffocation valve", "A pressure relief valve set at 60", "An oxygen analyzer", "A heated wire"], "correct": 0, "explanation": "If valves stick or O₂ fails, the patient could suffocate.", "srcItem": "Partial Rebreathing vs Nonrebreathing Mask"},
    {"id": "q-f203-g05-021", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which patient is a good candidate for a nonrebreathing mask?", "choices": ["A patient needing a high FiO₂ with a fairly normal breathing pattern, e.g. CO exposure", "A COPD patient needing 24% O₂", "An apneic patient", "A patient needing a precise FiO₂ of 0.28"], "correct": 0, "explanation": "Hess: trauma, MI, CO exposure; also preoxygenation before intubation.", "srcItem": "Partial Rebreathing vs Nonrebreathing Mask"},
    {"id": "q-f203-g05-022", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On an air-entrainment mask, a larger entrainment port does what?", "choices": ["Entrains more air, lowering FiO₂ and raising total flow", "Raises the FiO₂", "Lowers the total flow", "Has no effect"], "correct": 0, "explanation": "Bigger ports/smaller jets → lower FiO₂, higher flow.", "srcItem": "Air-Entrainment Mask and Aerosol Mask"},
    {"id": "q-f203-g05-023", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What happens if the entrainment ports of a Venturi mask are blocked by sheets?", "choices": ["The FiO₂ rises and total flow falls", "The FiO₂ falls", "Total flow rises", "Nothing changes"], "correct": 0, "explanation": "Blocked ports entrain less air.", "srcItem": "Air-Entrainment Mask and Aerosol Mask"},
    {"id": "q-f203-g05-024", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Does increasing the O₂ flowmeter on a Venturi mask change the FiO₂?", "choices": ["No — only the total flow changes", "Yes — FiO₂ rises", "Yes — FiO₂ falls", "It turns the mask off"], "correct": 0, "explanation": "The jet/port setting sets FiO₂; O₂ L/min sets total flow.", "srcItem": "Air-Entrainment Mask and Aerosol Mask"},
    {"id": "q-f203-g05-025", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A 40% Venturi mask (3:1) is run at 10 L/min. What is the total flow?", "choices": ["40 L/min", "30 L/min", "10 L/min", "13 L/min"], "correct": 0, "explanation": "(3 + 1) × 10 = 40 L/min.", "srcItem": "Air-Entrainment Mask and Aerosol Mask"},
    {"id": "q-f203-g05-026", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A 60% air-entrainment device (1:1) runs at 10 L/min. What is the total flow?", "choices": ["20 L/min", "60 L/min", "10 L/min", "40 L/min"], "correct": 0, "explanation": "(1 + 1) × 10 = 20 L/min — often too low; aim for ≥ 40 L/min.", "srcItem": "Air-Entrainment Mask and Aerosol Mask"},
    {"id": "q-f203-g05-027", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is a shunt?", "choices": ["Perfusion without ventilation", "Ventilation without perfusion", "Matched ventilation and perfusion", "High ventilation with low perfusion"], "correct": 0, "explanation": "Shunt V/Q = 0; dead space = ventilation without perfusion (V/Q infinite).", "srcItem": "V/Q Mismatch vs Shunt"},
    {"id": "q-f203-g05-028", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the most common cause of hypoxemia?", "choices": ["V/Q mismatch", "Shunt", "Diffusion defect", "Hypoventilation"], "correct": 0, "explanation": "V/Q mismatch is the most common cause — a huge NBRC favorite.", "srcItem": "V/Q Mismatch vs Shunt"},
    {"id": "q-f203-g05-029", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which hypoxemia mechanism is least responsive to oxygen?", "choices": ["Intrapulmonary shunt", "Low V/Q mismatch", "Hypoventilation", "High altitude"], "correct": 0, "explanation": "Shunt responds poorly → refractory hypoxemia; fix with recruitment (PEEP/CPAP).", "srcItem": "V/Q Mismatch vs Shunt"},
    {"id": "q-f203-g05-030", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Is a pulmonary embolism a shunt or dead space?", "choices": ["Dead space (high V/Q)", "Shunt", "Neither", "Low V/Q"], "correct": 0, "explanation": "Trap: PE is high V/Q (dead space), not shunt.", "srcItem": "V/Q Mismatch vs Shunt"},
    {"id": "q-f203-g05-031", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does the deck summarize dead space vs shunt?", "choices": ["Dead space is wasted air; shunt is wasted blood", "Both are wasted air", "Both are wasted blood", "Shunt is wasted air"], "correct": 0, "explanation": "Deck: \"Dead space is wasted air. Shunt is wasted blood.\"", "srcItem": "V/Q Mismatch vs Shunt"},
    {"id": "q-f203-g05-032", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On 100% O₂, a patient's PaO₂ reaches only 250 mm Hg. What does this suggest?", "choices": ["A shunt of about 25% of cardiac output", "Normal lungs", "Pure V/Q mismatch", "Hyperventilation"], "correct": 0, "explanation": "Normal adults reach > 600 mm Hg on 100% O₂.", "srcItem": "Telling Them Apart"},
    {"id": "q-f203-g05-033", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal shunt fraction per RCP 203?", "choices": ["< 5%", "< 50%", "20–30%", "> 30%"], "correct": 0, "explanation": "Use < 5% (RCP 203); > 20–30% is significant in the critically ill.", "srcItem": "Telling Them Apart"},
    {"id": "q-f203-g05-034", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What shunt fraction must be present for weaning?", "choices": ["< 20%", "< 50%", "> 30%", "Any value"], "correct": 0, "explanation": "For weaning, Qs/Qt must be < 20%.", "srcItem": "Telling Them Apart"},
    {"id": "q-f203-g05-035", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In the deck's shunt example, Qs/Qt = 3.8 ÷ 6.9. What is the shunt?", "choices": ["About 55% — severe", "About 5% — normal", "About 18% — mild", "About 90%"], "correct": 0, "explanation": "0.55 = 55%, consistent with ARDS or large atelectasis.", "srcItem": "Telling Them Apart"},
    {"id": "q-f203-g05-036", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When does RCP 203 say a significant shunt generally exists?", "choices": ["P/F < 200 or PaO₂ ≤ 50 on FiO₂ ≥ 50%", "P/F > 400", "PaO₂ 100 on room air", "SpO₂ 98% on 2 L"], "correct": 0, "explanation": "O₂ alone is insufficient; treat with CPAP or PEEP.", "srcItem": "RCP 203 Bedside Rules"},
    {"id": "q-f203-g05-037", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "An A-a gradient of 150 mm Hg suggests what, and what is the fix?", "choices": ["V/Q mismatch — O₂ up to 60%", "Shunt — PEEP", "Normal — no change", "Hypoventilation — increase rate"], "correct": 0, "explanation": "66–300 = V/Q mismatch; > 300 = shunt → ventilator with PEEP.", "srcItem": "RCP 203 Bedside Rules"},
    {"id": "q-f203-g05-038", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is a normal A-a gradient on room air?", "choices": ["5–15 mm Hg", "66–300 mm Hg", "> 300 mm Hg", "100 mm Hg"], "correct": 0, "explanation": "Normal 5–15 mm Hg on room air.", "srcItem": "RCP 203 Bedside Rules"},
    {"id": "q-f203-g05-039", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does prone positioning help refractory hypoxemia?", "choices": ["It re-expands the dorsal lung, decreasing shunt and improving V/Q", "It increases dead space", "It lowers the FiO₂ needed to zero", "It removes secretions only"], "correct": 0, "explanation": "RCP 203: proning decreases shunt.", "srcItem": "RCP 203 Bedside Rules"},
    {"id": "q-f203-g05-040", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A patient has pneumonia in the left lung. Which position improves oxygenation?", "choices": ["Right lateral decubitus (good lung down)", "Left lateral decubitus", "Prone with the left side down", "Trendelenburg"], "correct": 0, "explanation": "Good lung down matches perfusion with the best-ventilated lung.", "srcItem": "Good Lung Down"},
    {"id": "q-f203-g05-041", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "For which condition should the good lung be UP?", "choices": ["Lung abscess", "Unilateral pneumonia", "Unilateral atelectasis", "Unilateral pleural effusion"], "correct": 0, "explanation": "Good lung up for abscess, unilateral PIE in infants, and massive hemoptysis.", "srcItem": "Good Lung Down"},
    {"id": "q-f203-g05-042", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why is the good lung placed UP with massive hemoptysis?", "choices": ["To keep blood from flowing into the good lung", "To improve V/Q matching", "To raise the FiO₂", "To lower the PEEP"], "correct": 0, "explanation": "The goal shifts to protecting the one good lung.", "srcItem": "Good Lung Down"},
    {"id": "q-f203-g05-043", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In the lateral position, which lung receives more blood flow?", "choices": ["The dependent (lower) lung", "The upper lung", "Both equally", "Neither"], "correct": 0, "explanation": "Gravity pulls perfusion to the dependent lung.", "srcItem": "Good Lung Down"},
    {"id": "q-f203-g05-044", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does inhaled nitric oxide improve oxygenation?", "choices": ["It dilates pulmonary vessels in ventilated areas, improving V/Q matching", "It raises the FiO₂", "It dilates systemic arteries", "It thins secretions"], "correct": 0, "explanation": "NO ↑ cGMP → smooth muscle relaxation, only in the pulmonary bed.", "srcItem": "What NO Is and What It Is Used For"},
    {"id": "q-f203-g05-045", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why doesn't inhaled NO cause systemic hypotension?", "choices": ["Hemoglobin inactivates it immediately", "It is too weak", "It is exhaled before absorption", "It acts only on the heart"], "correct": 0, "explanation": "Binding to Hb forms methemoglobin.", "srcItem": "What NO Is and What It Is Used For"},
    {"id": "q-f203-g05-046", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the approved use of inhaled NO?", "choices": ["Neonates with hypoxic respiratory failure / PPHN", "Adult ARDS survival", "Asthma", "COPD maintenance"], "correct": 0, "explanation": "Deck trick: \"NO = Neonates Only\" (term and near-term > 34 weeks).", "srcItem": "What NO Is and What It Is Used For"},
    {"id": "q-f203-g05-047", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Does inhaled NO improve survival in ARDS?", "choices": ["No — it improves oxygenation only temporarily", "Yes — significantly", "Yes — when used for months", "Only above 80 ppm"], "correct": 0, "explanation": "It is a short-term bridge; prolonged use is not recommended.", "srcItem": "What NO Is and What It Is Used For"},
    {"id": "q-f203-g05-048", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the recommended starting dose of inhaled NO?", "choices": ["20 ppm", "800 ppm", "80 ppm", "1 ppm"], "correct": 0, "explanation": "Up to 14 days; cylinders hold 800 ppm.", "srcItem": "What NO Is and What It Is Used For"},
    {"id": "q-f203-g05-049", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What toxic gas forms when NO contacts oxygen?", "choices": ["Nitrogen dioxide (NO₂)", "Carbon monoxide", "Ozone", "Hydrogen cyanide"], "correct": 0, "explanation": "A higher FiO₂ makes more NO₂; OSHA limit 5 ppm.", "srcItem": "Side Effects"},
    {"id": "q-f203-g05-050", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What blood disorder can inhaled NO cause?", "choices": ["Methemoglobinemia", "Polycythemia", "Sickle cell crisis", "Thrombocytosis"], "correct": 0, "explanation": "MetHb doesn't carry O₂ and shifts the ODC left.", "srcItem": "Side Effects"},
    {"id": "q-f203-g05-051", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What happens if inhaled NO is stopped abruptly?", "choices": ["Rebound pulmonary hypertension", "Immediate improvement", "Hypercapnia only", "Nothing"], "correct": 0, "explanation": "Rebound can be severe and cause desaturation.", "srcItem": "Side Effects"},
    {"id": "q-f203-g05-052", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In which neonates is inhaled NO contraindicated?", "choices": ["Those dependent on a right-to-left shunt", "All premature infants", "Infants with PPHN", "Infants on ECMO"], "correct": 0, "explanation": "Deck contraindication.", "srcItem": "Side Effects"},
    {"id": "q-f203-g05-053", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Above what dose do the risks of MetHb and NO₂ rise without added benefit?", "choices": ["20 ppm", "5 ppm", "1 ppm", "100 ppm"], "correct": 0, "explanation": "No added response above 20 ppm.", "srcItem": "Side Effects"},
    {"id": "q-f203-g05-054", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is inhaled NO weaned to avoid rebound?", "choices": ["In small 3–5 ppm steps", "All at once", "By doubling the dose first", "By lowering FiO₂ to 21% first"], "correct": 0, "explanation": "Before withdrawal: lowest effective dose (≤ 5–6 ppm), FiO₂ ≤ 40%, PEEP ≤ 5, stable hemodynamics.", "srcItem": "Inhaled NO"},
    {"id": "q-f203-g05-055", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "MetHb rises above 1.5% during iNO. What should be recommended?", "choices": ["Decrease the iNO dose as tolerated", "Increase the dose", "Stop all oxygen", "Give methylene blue only"], "correct": 0, "explanation": "Ch 12/13 deck recommendation.", "srcItem": "Inhaled NO"},
    {"id": "q-f203-g05-056", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where does the INOvent/INOmax system inject NO?", "choices": ["Into the inspiratory side of the ventilator circuit near its outlet", "Into the expiratory limb", "Directly into the ETT cuff", "Into the humidifier water"], "correct": 0, "explanation": "A flow sensor adjusts injection to keep the ppm constant.", "srcItem": "Inhaled NO"},
    {"id": "q-f203-g05-057", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which inhaled pulmonary vasodilators are aerosols rather than gases?", "choices": ["Iloprost, treprostinil and epoprostenol", "Nitric oxide and helium", "Albuterol and ipratropium", "Montelukast and zileuton"], "correct": 0, "explanation": "They dilate pulmonary arteries and decrease platelet aggregation.", "srcItem": "Inhaled NO"},
    {"id": "q-f203-g05-058", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is healthcare-worker exposure to an inhaled prostacyclin reduced?", "choices": ["Expiratory filters and/or a negative-pressure room", "Opening the windows", "Using a simple mask", "No precautions are needed"], "correct": 0, "explanation": "Titration is extremely important, especially with Flolan.", "srcItem": "Inhaled NO"},
    {"id": "q-f203-g05-059", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What COHb level indicates CO poisoning in the RCP 203 decks?", "choices": ["> 20%", "1–3%", "5–10%", "< 1.5%"], "correct": 0, "explanation": "Both Lssn 3a and 3b: > 20% = CO poisoning.", "srcItem": "COHb Levels (%)"},
    {"id": "q-f203-g05-060", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is a normal COHb level per RCP 203 Lssn 3a?", "choices": ["1–3%", "10–15%", "20–30%", "> 40%"], "correct": 0, "explanation": "Lssn 1 says < 1.5%; know both.", "srcItem": "COHb Levels (%)"},
    {"id": "q-f203-g05-061", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why does CO cause tissue hypoxia?", "choices": ["It binds Hb ~200–250× more strongly than O₂ and shifts the ODC left", "It blocks the airway", "It raises PaO₂", "It dilates vessels"], "correct": 0, "explanation": "Less Hb carries O₂, and the remaining O₂ is held more tightly.", "srcItem": "COHb Levels (%)"},
    {"id": "q-f203-g05-062", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How should carboxyhemoglobin be measured?", "choices": ["CO-oximetry", "Standard pulse oximetry", "PaO₂ on an ABG", "Capnography"], "correct": 0, "explanation": "A normal PaO₂/SpO₂ does not rule out CO poisoning.", "srcItem": "How to Measure CO: CO-oximetry"},
    {"id": "q-f203-g05-063", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does a standard pulse oximeter read in CO poisoning?", "choices": ["Falsely high — SpO₂ > actual SaO₂", "Falsely low", "Accurately", "It shows zero"], "correct": 0, "explanation": "It cannot distinguish oxyhemoglobin from carboxyhemoglobin.", "srcItem": "How to Measure CO: CO-oximetry"},
    {"id": "q-f203-g05-064", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "SpO₂ reads 90% with a COHb of 7%. What is the true saturation?", "choices": ["83%", "97%", "90%", "63%"], "correct": 0, "explanation": "Subtract COHb from SpO₂.", "srcItem": "How to Measure CO: CO-oximetry"},
    {"id": "q-f203-g05-065", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Should a low SpCO reading rule out CO poisoning?", "choices": ["No — confirm with blood HbCO", "Yes — always", "Only in children", "Only below 1%"], "correct": 0, "explanation": "Hess: SpCO accuracy is ±6%; not for triage or management.", "srcItem": "How to Measure CO: CO-oximetry"},
    {"id": "q-f203-g05-066", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the first treatment for CO poisoning?", "choices": ["100% O₂ immediately", "Wait for COHb results", "Nasal cannula at 2 L/min", "Hyperbaric oxygen before any O₂"], "correct": 0, "explanation": "Ch 11: highest possible FiO₂; non-rebreather with tight seal, or intubate at FiO₂ 1.0.", "srcItem": "Treatment"},
    {"id": "q-f203-g05-067", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the COHb half-life on 100% O₂ per the deck?", "choices": ["~60–90 minutes", "~4–5 hours", "~20–30 minutes", "~24 hours"], "correct": 0, "explanation": "Room air ~4–5 h; HBO ~20–30 min.", "srcItem": "Treatment"},
    {"id": "q-f203-g05-068", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When should HBOT be considered for CO poisoning?", "choices": ["Severe poisoning, especially with neurologic depression or cardiac involvement", "Any COHb above 2%", "Only in smokers", "Never"], "correct": 0, "explanation": "The decision is not based on COHb alone; don't delay O₂ while deciding.", "srcItem": "Treatment"},
    {"id": "q-f203-g05-069", "topic": "f203-g05", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Mild–moderate CO poisoning is treated with 100% O₂ until COHb is below what?", "choices": ["5%", "20%", "1%", "50%"], "correct": 0, "explanation": "RCP 105 Nontraditional Settings.", "srcItem": "Treatment"},
    {"id": "q-f203-g06-001", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does a vane (Wright) respirometer measure?", "choices": ["Gas volume", "Gas pressure", "Oxygen concentration", "Carbon dioxide"], "correct": 0, "explanation": "Gas spins a vane; gears move hands on a dial to show volume.", "srcItem": "Vane Respirometer"},
    {"id": "q-f203-g06-002", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does a vane respirometer err at high and low flows?", "choices": ["Overreads at high flows and underreads at low flows", "Underreads at high flows and overreads at low flows", "Accurate at all flows", "Reads zero at high flows"], "correct": 0, "explanation": "Momentum keeps the vane spinning at high flow; friction resists it at low flow.", "srcItem": "Vane Respirometer"},
    {"id": "q-f203-g06-003", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why should a vane respirometer not be used for forced spirometry?", "choices": ["It is easily damaged by flows outside its range", "It cannot measure volume", "It needs a gas source", "It reads pressure only"], "correct": 0, "explanation": "NBRC takeaway: never measure forced flows or volumes with it.", "srcItem": "Vane Respirometer"},
    {"id": "q-f203-g06-004", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "V̇E is 8 L/min with a rate of 16/min. What is the average VT?", "choices": ["500 mL", "128 mL", "2 L", "50 mL"], "correct": 0, "explanation": "VT = V̇E ÷ f = 8 ÷ 16 = 0.5 L.", "srcItem": "Wright Respirometer: Bedside Setup and Use"},
    {"id": "q-f203-g06-005", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where is the Wright respirometer attached for routine measurements?", "choices": ["On the exhalation side of a one-way valve", "On the inspiratory limb of a ventilator", "Directly in the mouth with no valve", "On the oxygen flowmeter"], "correct": 0, "explanation": "Normal use measures expiratory volumes from the exhalation side.", "srcItem": "Wright Respirometer: Bedside Setup and Use"},
    {"id": "q-f203-g06-006", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A Wright respirometer will not register. What should be checked first?", "choices": ["The on/off switch and its position relative to the valve", "The FiO₂", "The battery", "The patient's heart rate"], "correct": 0, "explanation": "Recheck the on/off switch and its position on the valve.", "srcItem": "Wright Respirometer: Bedside Setup and Use"},
    {"id": "q-f203-g06-007", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does a peak flowmeter measure?", "choices": ["Maximum flow on forced expiration, reflecting the larger airways", "Total lung capacity", "Oxygen saturation", "Inspiratory capacity"], "correct": 0, "explanation": "PEFR is effort-dependent, used for monitoring, not diagnosis.", "srcItem": "Peak Flowmeter"},
    {"id": "q-f203-g06-008", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A patient's PEF is 7 L/s against a predicted 10 L/s. How is this interpreted?", "choices": ["70% predicted — expiratory flow obstruction (or poor effort)", "100% — normal", "Above normal", "Restrictive disease"], "correct": 0, "explanation": "< 80% predicted = obstruction; always consider poor effort.", "srcItem": "Peak Flowmeter"},
    {"id": "q-f203-g06-009", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which peak flow zone is 50–80% of personal best (deck)?", "choices": ["Yellow", "Green", "Red", "Blue"], "correct": 0, "explanation": "Deck: green 80–100%, yellow 50–80%, red < 50%.", "srcItem": "Peak Flowmeter"},
    {"id": "q-f203-g06-010", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What principle is the basis of manometric pressure measurement?", "choices": ["Pascal's law", "Boyle's law", "Dalton's law", "Charles's law"], "correct": 0, "explanation": "Pressure is transmitted without reduction through an enclosed static fluid.", "srcItem": "Pressure Manometer"},
    {"id": "q-f203-g06-011", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the goal cuff pressure measured with a manometer?", "choices": ["20–30 cm H₂O", "5–10 cm H₂O", "40–50 cm H₂O", "60 cm H₂O"], "correct": 0, "explanation": "Goal 20–30 cm H₂O; attaching the manometer loses volume, so always adjust.", "srcItem": "Pressure Manometer"},
    {"id": "q-f203-g06-012", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the deck give as a normal NIF?", "choices": ["More negative than −60 cm H₂O", "−10 cm H₂O", "+20 cm H₂O", "0 cm H₂O"], "correct": 0, "explanation": "Normal > −60; COPD > −40; myasthenia gravis > −20 (magnitude).", "srcItem": "Pressure Manometer"},
    {"id": "q-f203-g06-013", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the difference between capnometry and capnography?", "choices": ["Capnometry is the number; capnography is the number plus the waveform", "They are identical", "Capnography measures O₂", "Capnometry measures pressure"], "correct": 0, "explanation": "Capnogram = the waveform.", "srcItem": "Capnometer"},
    {"id": "q-f203-g06-014", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the main problem with a sidestream capnometer?", "choices": ["Condensate occluding the sampling tube", "It adds dead space at the airway", "It is too heavy", "It must be heated"], "correct": 0, "explanation": "Sidestream is useful for non-intubated patients; condensate can block the line.", "srcItem": "Capnometer"},
    {"id": "q-f203-g06-015", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What gas is used for the capnometer's high calibration point?", "choices": ["5% CO₂", "100% O₂", "21% O₂", "10% helium"], "correct": 0, "explanation": "5% CO₂ (PCO₂ 38 torr), standard ±0.3%; auto-zero corrects offset only.", "srcItem": "Capnometer"},
    {"id": "q-f203-g06-016", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How much less than PaCO₂ is PETCO₂ normally?", "choices": ["About 1–5 torr", "About 20 torr", "About 50 torr", "It is always higher"], "correct": 0, "explanation": "PETCO₂ runs 1–5 torr below PaCO₂ (more with high dead space).", "srcItem": "Capnometer"},
    {"id": "q-f203-g06-017", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What volume syringe is used to calibrate PFT equipment?", "choices": ["3.0 L", "1.0 L", "10 L", "500 mL"], "correct": 0, "explanation": "A 3.0-L syringe, daily before patient testing.", "srcItem": "The 3-L Syringe in PFTs: When and Why"},
    {"id": "q-f203-g06-018", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the deck's accepted range for a 3-L syringe calibration?", "choices": ["2.91–3.09 L", "2.5–3.5 L", "2.0–4.0 L", "2.99–3.01 L"], "correct": 0, "explanation": "ATS: ±3% or ±50 mL → 2.91–3.09 L.", "srcItem": "The 3-L Syringe in PFTs: When and Why"},
    {"id": "q-f203-g06-019", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "The 3-L syringe reads 2.80 L. What should be suspected?", "choices": ["A leak — repeat the leak check", "BTPS left on", "Too much humidity", "The syringe is too large"], "correct": 0, "explanation": "Low → think leak; high → think setup (BTPS ON, zeroing, temperature).", "srcItem": "The 3-L Syringe in PFTs: When and Why"},
    {"id": "q-f203-g06-020", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "If BTPS correction is left ON during calibration, what happens?", "choices": ["The reading is about 10% high", "The reading is about 10% low", "No effect", "The spirometer turns off"], "correct": 0, "explanation": "BTPS must be OFF, or the reading is ~10% high.", "srcItem": "The 3-L Syringe in PFTs: When and Why"},
    {"id": "q-f203-g06-021", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On a Levey-Jennings chart, what are the bounding limits?", "choices": ["±2 SD", "±1 SD", "±5 SD", "±10%"], "correct": 0, "explanation": "All controls within ±2 SD → in control.", "srcItem": "Standard Deviation (SD) Accepted Ranges in QC"},
    {"id": "q-f203-g06-022", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Two consecutive controls fall outside ±2 SD. What does this mean?", "choices": ["Out of control — recalibrate or replace the electrode", "A warning only", "Normal variation", "The patient is unstable"], "correct": 0, "explanation": "One out = warning; two or more consecutive = out of control.", "srcItem": "Standard Deviation (SD) Accepted Ranges in QC"},
    {"id": "q-f203-g06-023", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which type of QC error is more serious?", "choices": ["Systematic (bias) errors", "Single random errors", "Both equal", "Neither"], "correct": 0, "explanation": "Bias errors are more serious; no patient samples until corrected.", "srcItem": "Standard Deviation (SD) Accepted Ranges in QC"},
    {"id": "q-f203-g06-024", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which volumes make up the FRC?", "choices": ["RV + ERV", "IRV + VT", "VT + ERV", "IRV + RV"], "correct": 0, "explanation": "FRC = RV + ERV; IC = VT + IRV; VC = VT + IRV + ERV; TLC = RV + VC.", "srcItem": "All Lung Volumes and Capacities"},
    {"id": "q-f203-g06-025", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the deck's normal TLC?", "choices": ["6.0 L", "2.4 L", "4.8 L", "1.2 L"], "correct": 0, "explanation": "Normals: VT 0.5, IRV 3.1, ERV 1.2, RV 1.2, FRC 2.4, VC 4.8, TLC 6.0 L.", "srcItem": "All Lung Volumes and Capacities"},
    {"id": "q-f203-g06-026", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which lung volume cannot be measured with simple spirometry?", "choices": ["Residual volume (and therefore FRC and TLC)", "Tidal volume", "Vital capacity", "Inspiratory capacity"], "correct": 0, "explanation": "RV can't be exhaled; FRC must be measured separately, then RV = FRC − ERV.", "srcItem": "All Lung Volumes and Capacities"},
    {"id": "q-f203-g06-027", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal vital capacity per the deck?", "choices": ["About 4.8 L (~50 mL/kg IBW)", "About 0.5 L", "About 10 L", "About 1.2 L"], "correct": 0, "explanation": "VC = VT + IRV + ERV ≈ 4.8 L.", "srcItem": "All Lung Volumes and Capacities"},
    {"id": "q-f203-g06-028", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What FEV₁/FVC ratio indicates obstruction on this exam?", "choices": ["< 70%", "< 90%", "> 100%", "< 30% only"], "correct": 0, "explanation": "Deck: FEV₁/FVC < 70% = obstructive.", "srcItem": "Spirometry Values"},
    {"id": "q-f203-g06-029", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the FEF25–75% mainly reflect?", "choices": ["Small-airway function", "Large-airway function", "Lung volume", "Diffusing capacity"], "correct": 0, "explanation": "≤ 70% predicted = small-airway obstruction; may be low with a normal FEV₁.", "srcItem": "Spirometry Values"},
    {"id": "q-f203-g06-030", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What makes a spirometry session acceptable for repeatability?", "choices": ["The two largest FVC and the two largest FEV₁ within 150 mL", "One good effort", "Five efforts within 1 L", "Any three efforts"], "correct": 0, "explanation": "At least three error-free efforts; two largest FVC and FEV₁ each within 150 mL.", "srcItem": "Spirometry Values"},
    {"id": "q-f203-g06-031", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What % predicted is normal for FVC and FEV₁ per the deck?", "choices": ["≥ 80%", "≥ 50%", "≥ 100%", "≥ 65%"], "correct": 0, "explanation": "Deck cutoffs: ≥ 80% predicted normal.", "srcItem": "Spirometry Values"},
    {"id": "q-f203-g06-032", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "FEV₁ rises from 3.0 to 3.3 L after a bronchodilator. Is this significant reversibility?", "choices": ["No — 10% is below the 12–15% criterion", "Yes — any rise is significant", "Yes — 300 mL is all that matters", "Cannot be calculated"], "correct": 0, "explanation": "(3.3 − 3.0) ÷ 3.0 = 10% → not reversible.", "srcItem": "Pre/Post Bronchodilator Response"},
    {"id": "q-f203-g06-033", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What defines a reversible response to a bronchodilator (RCP 203)?", "choices": ["FEV₁ improves ≥ 12–15% and by ≥ 200 mL", "FEV₁ improves 5%", "FVC falls by 20%", "PEF falls"], "correct": 0, "explanation": "Use the RCP 203 slide: 12–15% and 200 mL.", "srcItem": "Pre/Post Bronchodilator Response"},
    {"id": "q-f203-g06-034", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When is post-bronchodilator spirometry repeated?", "choices": ["At the drug's peak response, usually 15–30 minutes", "Immediately", "After 24 hours", "After 1 week"], "correct": 0, "explanation": "Repeat at peak response time, usually 15–30 minutes.", "srcItem": "Pre/Post Bronchodilator Response"},
    {"id": "q-f203-g06-035", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does the nitrogen washout test measure FRC?", "choices": ["The patient breathes 100% O₂ and the N₂ washed out of the FRC is measured", "The patient rebreathes helium", "The patient pants in a body box", "The patient exhales forcefully"], "correct": 0, "explanation": "It ends when exhaled N₂ < 1.5% for 3 breaths.", "srcItem": "Lung-Volume Measurement (FRC → RV, TLC)"},
    {"id": "q-f203-g06-036", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which method measures trapped gas, including bullae?", "choices": ["Body plethysmography", "Helium dilution", "Nitrogen washout", "Simple spirometry"], "correct": 0, "explanation": "The body box (Boyle's law) measures all thoracic gas; dilution methods measure only communicating gas.", "srcItem": "Lung-Volume Measurement (FRC → RV, TLC)"},
    {"id": "q-f203-g06-037", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Thoracic gas volume (body box) is larger than the helium-dilution FRC. What does this mean?", "choices": ["Trapped gas, as in bullous emphysema", "A leak in the system", "Normal lungs", "Restrictive disease"], "correct": 0, "explanation": "Normally FRC = TGV; TGV > FRC = trapped gas.", "srcItem": "Lung-Volume Measurement (FRC → RV, TLC)"},
    {"id": "q-f203-g06-038", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "During helium dilution, a leak occurs. What happens to the measured FRC?", "choices": ["It reads falsely high", "It reads falsely low", "It is unaffected", "It reads zero"], "correct": 0, "explanation": "Hess: a leak → falsely high FRC.", "srcItem": "Lung-Volume Measurement (FRC → RV, TLC)"},
    {"id": "q-f203-g06-039", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is a positive methacholine challenge?", "choices": ["A fall in FEV₁ of ≥ 20%", "A rise in FEV₁ of 20%", "A fall in FEV₁ of 5%", "No change in FEV₁"], "correct": 0, "explanation": "FEV₁ ↓ ≥ 20% = hyperresponsiveness consistent with asthma (PD20).", "srcItem": "Bronchoprovocation and the Methacholine Challenge"},
    {"id": "q-f203-g06-040", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When is bronchoprovocation testing used?", "choices": ["When spirometry is nondiagnostic but asthma is suspected", "When obstruction is already severe", "To diagnose pneumothorax", "For every patient with a cough"], "correct": 0, "explanation": "Mild asthma often has normal spirometry between episodes.", "srcItem": "Bronchoprovocation and the Methacholine Challenge"},
    {"id": "q-f203-g06-041", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When is methacholine challenge contraindicated?", "choices": ["Moderate to severe airflow obstruction", "Normal spirometry", "Suspected asthma", "Exercise-induced cough"], "correct": 0, "explanation": "Hess: contraindicated in moderate to severe obstruction.", "srcItem": "Bronchoprovocation and the Methacholine Challenge"},
    {"id": "q-f203-g06-042", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What type of drug is methacholine?", "choices": ["A direct-acting cholinergic (parasympathomimetic)", "A beta-agonist", "A corticosteroid", "An anticholinergic"], "correct": 0, "explanation": "It provokes bronchoconstriction in hyperresponsive airways.", "srcItem": "Bronchoprovocation and the Methacholine Challenge"},
    {"id": "q-f203-g06-043", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which PFT pattern fits restrictive disease?", "choices": ["Reduced TLC with normal or increased FEV₁/FVC", "Increased TLC with low FEV₁/FVC", "Normal TLC with low FEF25–75%", "Increased RV/TLC"], "correct": 0, "explanation": "Restrictive: ↓ volumes, TLC < 80% predicted; a low TLC confirms it.", "srcItem": "Obstructive vs Restrictive Disease"},
    {"id": "q-f203-g06-044", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does DLCO differ between emphysema and asthma?", "choices": ["Decreased in emphysema; normal or increased in asthma", "Increased in emphysema; decreased in asthma", "Normal in both", "Decreased in both"], "correct": 0, "explanation": "DLCO ↓ in emphysema and ILD; normal/↑ in asthma and chronic bronchitis.", "srcItem": "Obstructive vs Restrictive Disease"},
    {"id": "q-f203-g06-045", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "An elevated RV and RV/TLC indicate what?", "choices": ["Air trapping (obstruction)", "Restriction", "Normal lungs", "Neuromuscular weakness only"], "correct": 0, "explanation": "Obstruction: ↑ RV and RV/TLC = air trapping.", "srcItem": "Obstructive vs Restrictive Disease"},
    {"id": "q-f203-g06-046", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is a restrictive disorder?", "choices": ["Guillain-Barré syndrome", "Asthma", "COPD", "Bronchiectasis"], "correct": 0, "explanation": "Restrictive: ILD, atelectasis, pleural effusion, neuromuscular disease.", "srcItem": "Obstructive vs Restrictive Disease"},
    {"id": "q-f203-g06-047", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where does the tip of a CVP catheter sit?", "choices": ["In the superior vena cava near the right atrium", "In the pulmonary artery", "In the left atrium", "In the aorta"], "correct": 0, "explanation": "CVP ≈ RAP, reflecting right-heart filling pressure (RV preload).", "srcItem": "CVP Catheter"},
    {"id": "q-f203-g06-048", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does a low CVP suggest?", "choices": ["Hypovolemia", "Fluid overload", "Left heart failure", "Pulmonary hypertension"], "correct": 0, "explanation": "Low CVP → hypovolemia; high CVP → fluid overload.", "srcItem": "CVP Catheter"},
    {"id": "q-f203-g06-049", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When should hemodynamic pressures be read?", "choices": ["At end-expiration, with the transducer at the phlebostatic axis", "At peak inspiration", "During a cough", "With the patient off PEEP"], "correct": 0, "explanation": "Level at the 4th ICS midaxillary line; do not remove PEEP.", "srcItem": "CVP Catheter"},
    {"id": "q-f203-g06-050", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which pressure is read with the PA catheter balloon inflated?", "choices": ["PCWP (wedge pressure)", "PA pressure", "CVP", "Systemic BP"], "correct": 0, "explanation": "PAP is read with the balloon deflated; inflate briefly for PCWP, then deflate.", "srcItem": "PA (Swan-Ganz) Catheter"},
    {"id": "q-f203-g06-051", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does PCWP reflect?", "choices": ["Left atrial pressure / left ventricular preload", "Right atrial pressure", "Pulmonary artery systolic pressure", "Systemic vascular resistance"], "correct": 0, "explanation": "PCWP > 18 mm Hg suggests cardiogenic pulmonary edema; ARDS is normal or low.", "srcItem": "PA (Swan-Ganz) Catheter"},
    {"id": "q-f203-g06-052", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the maximum PA catheter balloon volume?", "choices": ["1.5 mL", "5 mL", "10 mL", "0.1 mL"], "correct": 0, "explanation": "Use only the 1.0–1.5 mL syringe supplied.", "srcItem": "PA (Swan-Ganz) Catheter"},
    {"id": "q-f203-g06-053", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is thermodilution cardiac output measured?", "choices": ["10 mL of cold or room-temperature fluid is injected into the proximal port and the tip thermistor senses the change", "Through a blood culture", "By pulse oximetry", "By chest radiograph"], "correct": 0, "explanation": "Proximal port in the RA; thermistor at the tip in the PA.", "srcItem": "PA (Swan-Ganz) Catheter"},
    {"id": "q-f203-g06-054", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal cardiac index?", "choices": ["2.5–3.5 L/min/m²", "4–8 L/min/m²", "0.5–1.0 L/min/m²", "10–12 L/min/m²"], "correct": 0, "explanation": "CI = CO ÷ BSA; normal CO 4–8 L/min.", "srcItem": "Normal Ranges: CVP, RAP, PACP/PCWP, CO, CI"},
    {"id": "q-f203-g06-055", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "For this exam, which PA pressure range should be used (Ch 16 PowerPoint)?", "choices": ["15–30 / 4–12 mm Hg", "120/80 mm Hg", "5–10 / 0–2 mm Hg", "40–60 / 20–30 mm Hg"], "correct": 0, "explanation": "Ch 16: RA 2–6, RV 15–30/0–8, PA 15–30/4–12, PAWP 6–12.", "srcItem": "Normal Ranges: CVP, RAP, PACP/PCWP, CO, CI"},
    {"id": "q-f203-g06-056", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal PAWP (wedge) range in the Ch 16 PowerPoint?", "choices": ["6–12 mm Hg", "20–25 mm Hg", "0–2 mm Hg", "15–30 mm Hg"], "correct": 0, "explanation": "Answer with Ch 16's 6–12; recognize RCP 105's 8–12.", "srcItem": "Normal Ranges: CVP, RAP, PACP/PCWP, CO, CI"},
    {"id": "q-f203-g06-057", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal cardiac output range in the deck?", "choices": ["4–8 L/min", "1–2 L/min", "10–15 L/min", "20 L/min"], "correct": 0, "explanation": "CO = SV × HR; RCP 105 and RCP 203: 4–8 L/min.", "srcItem": "Normal Ranges: CVP, RAP, PACP/PCWP, CO, CI"},
    {"id": "q-f203-g06-058", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "According to the deck's memory trick, which diuretic is used 'for Lungs'?", "choices": ["Loop diuretics such as furosemide", "Thiazides", "Potassium-sparing diuretics", "Carbonic anhydrase inhibitors"], "correct": 0, "explanation": "\"Loops for Lungs, Thiazides for BP, K-sparing for Potassium.\"", "srcItem": "Diuretic Classes"},
    {"id": "q-f203-g06-059", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is a key adverse effect of loop diuretics?", "choices": ["Hypokalemia and metabolic alkalosis", "Hyperkalemia", "Metabolic acidosis", "Hypernatremia only"], "correct": 0, "explanation": "Loops: hypokalemia, metabolic alkalosis, volume depletion, ototoxicity.", "srcItem": "Diuretic Classes"},
    {"id": "q-f203-g06-060", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which diuretic class causes hyperkalemia?", "choices": ["Potassium-sparing (spironolactone)", "Loop", "Thiazide", "Osmotic"], "correct": 0, "explanation": "K-sparing protects K⁺ and can cause hyperkalemia.", "srcItem": "Diuretic Classes"},
    {"id": "q-f203-g06-061", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which diuretic is used for TBI with cerebral edema?", "choices": ["Mannitol (osmotic)", "Furosemide", "Spironolactone", "Hydrochlorothiazide"], "correct": 0, "explanation": "Mannitol can worsen pulmonary edema and CHF.", "srcItem": "Diuretic Classes"},
    {"id": "q-f203-g06-062", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which diuretic class causes metabolic acidosis and treats metabolic alkalosis?", "choices": ["Carbonic anhydrase inhibitors (acetazolamide)", "Loop diuretics", "Thiazides", "Potassium-sparing diuretics"], "correct": 0, "explanation": "Acetazolamide: glaucoma, metabolic alkalosis, altitude sickness.", "srcItem": "Diuretic Classes"},
    {"id": "q-f203-g06-063", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How do IV loop diuretics help in acute pulmonary edema before urine output rises?", "choices": ["They cause vasodilation within 5 minutes, lowering PCWP, BP and SVR", "They raise preload", "They constrict pulmonary vessels", "They increase heart rate"], "correct": 0, "explanation": "Preload reduction is the goal; furosemide is the cornerstone.", "srcItem": "The Role of Diuretics"},
    {"id": "q-f203-g06-064", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What are the top three adverse effects of diuretics in the deck?", "choices": ["Hypovolemia, hypokalemia and metabolic alkalosis", "Hypertension, hyperkalemia, acidosis", "Hypoglycemia, fever, rash", "Bradycardia, apnea, seizures"], "correct": 0, "explanation": "Treat diuretic-induced alkalosis by reducing the diuretic and giving Cl⁻ and K⁺.", "srcItem": "The Role of Diuretics"},
    {"id": "q-f203-g06-065", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why should mannitol not be given for diuresis in fluid overload?", "choices": ["It first raises plasma volume", "It causes hypokalemia only", "It is too weak", "It has no effect on urine"], "correct": 0, "explanation": "Mannitol initially expands plasma volume.", "srcItem": "The Role of Diuretics"},
    {"id": "q-f203-g06-066", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A pressure transducer sits below the phlebostatic axis. How do the readings change?", "choices": ["They read falsely high", "They read falsely low", "No change", "They read zero"], "correct": 0, "explanation": "Below → falsely high; above → falsely low (water-level gauge).", "srcItem": "The Ch 16 PowerPoint"},
    {"id": "q-f203-g06-067", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Why is the head of the bed lowered (Trendelenburg) for CVP insertion?", "choices": ["The vein fills and the risk of air embolism falls", "To improve breathing", "To lower the BP", "To prevent pneumothorax"], "correct": 0, "explanation": "Also confirm the tip in the SVC by CXR; pneumothorax is a risk, especially subclavian.", "srcItem": "The Ch 16 PowerPoint"},
    {"id": "q-f203-g06-068", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "As a PA catheter advances from the RV into the pulmonary artery, what waveform change is seen?", "choices": ["The diastolic pressure rises and a dicrotic notch appears", "The pressure drops to zero", "The waveform becomes flat", "Systolic pressure falls to 5 mm Hg"], "correct": 0, "explanation": "RV: high systolic, low diastolic; PA: diastolic rises, dicrotic notch (pulmonic valve).", "srcItem": "The Ch 16 PowerPoint"},
    {"id": "q-f203-g06-069", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What happens to the waveform when the PA catheter wedges?", "choices": ["Pulse-pressure swings disappear", "The pressure doubles", "A dicrotic notch appears", "It shows ventricular pressures"], "correct": 0, "explanation": "Wedge: pulsatile swings disappear; read PAWP then deflate.", "srcItem": "The Ch 16 PowerPoint"},
    {"id": "q-f203-g06-070", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is C(a-v)O₂ calculated?", "choices": ["CaO₂ − CvO₂", "PaO₂ − PvO₂", "SaO₂ − SvO₂", "CvO₂ − CaO₂"], "correct": 0, "explanation": "It reflects the O₂ used by the tissues.", "srcItem": "How to Calculate C(a-v)O₂, With a Worked Example"},
    {"id": "q-f203-g06-071", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is CaO₂ calculated?", "choices": ["(1.34 × Hb × SaO₂) + (0.003 × PaO₂)", "Hb × PaO₂", "SaO₂ ÷ PaO₂", "(0.003 × Hb) + (1.34 × PaO₂)"], "correct": 0, "explanation": "Hemoglobin-bound plus dissolved O₂, in mL/100 mL.", "srcItem": "How to Calculate C(a-v)O₂, With a Worked Example"},
    {"id": "q-f203-g06-072", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Hb 15, SaO₂ 97%, PaO₂ 100. What is the CaO₂?", "choices": ["About 20 mL/dL", "About 15 mL/dL", "About 10 mL/dL", "About 30 mL/dL"], "correct": 0, "explanation": "15 × 1.34 × 0.97 = 19.5 + 0.3 = 19.8 ≈ 20.", "srcItem": "How to Calculate C(a-v)O₂, With a Worked Example"},
    {"id": "q-f203-g06-073", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal C(a-v)O₂ at rest?", "choices": ["About 5 mL/100 mL", "About 20 mL/100 mL", "About 0.5 mL/100 mL", "About 15 mL/100 mL"], "correct": 0, "explanation": "20 − 15 ≈ 5 mL/100 mL; tissues extract ~25% of delivered O₂.", "srcItem": "How to Calculate C(a-v)O₂, With a Worked Example"},
    {"id": "q-f203-g06-074", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal CaO₂ range in RCP 203 Lssn 7?", "choices": ["16–22 mL O₂/dL", "5–8 mL O₂/dL", "30–40 mL O₂/dL", "1–2 mL O₂/dL"], "correct": 0, "explanation": "RCP 203: CaO₂ 16–22 mL O₂/dL.", "srcItem": "How to Calculate C(a-v)O₂, With a Worked Example"},
    {"id": "q-f203-g06-075", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does C(a-v)O₂ change with a large pleural effusion (RCP 103)?", "choices": ["It increases — tissues extract more O₂", "It decreases", "It stays exactly the same", "It becomes negative"], "correct": 0, "explanation": "RCP 103: large effusion → C(a-v)O₂ ↑.", "srcItem": "What Widens or Narrows It"},
    {"id": "q-f203-g06-076", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What PvO₂ suggests tissue hypoxia in a critically ill patient?", "choices": ["< 35 mm Hg", "> 45 mm Hg", "40 mm Hg", "100 mm Hg"], "correct": 0, "explanation": "Normal PvO₂ 35–45; < 35 suggests increased extraction.", "srcItem": "What Widens or Narrows It"},
    {"id": "q-f203-g06-077", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What happens to CvO₂ in sepsis with a greatly increased cardiac output?", "choices": ["It rises (extraction falls)", "It falls", "No change", "It becomes zero"], "correct": 0, "explanation": "Hess: extraction falls when CO rises greatly.", "srcItem": "What Widens or Narrows It"},
    {"id": "q-f203-g06-078", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What normal SvO₂ does the RCP 105 Hemodynamic deck give?", "choices": ["75% (68–77%)", "95–100%", "40%", "50–55%"], "correct": 0, "explanation": "Use the deck's 68–77% (Hess: 65–75%).", "srcItem": "What Widens or Narrows It"},
    {"id": "q-f203-g06-079", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which capnometer type is best for non-intubated patients?", "choices": ["Sidestream (aspirating)", "Mainstream", "Neither", "Both equally only in neonates"], "correct": 0, "explanation": "Mainstream suits intubated patients; sidestream samples via a tube.", "srcItem": "How Capnography Is Measured"},
    {"id": "q-f203-g06-080", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is a disadvantage of mainstream capnography?", "choices": ["Weight on the ETT and added dead space", "Tubing occlusion by water", "Long lag time", "It cannot be used in adults"], "correct": 0, "explanation": "Sidestream problems: secretions/water/kinks in the sampling line.", "srcItem": "How Capnography Is Measured"},
    {"id": "q-f203-g06-081", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the normal PETCO₂ range?", "choices": ["30–43 mm Hg", "5–10 mm Hg", "60–80 mm Hg", "100 mm Hg"], "correct": 0, "explanation": "PETCO₂ runs 1–5 torr below PaCO₂ (35–45).", "srcItem": "How Capnography Is Measured"},
    {"id": "q-f203-g06-082", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is preferred for confirming ETT placement?", "choices": ["Waveform capnography", "Listening to the stomach only", "Chest rise only", "A colorimetric detector changing once"], "correct": 0, "explanation": "Colorimetric is an alternative: purple → yellow over six or more breaths.", "srcItem": "How Capnography Is Measured"},
    {"id": "q-f203-g06-083", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A colorimetric CO₂ detector changes color only briefly after BVM ventilation. What should you suspect?", "choices": ["Stomach CO₂ — possible esophageal intubation", "Correct tracheal placement", "Bronchospasm", "ROSC"], "correct": 0, "explanation": "A transient change is less convincing; look for change over six or more breaths.", "srcItem": "How Capnography Is Measured"},
    {"id": "q-f203-g06-084", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which phase of the capnogram is exhaled pure dead-space gas?", "choices": ["A → B (phase I)", "B → C", "C → D", "D → E"], "correct": 0, "explanation": "Phase I: no CO₂; II: rapid rise; III: alveolar plateau; D → E: inhalation.", "srcItem": "The Normal Capnogram"},
    {"id": "q-f203-g06-085", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where on the capnogram is PETCO₂ read?", "choices": ["At the end of the alveolar plateau", "At the start of exhalation", "At the baseline", "During inhalation"], "correct": 0, "explanation": "PETCO₂ is read at D, the end of phase III.", "srcItem": "The Normal Capnogram"},
    {"id": "q-f203-g06-086", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What happens on the capnogram during inhalation?", "choices": ["CO₂ drops to zero", "CO₂ peaks", "CO₂ plateaus", "CO₂ doubles"], "correct": 0, "explanation": "D → E: fresh gas inhaled, CO₂ falls to zero.", "srcItem": "The Normal Capnogram"},
    {"id": "q-f203-g06-087", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "The capnogram waveform and number disappear suddenly. What is the likely cause?", "choices": ["Disconnection", "Hyperventilation", "Fever", "Sodium bicarbonate"], "correct": 0, "explanation": "Sudden loss = disconnection; falling toward zero = obstruction.", "srcItem": "Sudden Decreases and Increases, and Abnormal Wave Shapes"},
    {"id": "q-f203-g06-088", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PETCO₂ drops suddenly and proportionally during ventilation. What should be considered?", "choices": ["Cardiac arrest (lungs not perfused)", "Malignant hyperthermia", "Fever", "Hypoventilation"], "correct": 0, "explanation": "A sudden drop suggests lost pulmonary perfusion.", "srcItem": "Sudden Decreases and Increases, and Abnormal Wave Shapes"},
    {"id": "q-f203-g06-089", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What causes an immediate rise in PETCO₂ after a drug is given?", "choices": ["IV sodium bicarbonate", "Albuterol", "Oxygen", "Normal saline"], "correct": 0, "explanation": "Bicarbonate forms CO₂.", "srcItem": "Sudden Decreases and Increases, and Abnormal Wave Shapes"},
    {"id": "q-f203-g06-090", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "The capnogram baseline doesn't return to zero. What does this indicate?", "choices": ["CO₂ rebreathing or a circuit problem", "Normal function", "Hyperventilation", "Esophageal intubation"], "correct": 0, "explanation": "Inspired CO₂ should be zero.", "srcItem": "Sudden Decreases and Increases, and Abnormal Wave Shapes"},
    {"id": "q-f203-g06-091", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A 'shark-fin' capnogram suggests what?", "choices": ["Acute partial airway obstruction such as bronchospasm", "Disconnection", "Normal ventilation", "Hypothermia"], "correct": 0, "explanation": "Heuer: bronchospasm, kinked ETT or mucus plug.", "srcItem": "Sudden Decreases and Increases, and Abnormal Wave Shapes"},
    {"id": "q-f203-g06-092", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PETCO₂ falls because of a pulmonary embolism. What should the RT NOT do?", "choices": ["Lower the ventilator rate as if it were improvement", "Notify the physician", "Get an ABG", "Assess the patient"], "correct": 0, "explanation": "A dead-space fall is not improvement (RCP 105).", "srcItem": "Sudden Decreases and Increases, and Abnormal Wave Shapes"},
    {"id": "q-f203-g06-093", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "During CPR, what PETCO₂ means compressions must be improved?", "choices": ["< 10 mm Hg", "> 40 mm Hg", "35–45 mm Hg", "Exactly 20 mm Hg"], "correct": 0, "explanation": "Also intra-arterial diastolic pressure < 20 mm Hg.", "srcItem": "Capnography During CPR"},
    {"id": "q-f203-g06-094", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What PETCO₂ finding after 20 minutes of CPR may support stopping resuscitation?", "choices": ["Failure to exceed 10 mm Hg", "A rise above 40 mm Hg", "A steady 35 mm Hg", "Any value above 5"], "correct": 0, "explanation": "Failure to reach > 10 mm Hg after 20 minutes.", "srcItem": "Capnography During CPR"},
    {"id": "q-f203-g06-095", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which capnography change signals ROSC?", "choices": ["A sudden increase to ≥ 40 mm Hg", "A gradual fall to zero", "Loss of waveform", "A value below 10"], "correct": 0, "explanation": "With a palpable pulse, rising BP and better SpO₂.", "srcItem": "Capnography During CPR"},
    {"id": "q-f203-g06-096", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does a transcutaneous monitor estimate arterial gases?", "choices": ["A heated sensor 'arterializes' the capillary bed and gases diffuse into the sensor", "It draws blood through the skin", "It uses infrared light only", "It measures exhaled gas"], "correct": 0, "explanation": "Continuous noninvasive PtcO₂ and PtcCO₂.", "srcItem": "Electrode Placement"},
    {"id": "q-f203-g06-097", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What sensor temperature does the RCP 203 deck use for PtcO₂ and PtcCO₂?", "choices": ["44 °C", "37 °C", "50 °C", "30 °C"], "correct": 0, "explanation": "As low as 37 °C if monitoring PtcCO₂ only.", "srcItem": "Electrode Placement"},
    {"id": "q-f203-g06-098", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How often should the TcM site be changed per the RCP 203 deck?", "choices": ["Every 2–6 hours", "Every 24 hours", "Every 15 minutes", "Never"], "correct": 0, "explanation": "To avoid burns and skin damage.", "srcItem": "Electrode Placement"},
    {"id": "q-f203-g06-099", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which site is good for TcM electrode placement?", "choices": ["Side of the chest, abdomen or inner thigh", "Over a bony prominence", "On the scalp hair", "On the palm"], "correct": 0, "explanation": "Choose good superficial circulation; avoid bony surfaces.", "srcItem": "Electrode Placement"},
    {"id": "q-f203-g06-100", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How long does a TcM sensor take to stabilize?", "choices": ["5–20 minutes", "1 second", "2 hours", "Overnight"], "correct": 0, "explanation": "That is why TcM isn't used in emergencies.", "srcItem": "Electrode Placement"},
    {"id": "q-f203-g06-101", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "For a CCHD screen with dual TcM sensors, what difference suggests CCHD?", "choices": ["Pre-ductal PtcO₂ at least 15 torr higher than post-ductal", "Post-ductal higher than pre-ductal", "Any equal readings", "A 2-torr difference"], "correct": 0, "explanation": "Pre-ductal = right upper chest; post-ductal = abdomen or thigh.", "srcItem": "Electrode Placement"},
    {"id": "q-f203-g06-102", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the most common TcM problem?", "choices": ["Air leaking around the adhesive ring", "Overheating the sensor", "Battery failure", "Excess oxygen"], "correct": 0, "explanation": "A large leak makes values mimic room air (PO₂ ≈ 150, PCO₂ ≈ 0).", "srcItem": "Troubleshooting"},
    {"id": "q-f203-g06-103", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does an air leak at the sensor affect PtcCO₂?", "choices": ["It causes a dramatic fall", "It causes a rise", "No effect", "It doubles it"], "correct": 0, "explanation": "Fix by reapplying with a new adhesive ring.", "srcItem": "Troubleshooting"},
    {"id": "q-f203-g06-104", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "In shock with poor perfusion, how does PtcO₂ compare with PaO₂?", "choices": ["PtcO₂ underestimates PaO₂", "PtcO₂ overestimates PaO₂", "They match exactly", "PtcO₂ reads zero"], "correct": 0, "explanation": "Do not use TcM in shock or poor peripheral circulation.", "srcItem": "Troubleshooting"},
    {"id": "q-f203-g06-105", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Above what PaO₂ does the RCP 203 deck say PtcO₂ underestimates it?", "choices": ["100 torr", "40 torr", "60 torr", "300 torr"], "correct": 0, "explanation": "Use the deck's 100 torr (Chang says 80).", "srcItem": "Troubleshooting"},
    {"id": "q-f203-g06-106", "topic": "f203-g06", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "PaO₂ is substantially higher than PtcO₂. What is the likely cause?", "choices": ["Poor peripheral circulation", "Sensor overheating", "Hyperventilation", "A normal finding"], "correct": 0, "explanation": "Correlate with an arterial sample after setup or site change.", "srcItem": "Troubleshooting"},
    {"id": "q-f203-g07-001", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Polysomnography shows ventilatory effort with no airflow. What type of apnea is this?", "choices": ["Obstructive", "Central", "Mixed", "Hypopnea"], "correct": 0, "explanation": "Effort but no airflow = obstructive; no effort + no airflow = central.", "srcItem": "OSA vs CSA: the core difference"},
    {"id": "q-f203-g07-002", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What happens in central sleep apnea?", "choices": ["The airway is open but the brain sends no signal to breathe", "The airway collapses while effort continues", "The tongue blocks the airway", "Effort increases against a closed airway"], "correct": 0, "explanation": "CSA: airflow and effort both stop.", "srcItem": "OSA vs CSA: the core difference"},
    {"id": "q-f203-g07-003", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "An apnea starts central and ends obstructive. How are such patients classified and treated?", "choices": ["As OSA (mixed apnea is an event)", "As CSA", "As normal", "As hypoventilation"], "correct": 0, "explanation": "Patients with predominantly mixed apnea are treated as OSA.", "srcItem": "OSA vs CSA: the core difference"},
    {"id": "q-f203-g07-004", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When is upper-airway narrowing in OSA worst?", "choices": ["During REM sleep and in the supine position", "While awake and upright", "During exercise", "Only in the prone position"], "correct": 0, "explanation": "Hess: worst in REM sleep and supine.", "srcItem": "OSA vs CSA: the core difference"},
    {"id": "q-f203-g07-005", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the strongest predictor of OSA?", "choices": ["Obesity", "Female sex", "Age under 20", "Low blood pressure"], "correct": 0, "explanation": "Deck notes: obesity is the \"strongest predictor\" (most OSA patients BMI > 30).", "srcItem": "Risk factors and symptoms"},
    {"id": "q-f203-g07-006", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What neck size is an OSA risk factor in men?", "choices": ["> 17 inches", "> 12 inches", "> 22 inches", "> 10 inches"], "correct": 0, "explanation": "Large neck: > 17 in (men), > 16 in (women).", "srcItem": "Risk factors and symptoms"},
    {"id": "q-f203-g07-007", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the main cause of central sleep apnea?", "choices": ["Heart failure (Cheyne-Stokes)", "Obesity", "Large tonsils", "Nasal congestion"], "correct": 0, "explanation": "CSA causes: heart failure, CNS disorders, drugs, high altitude; usually not obese.", "srcItem": "Risk factors and symptoms"},
    {"id": "q-f203-g07-008", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which symptom is typical of OSA?", "choices": ["Loud snoring with excessive daytime sleepiness", "No snoring at all", "Weight loss", "Low hemoglobin"], "correct": 0, "explanation": "OSA: loud snoring, witnessed apneas, morning headache, daytime sleepiness.", "srcItem": "Risk factors and symptoms"},
    {"id": "q-f203-g07-009", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the gold standard for diagnosing sleep apnea?", "choices": ["Attended in-lab polysomnography", "Overnight pulse oximetry only", "Spirometry", "Chest radiograph"], "correct": 0, "explanation": "Full-night, attended in-lab PSG.", "srcItem": "Diagnosis: PSG and AHI"},
    {"id": "q-f203-g07-010", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A patient has 100 apneas and hypopneas in 8 hours of sleep. What is the AHI and severity?", "choices": ["12.5/hr — mild", "100/hr — severe", "8/hr — normal", "25/hr — moderate"], "correct": 0, "explanation": "AHI = 100 ÷ 8 = 12.5 → mild (5–15).", "srcItem": "Diagnosis: PSG and AHI"},
    {"id": "q-f203-g07-011", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What AHI defines severe sleep apnea?", "choices": ["> 30 events/hr", "5–15 events/hr", "15–30 events/hr", "< 5 events/hr"], "correct": 0, "explanation": "Mild 5–15, moderate 15–30, severe > 30.", "srcItem": "Diagnosis: PSG and AHI"},
    {"id": "q-f203-g07-012", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "OSA is confirmed in a symptomatic patient at what AHI?", "choices": ["≥ 5/hr", "≥ 30/hr", "≥ 1/hr", "≥ 50/hr"], "correct": 0, "explanation": "AHI ≥ 5 with symptoms, or ≥ 15 asymptomatic, with 75% obstructive events.", "srcItem": "Diagnosis: PSG and AHI"},
    {"id": "q-f203-g07-013", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the first-line therapy for OSA?", "choices": ["CPAP", "Respiratory stimulants", "Supplemental O₂ alone", "Theophylline"], "correct": 0, "explanation": "CPAP splints the airway open; behavior modification is the first step.", "srcItem": "Treatment: OSA vs CSA"},
    {"id": "q-f203-g07-014", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the first step in treating central sleep apnea?", "choices": ["Treat the underlying cause such as CHF", "Weight loss only", "Surgery on the palate", "Oral appliance"], "correct": 0, "explanation": "Treat the cause first; then CPAP/BiPAP or ASV if CSA persists.", "srcItem": "Treatment: OSA vs CSA"},
    {"id": "q-f203-g07-015", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A patient cannot tolerate CPAP for OSA. What can be tried?", "choices": ["Other masks, humidification, ramp, auto-titration, pressure relief or BiPAP", "Stop all therapy", "Oxygen only", "Increase CPAP to 25"], "correct": 0, "explanation": "RCP 203 lists these options for CPAP intolerance.", "srcItem": "Treatment: OSA vs CSA"},
    {"id": "q-f203-g07-016", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What AHI on therapy indicates optimum CPAP control?", "choices": ["< 5/hr", "< 30/hr", "< 15/hr", "< 50/hr"], "correct": 0, "explanation": "RCP 203: optimum control = AHI < 5/hr.", "srcItem": "Treatment: OSA vs CSA"},
    {"id": "q-f203-g07-017", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which respiratory stimulants are listed for CSA?", "choices": ["Acetazolamide and theophylline", "Albuterol and ipratropium", "Morphine and fentanyl", "Midazolam and propofol"], "correct": 0, "explanation": "Stimulants: acetazolamide, theophylline; O₂ reduces desaturation only.", "srcItem": "Treatment: OSA vs CSA"},
    {"id": "q-f203-g07-018", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does Spaulding's classification base equipment processing on?", "choices": ["Where the item goes in the patient", "The cost of the item", "The item's color", "How often it is used"], "correct": 0, "explanation": "Critical → sterilize; semicritical → HLD; noncritical → clean/low-level.", "srcItem": "Sterilization vs Disinfection, and the Spaulding Categories"},
    {"id": "q-f203-g07-019", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Most respiratory equipment that touches mucous membranes is classified as what?", "choices": ["Semicritical — high-level disinfection or sterilization", "Critical", "Noncritical", "Disposable only"], "correct": 0, "explanation": "E.g. bronchoscopes.", "srcItem": "Sterilization vs Disinfection, and the Spaulding Categories"},
    {"id": "q-f203-g07-020", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does sterilization differ from high-level disinfection?", "choices": ["Sterilization destroys all organisms including spores; HLD may leave spores", "They are identical", "HLD kills more organisms", "Sterilization leaves spores"], "correct": 0, "explanation": "High-level disinfection is not sterilization.", "srcItem": "Sterilization vs Disinfection, and the Spaulding Categories"},
    {"id": "q-f203-g07-021", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What must always come before disinfection or sterilization?", "choices": ["Cleaning", "Drying", "Wrapping", "Labeling"], "correct": 0, "explanation": "Residue interferes with both.", "srcItem": "Sterilization vs Disinfection, and the Spaulding Categories"},
    {"id": "q-f203-g07-022", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which item is noncritical?", "choices": ["A blood pressure cuff", "Bronchoscope biopsy forceps", "A chest tube", "A bronchoscope"], "correct": 0, "explanation": "Noncritical items touch intact skin.", "srcItem": "Sterilization vs Disinfection, and the Spaulding Categories"},
    {"id": "q-f203-g07-023", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Does pasteurization sterilize equipment?", "choices": ["No — it is hot-water disinfection", "Yes — it kills spores", "Yes — at 30 °C", "Only for metal"], "correct": 0, "explanation": "Hess: about 70 °C for 30 minutes; some bacteria may survive.", "srcItem": "Pasteurization vs Autoclave vs Isopropyl Alcohol vs Chlorhexidine"},
    {"id": "q-f203-g07-024", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What are autoclave conditions per Hess?", "choices": ["121 °C for 30 min or 132 °C for 4 min at 15 psi", "70 °C for 30 min", "37 °C for 24 h", "200 °C for 1 min"], "correct": 0, "explanation": "Saturated steam under pressure; sporicidal; fast, cheap, nontoxic.", "srcItem": "Pasteurization vs Autoclave vs Isopropyl Alcohol vs Chlorhexidine"},
    {"id": "q-f203-g07-025", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is isopropyl alcohol suitable for?", "choices": ["Skin before injections, vial tops, stethoscopes", "Sterilizing bronchoscopes", "Killing spores", "Cleaning rubber circuits long term"], "correct": 0, "explanation": "It doesn't kill spores and may damage rubber and plastic.", "srcItem": "Pasteurization vs Autoclave vs Isopropyl Alcohol vs Chlorhexidine"},
    {"id": "q-f203-g07-026", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What is the difference between an antiseptic and a disinfectant?", "choices": ["An antiseptic is used on living tissue; a disinfectant on equipment", "They are identical", "A disinfectant is used on skin", "An antiseptic sterilizes equipment"], "correct": 0, "explanation": "Chlorhexidine is an antiseptic (skin prep, oral care), not an equipment process.", "srcItem": "Pasteurization vs Autoclave vs Isopropyl Alcohol vs Chlorhexidine"},
    {"id": "q-f203-g07-027", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How long does glutaraldehyde (Cidex) take for high-level disinfection and for sterilization?", "choices": ["20 minutes for HLD; 10 hours for sterilization", "2 minutes for both", "24 hours for HLD", "1 hour for sterilization"], "correct": 0, "explanation": "Use the deck's 10 hours (Hess 6–10); rinse with sterile water.", "srcItem": "Other Methods"},
    {"id": "q-f203-g07-028", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which agent is used for low-temperature gas sterilization but is toxic, flammable and needs long aeration?", "choices": ["Ethylene oxide", "Isopropyl alcohol", "Glutaraldehyde", "Bleach"], "correct": 0, "explanation": "ETO items need 8–24 hours of aeration.", "srcItem": "Other Methods"},
    {"id": "q-f203-g07-029", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the deck say to use for C. difficile (spores)?", "choices": ["An EPA-registered sporicidal disinfectant", "Isopropyl alcohol", "Soap and water only", "Pasteurization"], "correct": 0, "explanation": "Hess: 1:10 dilution of 5.25% bleach; never mix bleach with acid.", "srcItem": "Other Methods"},
    {"id": "q-f203-g07-030", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which high-level disinfectant has a 12-minute exposure and doesn't irritate eyes or nose?", "choices": ["OPA (ortho-phthalaldehyde)", "Glutaraldehyde", "Ethylene oxide", "Bleach"], "correct": 0, "explanation": "Hess: OPA sterilizes or gives HLD.", "srcItem": "Other Methods"},
    {"id": "q-f203-g07-031", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "When is the Apgar score taken?", "choices": ["At 1 and 5 minutes after birth", "Only at 10 minutes", "Before delivery", "At 24 hours"], "correct": 0, "explanation": "A 10-minute score if the 5-minute score is < 7.", "srcItem": "APGAR Score"},
    {"id": "q-f203-g07-032", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What Apgar score is normal per the deck?", "choices": ["7–10", "4–6", "0–3", "10 only"], "correct": 0, "explanation": "4–6 moderately depressed; 0–3 severely depressed.", "srcItem": "APGAR Score"},
    {"id": "q-f203-g07-033", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A newborn has HR 90, weak irregular breathing, pink body with blue extremities, a grimace and some flexion. What is the Apgar?", "choices": ["5", "3", "7", "10"], "correct": 0, "explanation": "HR < 100 = 1, weak effort = 1, acrocyanosis = 1, grimace = 1, some flexion = 1.", "srcItem": "APGAR Score"},
    {"id": "q-f203-g07-034", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Should resuscitation be delayed to obtain the Apgar score?", "choices": ["No — never delay interventions for the score", "Yes — score first", "Only for preterm infants", "Only at 1 minute"], "correct": 0, "explanation": "The Apgar does not decide whether resuscitation starts.", "srcItem": "APGAR Score"},
    {"id": "q-f203-g07-035", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How many points does a heart rate above 100/min receive?", "choices": ["2", "1", "0", "3"], "correct": 0, "explanation": "None = 0; < 100 = 1; > 100 = 2.", "srcItem": "APGAR Score"},
    {"id": "q-f203-g07-036", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which is an indication for home apnea monitoring (Hess Box 48-2)?", "choices": ["Methylxanthine treatment at home", "A healthy term newborn", "Routine SIDS prevention in all infants", "A cold"], "correct": 0, "explanation": "Also GERD with apnea, documented ALTE, central apnea risk, sibling SIDS death.", "srcItem": "Home Apnea Monitoring: Conditions Requiring It"},
    {"id": "q-f203-g07-037", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Does the AAP recommend home apnea monitoring to prevent SIDS?", "choices": ["No", "Yes, for all infants", "Yes, for premature infants only", "Yes, for twins only"], "correct": 0, "explanation": "Trap: the AAP does not recommend monitors to prevent SIDS.", "srcItem": "Home Apnea Monitoring: Conditions Requiring It"},
    {"id": "q-f203-g07-038", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What do caregivers learn for home apnea monitoring?", "choices": ["CPR, stimulation, lead placement and alarm response", "How to intubate", "How to give IV drugs", "Nothing"], "correct": 0, "explanation": "Hess Ch 48.", "srcItem": "Home Apnea Monitoring: Conditions Requiring It"},
    {"id": "q-f203-g07-039", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How does a home apnea monitor detect breathing?", "choices": ["Chest-wall movement by electrical impedance", "Airflow at the nose", "Exhaled CO₂", "Pulse oximetry only"], "correct": 0, "explanation": "It cannot detect obstructive apnea because the chest keeps moving.", "srcItem": "How the Monitor Works, Alarm Settings and Apnea Definitions"},
    {"id": "q-f203-g07-040", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What apnea alarm time is used on a home monitor?", "choices": ["15–20 seconds", "2 seconds", "60 seconds", "5 minutes"], "correct": 0, "explanation": "Heart rate alarms for neonates 80–210/min.", "srcItem": "How the Monitor Works, Alarm Settings and Apnea Definitions"},
    {"id": "q-f203-g07-041", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "How is pathologic apnea defined?", "choices": ["> 20 seconds, or with cyanosis, pallor, hypotonia or bradycardia", "Any pause over 3 seconds", "< 10 seconds of central apnea", "Periodic breathing"], "correct": 0, "explanation": "< 10 s central apnea can be normal.", "srcItem": "How the Monitor Works, Alarm Settings and Apnea Definitions"},
    {"id": "q-f203-g07-042", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where are the monitor's chest sensors placed?", "choices": ["Right and left chest, midway between the nipple line and midaxillary line", "On the abdomen only", "On the back", "On the forehead"], "correct": 0, "explanation": "That's where chest motion is greatest.", "srcItem": "How the Monitor Works, Alarm Settings and Apnea Definitions"},
    {"id": "q-f203-g07-043", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A newborn is not breathing well 30 seconds after birth. What is the most effective intervention?", "choices": ["Positive-pressure ventilation by face mask", "Waiting for the Apgar", "Intubation immediately", "Epinephrine first"], "correct": 0, "explanation": "PPV is the most effective intervention; PEEP ≤ 5.", "srcItem": "Neonatal Resuscitation in the Delivery Room, and Pre- vs Post-Ductal S"},
    {"id": "q-f203-g07-044", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What heart rate always requires CPR in a neonate?", "choices": ["< 60/min", "< 100/min", "< 120/min", "< 140/min"], "correct": 0, "explanation": "Then epinephrine and consider intubation if no response.", "srcItem": "Neonatal Resuscitation in the Delivery Room, and Pre- vs Post-Ductal S"},
    {"id": "q-f203-g07-045", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Where is a pre-ductal SpO₂ measured?", "choices": ["The right hand or wrist", "The left foot", "The left hand", "The abdomen"], "correct": 0, "explanation": "Post-ductal: a lower extremity, usually the left foot.", "srcItem": "Neonatal Resuscitation in the Delivery Room, and Pre- vs Post-Ductal S"},
    {"id": "q-f203-g07-046", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A neonate's post-ductal SpO₂ is 12% lower than pre-ductal. What does this suggest?", "choices": ["Marked pulmonary hypertension with R→L shunting (e.g. PPHN)", "Normal transition", "A probe error only", "Left-to-right shunt"], "correct": 0, "explanation": "≥ 10% gap suggests marked pulmonary hypertension; > 3–5% needs evaluation.", "srcItem": "Neonatal Resuscitation in the Delivery Room, and Pre- vs Post-Ductal S"},
    {"id": "q-f203-g07-047", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What O₂ should resuscitation of a preterm infant < 35 weeks start with?", "choices": ["Low O₂ (21–30%), titrated to preductal SpO₂", "100% O₂", "No O₂ ever", "50% O₂ fixed"], "correct": 0, "explanation": "Titrate to preductal SpO₂ targets.", "srcItem": "Neonatal Resuscitation in the Delivery Room, and Pre- vs Post-Ductal S"},
    {"id": "q-f203-g07-048", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which score estimates a newborn's gestational age?", "choices": ["Ballard", "Apgar", "Silverman", "Glasgow"], "correct": 0, "explanation": "Ballard: neuromuscular + physical maturity; assess by 12 hours.", "srcItem": "The Four Scores Side by Side"},
    {"id": "q-f203-g07-049", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "For which score does a HIGHER value mean worse condition?", "choices": ["Silverman", "Apgar", "Glasgow", "Ballard"], "correct": 0, "explanation": "Exam trap: Silverman runs opposite to Apgar and GCS.", "srcItem": "The Four Scores Side by Side"},
    {"id": "q-f203-g07-050", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What does the Silverman score measure?", "choices": ["The magnitude of an infant's respiratory distress", "Level of consciousness", "Gestational age", "Newborn condition at 1 minute"], "correct": 0, "explanation": "Five signs graded 0–2 each.", "srcItem": "The Four Scores Side by Side"},
    {"id": "q-f203-g07-051", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "A GCS of 8 means what?", "choices": ["Severe — consider intubation for airway protection", "Mild", "Moderate", "Normal"], "correct": 0, "explanation": "Mild 13–15, moderate 9–12, severe ≤ 8.", "srcItem": "Glasgow Coma Scale"},
    {"id": "q-f203-g07-052", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What range does the GCS have in an intubated patient?", "choices": ["2T–10T", "3–15", "0–10", "1–6"], "correct": 0, "explanation": "Verbal cannot be tested when intubated.", "srcItem": "Glasgow Coma Scale"},
    {"id": "q-f203-g07-053", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which GCS component is the best predictor of neurologic outcome?", "choices": ["Motor response", "Eye opening", "Verbal response", "Pupils"], "correct": 0, "explanation": "Motor response.", "srcItem": "Glasgow Coma Scale"},
    {"id": "q-f203-g07-054", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Ch 11 says GCS ≤ 8 is a reason to avoid what?", "choices": ["CPAP to treat cardiogenic pulmonary edema", "Oxygen therapy", "Suctioning", "Chest radiographs"], "correct": 0, "explanation": "These patients often can't protect the airway.", "srcItem": "Glasgow Coma Scale"},
    {"id": "q-f203-g07-055", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On the New Ballard score, what does a score of 40 mean?", "choices": ["40 weeks' gestation", "40% risk", "Severe distress", "4 kg weight"], "correct": 0, "explanation": "< 40 = preterm; > 40 = post-term.", "srcItem": "Ballard Score"},
    {"id": "q-f203-g07-056", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which signs make up the Ballard score?", "choices": ["Neuromuscular and physical maturity signs", "Heart rate and respirations", "Retractions and grunting", "Eye, verbal and motor responses"], "correct": 0, "explanation": "E.g. posture, square window, skin, lanugo, plantar surface.", "srcItem": "Ballard Score"},
    {"id": "q-f203-g07-057", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Does the instructor expect RTs to perform the Ballard exam?", "choices": ["No — just know what it is, what it evaluates and what it tells you", "Yes, on every newborn", "Yes, at 1 and 5 minutes", "Only in the NICU"], "correct": 0, "explanation": "RTs normally don't perform it.", "srcItem": "Ballard Score"},
    {"id": "q-f203-g07-058", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "Which signs are graded on the Silverman score?", "choices": ["Upper chest, lower chest retraction, xiphoid retraction, nares dilation, expiratory grunt", "Color, tone, reflex, pulse, respirations", "Eyes, verbal, motor", "Skin, lanugo, posture"], "correct": 0, "explanation": "Graded 0–2 each.", "srcItem": "Silverman Score"},
    {"id": "q-f203-g07-059", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "On the Silverman score, an expiratory grunt heard with the naked ear grades as what?", "choices": ["2", "1", "0", "3"], "correct": 0, "explanation": "Stethoscope only = 1; naked ear = 2.", "srcItem": "Silverman Score"},
    {"id": "q-f203-g07-060", "topic": "f203-g07", "course": "rcp203f", "pool": "both", "difficulty": 2, "q": "What Silverman-Anderson score indicates impending respiratory failure (Heuer)?", "choices": ["7 or higher", "1–2", "0", "3–4"], "correct": 0, "explanation": "0 = no distress; 1–6 mild to moderate; ≥ 7 impending failure.", "srcItem": "Silverman Score"}
